def normalize_role(role: Any) -> str:
    clean = str(role or "").strip().lower().replace("-", "_")
    clean = " ".join(clean.split())
    clean = clean.replace(" ", "_") if clean not in ROLE_ALIASES else clean
    return ROLE_ALIASES.get(clean, clean)


class CursorAdapter:
    def __init__(self, cursor: psycopg.Cursor[DbRow]):
        self.cursor = cursor

    def fetchone(self) -> DbRow | None:
        return self.cursor.fetchone()

    def fetchall(self) -> list[DbRow]:
        return list(self.cursor.fetchall())


class Database:
    def __init__(self) -> None:
        if not DATABASE_URL:
            raise RuntimeError("DATABASE_URL is required. Attach a PostgreSQL database and set DATABASE_URL.")
        self._slot_acquired = DATABASE_CONNECTION_SEMAPHORE.acquire(timeout=DATABASE_CONNECT_TIMEOUT_SECONDS)
        if not self._slot_acquired:
            raise RuntimeError("Database is busy; no application connection slot became available")
        try:
            self.raw = psycopg.connect(
                DATABASE_URL,
                row_factory=dict_row,
                connect_timeout=DATABASE_CONNECT_TIMEOUT_SECONDS,
                application_name="faircroft-rp-os",
            )
        except Exception:
            DATABASE_CONNECTION_SEMAPHORE.release()
            self._slot_acquired = False
            raise

    def __enter__(self) -> "Database":
        return self

    def __exit__(self, exc_type: Any, exc: Any, tb: Any) -> None:
        try:
            if exc_type:
                self.raw.rollback()
            else:
                self.raw.commit()
        finally:
            self.raw.close()
            if self._slot_acquired:
                DATABASE_CONNECTION_SEMAPHORE.release()
                self._slot_acquired = False

    def sql(self, query: str) -> str:
        return query.replace("?", "%s")

    def execute(self, query: str, params: tuple[Any, ...] | list[Any] = ()) -> CursorAdapter:
        cursor = self.raw.cursor()
        cursor.execute(self.sql(query), tuple(params))
        return CursorAdapter(cursor)

    def executemany(self, query: str, params: list[tuple[Any, ...]]) -> CursorAdapter:
        cursor = self.raw.cursor()
        cursor.executemany(self.sql(query), params)
        return CursorAdapter(cursor)

    def executescript(self, script: str) -> None:
        cursor = self.raw.cursor()
        for statement in [part.strip() for part in script.split(";") if part.strip()]:
            cursor.execute(statement)


def conn() -> Database:
    return Database()


def one(db: Database, sql: str, params: tuple[Any, ...] = ()) -> DbRow | None:
    return db.execute(sql, params).fetchone()


def all_rows(db: Database, sql: str, params: tuple[Any, ...] = ()) -> list[DbRow]:
    return db.execute(sql, params).fetchall()


def has_shadowhaven_sftp_credentials() -> bool:
    return bool(
        SHADOWHAVEN_SFTP_HOST
        and SHADOWHAVEN_SFTP_USERNAME
        and SHADOWHAVEN_SFTP_PASSWORD
    )


def _shadowhaven_sftp_private_key_text() -> str:
    if SHADOWHAVEN_SFTP_PRIVATE_KEY_B64:
        try:
            return base64.b64decode(SHADOWHAVEN_SFTP_PRIVATE_KEY_B64).decode("utf-8").replace("\r\n", "\n")
        except Exception as exc:
            raise RuntimeError(f"SFTP private key base64 could not be decoded: {exc}") from exc
    key_value = (SHADOWHAVEN_SFTP_PRIVATE_KEY or "").strip()
    if not key_value:
        return ""
    if (key_value.startswith('"') and key_value.endswith('"')) or (key_value.startswith("'") and key_value.endswith("'")):
        key_value = key_value[1:-1].strip()
    if "BEGIN " in key_value:
        return key_value.replace("\\n", "\n").replace("\r\n", "\n")
    key_path = Path(key_value)
    if key_path.exists() and key_path.is_file():
        return key_path.read_text(encoding="utf-8")
    return key_value.replace("\\n", "\n")


def _load_shadowhaven_sftp_private_key() -> paramiko.PKey | None:
    key_text = _shadowhaven_sftp_private_key_text()
    if not key_text:
        return None
    passphrase = SHADOWHAVEN_SFTP_PRIVATE_KEY_PASSPHRASE or None
    key_errors: list[str] = []
    key_types = [
        key_type
        for key_type in (
            getattr(paramiko, "Ed25519Key", None),
            getattr(paramiko, "RSAKey", None),
            getattr(paramiko, "ECDSAKey", None),
            getattr(paramiko, "DSSKey", None),
        )
        if key_type is not None
    ]
    for key_type in key_types:
        try:
            return key_type.from_private_key(io.StringIO(key_text), password=passphrase)
        except Exception as exc:
            key_errors.append(f"{key_type.__name__}: {exc}")
    raise RuntimeError("SFTP private key could not be loaded: " + " | ".join(key_errors))


class ShadowhavenTransport(paramiko.Transport):
    """Serialize hosted SFTP sessions and release the slot with the transport."""

    def __init__(self, *args: Any, **kwargs: Any) -> None:
        SHADOWHAVEN_SFTP_SESSION_SEMAPHORE.acquire()
        self._shadowhaven_slot_released = False
        try:
            super().__init__(*args, **kwargs)
        except Exception:
            self._release_shadowhaven_slot()
            raise

    def _release_shadowhaven_slot(self) -> None:
        if not self._shadowhaven_slot_released:
            self._shadowhaven_slot_released = True
            SHADOWHAVEN_SFTP_SESSION_SEMAPHORE.release()

    def close(self) -> None:
        try:
            super().close()
        finally:
            self._release_shadowhaven_slot()


def connect_shadowhaven_transport() -> paramiko.Transport:
    if not SHADOWHAVEN_SFTP_PASSWORD:
        raise RuntimeError("SFTP password login is required")
    last_error: Exception | None = None
    for attempt in range(3):
        transport = ShadowhavenTransport((SHADOWHAVEN_SFTP_HOST, SHADOWHAVEN_SFTP_PORT))
        try:
            transport.connect(username=SHADOWHAVEN_SFTP_USERNAME, password=SHADOWHAVEN_SFTP_PASSWORD)
            return transport
        except paramiko.AuthenticationException as exc:
            last_error = exc
            transport.close()
            if attempt < 2:
                time.sleep(1 + attempt)
        except Exception:
            transport.close()
            raise
    raise paramiko.AuthenticationException(
        "Shadow Haven rejected the SFTP password after 3 serialized attempts"
    ) from last_error


def extract_shadowhaven_bank_data(payload: Any) -> tuple[dict[str, Any], str]:
    if not isinstance(payload, dict):
        return {}, ""
    source_saved_at = str(payload.get("m_iLastSaved") or "")
    components = payload.get("m_aComponents")
    if not isinstance(components, list):
        return {}, source_saved_at
    for component in components:
        if not isinstance(component, dict) or component.get("_type") != "BankManagerComponent":
            continue
        data = component.get("m_pData")
        if isinstance(data, dict) and isinstance(data.get("m_Banks"), dict):
            return data["m_Banks"], source_saved_at
    return {}, source_saved_at


def sync_shadowhaven_bank_once() -> int:
    if not has_shadowhaven_sftp_credentials():
        return 0
    transport = connect_shadowhaven_transport()
    try:
        sftp = paramiko.SFTPClient.from_transport(transport)
        try:
            try:
                with sftp.open(SHADOWHAVEN_BANK_FILE, "r") as remote_file:
                    payload = json.loads(remote_file.read().decode("utf-8-sig"))
            except FileNotFoundError as exc:
                raise FileNotFoundError(
                    f"Remote bank file not found: {SHADOWHAVEN_BANK_FILE}"
                ) from exc
        finally:
            sftp.close()
    finally:
        transport.close()

    balances, source_saved_at = extract_shadowhaven_bank_data(payload)
    if not balances:
        raise RuntimeError("BankManagerComponent contained no balances")
    synced_at = now_iso()
    accepted = 0
    with conn() as db:
        for identity_id, raw_balance in balances.items():
            identity = str(identity_id or "").strip()[:160]
            if not identity:
                continue
            try:
                balance = round(float(raw_balance or 0), 2)
            except (TypeError, ValueError):
                continue
            db.execute(
                """
                INSERT INTO arma_game_bank_balances
                (identity_id, balance, source_file, source_saved_at, raw_payload, synced_at)
                VALUES (?, ?, ?, ?, ?, ?)
                ON CONFLICT (identity_id) DO UPDATE SET
                    balance = EXCLUDED.balance,
                    source_file = EXCLUDED.source_file,
                    source_saved_at = EXCLUDED.source_saved_at,
                    raw_payload = EXCLUDED.raw_payload,
                    synced_at = EXCLUDED.synced_at
                """,
                (
                    identity,
                    balance,
                    SHADOWHAVEN_BANK_FILE[:255],
                    source_saved_at[:80],
                    json.dumps({"balance": balance}),
                    synced_at,
                ),
            )
            db.execute(
                """
                INSERT INTO leaderboard_metric_snapshots
                (metric_key, subject_key, snapshot_day, metric_value, captured_at)
                VALUES ('bank_balance', ?, ?, ?, ?)
                ON CONFLICT (metric_key, subject_key, snapshot_day) DO UPDATE SET
                    metric_value = EXCLUDED.metric_value,
                    captured_at = EXCLUDED.captured_at
                """,
                (identity, today_key(), balance, synced_at),
            )
            accepted += 1
    return accepted


