def faircroft_credit_snapshot(reputation: int | None) -> dict[str, Any]:
    if reputation is None:
        return {
            "score": None, "rating": "Awaiting reputation sync",
            "reputation": None, "reputation_max": 2000, "progress": 0,
        }
    normalized = max(0, min(2000, int(reputation)))
    score = round(300 + (normalized / 2000) * 550)
    if score >= 800:
        rating = "Exceptional"
    elif score >= 740:
        rating = "Very good"
    elif score >= 670:
        rating = "Good"
    elif score >= 580:
        rating = "Fair"
    else:
        rating = "Building"
    return {
        "score": score,
        "rating": rating,
        "reputation": normalized,
        "reputation_max": 2000,
        "progress": round((score - 300) / 550 * 100, 1),
    }


def sync_shadowhaven_anticheat_once() -> tuple[int, int]:
    if not has_shadowhaven_sftp_credentials():
        return 0, 0
    transport = connect_shadowhaven_transport()
    try:
        sftp = paramiko.SFTPClient.from_transport(transport)
        try:
            with sftp.open(SHADOWHAVEN_ANTICHEAT_DATABASE_FILE, "r") as remote_file:
                player_payload = json.loads(remote_file.read().decode("utf-8-sig"))
            with sftp.open(SHADOWHAVEN_ANTICHEAT_ALT_FILE, "r") as remote_file:
                alt_payload = json.loads(remote_file.read().decode("utf-8-sig"))
        finally:
            sftp.close()
    finally:
        transport.close()

    players = player_payload.get("players", []) if isinstance(player_payload, dict) else []
    groups = alt_payload.get("groups", []) if isinstance(alt_payload, dict) else []
    if not isinstance(players, list) or not isinstance(groups, list):
        raise RuntimeError("Thunder Buddies Anti-Cheat JSON has an invalid structure")

    synced_at = now_iso()
    accepted_players = 0
    accepted_groups = 0
    active_json_locked_uids: set[str] = set()
    current_json_uids: set[str] = set()
    with conn() as db:
        db.execute("DELETE FROM anticheat_events WHERE source_file = ?", (SHADOWHAVEN_ANTICHEAT_DATABASE_FILE[:255],))
        for player in players:
            if not isinstance(player, dict):
                continue
            uid = str(player.get("playerUID") or "").strip()[:160]
            if not uid:
                continue
            current_json_uids.add(uid)
            profile_locked = 1 if player.get("profileLocked") is True else 0
            grey_screened = 1 if player.get("greyScreened") is True else 0
            grey_screen_reason = str(player.get("greyScreenReason") or "")[:500]
            grey_screened_at = str(player.get("greyScreenedAt") or "")[:100]
            grey_screen_teleport_hits = int(player.get("greyScreenTeleportHits") or 0)
            grey_screen_evidence = str(player.get("greyScreenEvidence") or "")[:4000]
            db.execute(
                """
                INSERT INTO anticheat_players
                (uid, player_name, reported_system, is_online, last_seen_at, teleport_flags, aim_flags, ticket_count,
                 profile_locked, grey_screened, grey_screen_reason, grey_screened_at, grey_screen_teleport_hits,
                 grey_screen_evidence, raw_payload, source_file, first_synced_at, last_synced_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                ON CONFLICT (uid) DO UPDATE SET
                    player_name = EXCLUDED.player_name,
                    reported_system = CASE
                        WHEN EXCLUDED.reported_system <> '' THEN EXCLUDED.reported_system
                        ELSE anticheat_players.reported_system
                    END,
                    is_online = EXCLUDED.is_online,
                    last_seen_at = EXCLUDED.last_seen_at,
                    teleport_flags = EXCLUDED.teleport_flags,
                    aim_flags = EXCLUDED.aim_flags,
                    ticket_count = EXCLUDED.ticket_count,
                    profile_locked = EXCLUDED.profile_locked,
                    grey_screened = EXCLUDED.grey_screened,
                    grey_screen_reason = EXCLUDED.grey_screen_reason,
                    grey_screened_at = EXCLUDED.grey_screened_at,
                    grey_screen_teleport_hits = EXCLUDED.grey_screen_teleport_hits,
                    grey_screen_evidence = EXCLUDED.grey_screen_evidence,
                    raw_payload = EXCLUDED.raw_payload,
                    source_file = EXCLUDED.source_file,
                    last_synced_at = EXCLUDED.last_synced_at
                """,
                (
                    uid,
                    str(player.get("playerName") or "Unknown")[:120],
                    str(
                        player.get("platform")
                        or player.get("playerPlatform")
                        or player.get("platformName")
                        or player.get("system")
                        or player.get("deviceType")
                        or ""
                    ).strip()[:80],
                    1 if player.get("online") is True else 0,
                    str(player.get("lastSeen") or "")[:80],
                    int(player.get("teleportFlags") or 0),
                    int(player.get("aimFlags") or 0),
                    int(player.get("ticketCount") or 0),
                    profile_locked,
                    grey_screened,
                    grey_screen_reason,
                    grey_screened_at,
                    grey_screen_teleport_hits,
                    grey_screen_evidence,
                    json.dumps(player, separators=(",", ":"), default=str)[:20000],
                    SHADOWHAVEN_ANTICHEAT_DATABASE_FILE[:255],
                    synced_at,
                    synced_at,
                ),
            )
            if profile_locked or grey_screened:
                active_json_locked_uids.add(uid)
                upsert_anticheat_profile_lock(
                    db,
                    uid,
                    str(player.get("playerName") or "Unknown")[:120],
                    grey_screen_reason or "Thunder Buddies Anti-Cheat grey screen",
                    grey_screen_evidence or json.dumps(player, separators=(",", ":"), default=str)[:4000],
                    grey_screened_at or synced_at,
                    "shadowhaven-json-sync",
                )
            for event in player.get("events", []) if isinstance(player.get("events"), list) else []:
                if not isinstance(event, dict):
                    continue
                event_type = str(event.get("type") or "unknown")[:80]
                event_time = str(event.get("time") or "")[:100]
                details = str(event.get("details") or "")[:4000]
                fingerprint = hashlib.sha256(
                    f"{uid}\x1f{event_type}\x1f{event_time}\x1f{details}".encode("utf-8")
                ).hexdigest()
                db.execute(
                    """
                    INSERT INTO anticheat_events
                    (event_fingerprint, player_uid, event_type, event_time, details,
                     source_file, first_synced_at, last_synced_at)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                    ON CONFLICT (event_fingerprint) DO UPDATE SET last_synced_at = EXCLUDED.last_synced_at
                    """,
                    (fingerprint, uid, event_type, event_time, details,
                     SHADOWHAVEN_ANTICHEAT_DATABASE_FILE[:255], synced_at, synced_at),
                )
            accepted_players += 1

        for group in groups:
            if not isinstance(group, dict):
                continue
            group_key = str(group.get("groupKey") or "").strip()[:180]
            if not group_key:
                continue
            db.execute(
                """
                INSERT INTO anticheat_alt_groups
                (group_key, note, first_seen, last_seen, raw_payload, last_synced_at)
                VALUES (?, ?, ?, ?, ?, ?)
                ON CONFLICT (group_key) DO UPDATE SET
                    note = EXCLUDED.note, first_seen = EXCLUDED.first_seen,
                    last_seen = EXCLUDED.last_seen, raw_payload = EXCLUDED.raw_payload,
                    last_synced_at = EXCLUDED.last_synced_at
                """,
                (
                    group_key, str(group.get("note") or "")[:2000],
                    str(group.get("firstSeen") or "")[:100], str(group.get("lastSeen") or "")[:100],
                    json.dumps(group, separators=(",", ":"), default=str)[:20000], synced_at,
                ),
            )
            uids = group.get("uids") if isinstance(group.get("uids"), list) else []
            names = group.get("names") if isinstance(group.get("names"), list) else []
            for index, raw_uid in enumerate(uids):
                member_uid = str(raw_uid or "").strip()[:160]
                if not member_uid:
                    continue
                observed_name = str(names[index] if index < len(names) else "")[:120]
                db.execute(
                    """
                    INSERT INTO anticheat_alt_members (group_key, uid, observed_name, last_synced_at)
                    VALUES (?, ?, ?, ?)
                    ON CONFLICT (group_key, uid) DO UPDATE SET
                        observed_name = EXCLUDED.observed_name,
                        last_synced_at = EXCLUDED.last_synced_at
                    """,
                    (group_key, member_uid, observed_name, synced_at),
                )
            accepted_groups += 1

        prune_anticheat_players_absent_from_json(db, current_json_uids)
        clear_anticheat_locks_absent_from_json(db, active_json_locked_uids, synced_at)

        for source_key, source_path, records in (
            ("players", SHADOWHAVEN_ANTICHEAT_DATABASE_FILE, accepted_players),
            ("alt_accounts", SHADOWHAVEN_ANTICHEAT_ALT_FILE, accepted_groups),
        ):
            db.execute(
                """
                INSERT INTO anticheat_sync_status
                (source_key, source_path, status, records, last_success_at, last_error, updated_at)
                VALUES (?, ?, 'synced', ?, ?, '', ?)
                ON CONFLICT (source_key) DO UPDATE SET
                    source_path = EXCLUDED.source_path, status = EXCLUDED.status,
                    records = EXCLUDED.records, last_success_at = EXCLUDED.last_success_at,
                    last_error = '', updated_at = EXCLUDED.updated_at
                """,
                (source_key, source_path[:255], records, synced_at, synced_at),
            )
    return accepted_players, accepted_groups


def shadowhaven_anticheat_sync_worker() -> None:
    if not has_shadowhaven_sftp_credentials():
        print("Shadowhaven SFTP anti-cheat sync disabled: credentials are not configured")
        return
    while True:
        try:
            players, groups = sync_shadowhaven_anticheat_once()
            print(f"Shadowhaven SFTP anti-cheat sync updated {players} player(s), {groups} alt group(s)")
        except Exception as exc:
            print(f"Shadowhaven SFTP anti-cheat sync failed: {type(exc).__name__}: {exc}")
        time.sleep(SHADOWHAVEN_ANTICHEAT_SYNC_SECONDS)


PERSISTENCE_CATEGORIES = {
    "Characters", "CopChats", "Criminals", "Items", "PoliceReports",
    "RootEntityCollections", "Turrets", "Vehicles",
}


def persistence_scalar_fields(payload: Any, limit: int = 2000) -> list[tuple[str, str]]:
    fields: list[tuple[str, str]] = []

    def walk(value: Any, path: str, depth: int) -> None:
        if len(fields) >= limit or depth > 16:
            return
        if isinstance(value, dict):
            for key, child in value.items():
                walk(child, f"{path}.{key}" if path else str(key), depth + 1)
        elif isinstance(value, list):
            for index, child in enumerate(value[:500]):
                walk(child, f"{path}[{index}]", depth + 1)
        elif value is not None and not isinstance(value, bool):
            text = str(value).strip()
            if text:
                fields.append((path, text[:1000]))

    walk(payload, "", 0)
    return fields


def summarize_persistence_record(category: str, record_id: str, payload: Any) -> dict[str, Any]:
    fields = persistence_scalar_fields(payload)
    lowered = [(path.lower(), value) for path, value in fields]

    def first_value(*needles: str) -> str:
        for path, value in lowered:
            leaf = path.rsplit(".", 1)[-1]
            if any(needle in leaf for needle in needles):
                return value
        return ""

    identity_values: list[str] = []
    for path, value in lowered:
        leaf = path.rsplit(".", 1)[-1]
        if any(key in leaf for key in (
            "identity", "playeruid", "player_uid", "playerid", "player_id",
            "owneruid", "owner_uid", "ownerid", "owner_id", "bohemia",
            "characterid", "character_id", "persistentid", "persistent_id", "pid",
        )):
            if value not in identity_values:
                identity_values.append(value[:180])

    component_types: list[str] = []
    for path, value in fields:
        if path.lower().endswith("._type") and value not in component_types:
            component_types.append(value[:120])

    prefab = first_value("prefab", "resourcename", "template")
    display_name = first_value("displayname", "itemname", "vehiclename", "charactername", "name", "title")
    owner_id = first_value(
        "owneruid", "owner_uid", "ownerid", "owner_id", "playeruid",
        "player_uid", "playerid", "player_id", "identityid", "identity_id",
        "bohemia", "persistentid", "persistent_id", "pid",
    )
    status = first_value("status", "state")
    amount = first_value("balance", "amount", "value", "price")
    title = display_name or (prefab.rsplit("/", 1)[-1].replace(".et", "") if prefab else "") or f"{category} record"
    return {
        "title": title[:180],
        "prefab": prefab[:500],
        "owner_id": owner_id[:180],
        "status": status[:100],
        "amount": amount[:100],
        "identity_values": identity_values[:40],
        "component_types": component_types[:80],
        "field_count": len(fields),
    }


def upsert_persistence_record_batch(records: list[tuple[Any, ...]]) -> None:
    if not records:
        return
    with conn() as db:
        for record in records:
            db.execute(
                """
                INSERT INTO game_persistence_records
                (source_path, category, record_id, title, owner_identity, identity_values,
                 component_types, prefab, record_status, amount_text, summary_payload,
                 raw_payload, source_modified_at, synced_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                ON CONFLICT (source_path) DO UPDATE SET
                    category = EXCLUDED.category, record_id = EXCLUDED.record_id,
                    title = EXCLUDED.title, owner_identity = EXCLUDED.owner_identity,
                    identity_values = EXCLUDED.identity_values,
                    component_types = EXCLUDED.component_types, prefab = EXCLUDED.prefab,
                    record_status = EXCLUDED.record_status, amount_text = EXCLUDED.amount_text,
                    summary_payload = EXCLUDED.summary_payload, raw_payload = EXCLUDED.raw_payload,
                    source_modified_at = EXCLUDED.source_modified_at, synced_at = EXCLUDED.synced_at
                """,
                record,
            )


def sync_shadowhaven_persistence_once() -> tuple[int, dict[str, int]]:
    if not has_shadowhaven_sftp_credentials():
        return 0, {}
    transport = connect_shadowhaven_transport()
    processed = 0
    category_counts: dict[str, int] = {}
    seen_source_paths: set[str] = set()
    scan_complete = False
    synced_at = now_iso()
    try:
        sftp = paramiko.SFTPClient.from_transport(transport)
        try:
            # The list is reversed because this scanner consumes it with pop().
            # Player-facing collections are deliberately processed before large
            # world/item collections so linked-account data appears immediately.
            category_priority = [
                "Characters", "Vehicles", "Criminals", "PoliceReports",
                "CopChats", "Turrets", "RootEntityCollections", "Items",
            ]
            pending = [
                (f"{SHADOWHAVEN_PERSISTENCE_ROOT}/{category}", category)
                for category in reversed(category_priority)
            ]
            records: list[tuple[Any, ...]] = []
            while pending and processed < SHADOWHAVEN_PERSISTENCE_MAX_FILES:
                remote_path, category = pending.pop()
                try:
                    entries = sftp.listdir_attr(remote_path)
                except OSError:
                    continue
                for entry in entries:
                    if processed >= SHADOWHAVEN_PERSISTENCE_MAX_FILES:
                        break
                    child_path = f"{remote_path}/{entry.filename}"
                    if stat.S_ISDIR(entry.st_mode):
                        pending.append((child_path, category))
                        continue
                    if not entry.filename.lower().endswith(".json"):
                        continue
                    seen_source_paths.add(child_path[:500])
                    if entry.st_size > SHADOWHAVEN_PERSISTENCE_MAX_FILE_BYTES:
                        continue
                    try:
                        with sftp.open(child_path, "r") as remote_file:
                            payload = json.loads(remote_file.read().decode("utf-8-sig"))
                    except (OSError, UnicodeDecodeError, json.JSONDecodeError):
                        continue
                    record_id = entry.filename[:-5][:180]
                    summary = summarize_persistence_record(category, record_id, payload)
                    raw_payload = json.dumps(payload, separators=(",", ":"), default=str)
                    records.append((
                        child_path[:500], category[:80], record_id,
                        summary["title"], summary["owner_id"],
                        json.dumps(summary["identity_values"], separators=(",", ":")),
                        json.dumps(summary["component_types"], separators=(",", ":")),
                        summary["prefab"], summary["status"], summary["amount"],
                        json.dumps(summary, separators=(",", ":")),
                        raw_payload[:250000], str(int(entry.st_mtime or 0)), synced_at,
                    ))
                    processed += 1
                    category_counts[category] = category_counts.get(category, 0) + 1
                    if len(records) >= 100:
                        upsert_persistence_record_batch(records)
                        records.clear()
                        print(
                            f"Shadowhaven FCRPMUSSALO sync progress: "
                            f"{processed} record(s), current category {category}"
                        )
            scan_complete = not pending
        finally:
            sftp.close()
    finally:
        transport.close()

    upsert_persistence_record_batch(records)
    with conn() as db:
        # A complete scan is an authoritative snapshot. Prune files that are no
        # longer present so records from a retired server cannot survive forever.
        if scan_complete:
            if seen_source_paths:
                db.execute(
                    "DELETE FROM game_persistence_records WHERE NOT (source_path = ANY(?))",
                    (list(seen_source_paths),),
                )
            else:
                db.execute("DELETE FROM game_persistence_records")
        db.execute(
            """
            INSERT INTO game_persistence_sync_status
            (source_root, status, records, category_counts, last_success_at, last_error, updated_at)
            VALUES (?, 'synced', ?, ?, ?, '', ?)
            ON CONFLICT (source_root) DO UPDATE SET
                status = 'synced', records = EXCLUDED.records,
                category_counts = EXCLUDED.category_counts,
                last_success_at = EXCLUDED.last_success_at, last_error = '',
                updated_at = EXCLUDED.updated_at
            """,
            (
                SHADOWHAVEN_PERSISTENCE_ROOT[:500], processed,
                json.dumps(category_counts, separators=(",", ":"), sort_keys=True),
                synced_at, synced_at,
            ),
        )
    return processed, category_counts


def shadowhaven_persistence_sync_worker() -> None:
    if not has_shadowhaven_sftp_credentials():
        print("Shadowhaven FCRPMUSSALO sync disabled: credentials are not configured")
        return
    print(
        f"Shadowhaven FCRPMUSSALO sync starting from "
        f"{SHADOWHAVEN_PERSISTENCE_ROOT}"
    )
    while True:
        try:
            records, categories = sync_shadowhaven_persistence_once()
            print(f"Shadowhaven FCRPMUSSALO sync updated {records} record(s): {categories}")
        except Exception as exc:
            print(f"Shadowhaven FCRPMUSSALO sync failed: {type(exc).__name__}: {exc}")
        time.sleep(SHADOWHAVEN_PERSISTENCE_SYNC_SECONDS)


PROPERTY_RECORD_KEYS = {
    "id", "PropertyId", "propertyId", "property_id",
    "OwnerUid", "ownerUid", "owner_identity", "ownerIdentity", "ownerId", "owner_id",
    "GuestUids", "guestUids", "Locked", "locked", "Tenure", "tenure",
    "RentPayments", "rentPayments", "PropertyName", "propertyName", "property_name",
}


def _looks_like_property_record(value: dict[str, Any], source_key: str = "") -> bool:
    if any(key in value for key in ("PropertyId", "propertyId", "property_id", "OwnerUid", "ownerUid")):
        return True
    if source_key.lower().startswith(("auto_house", "house_", "property_")):
        return True
    score = sum(1 for key in PROPERTY_RECORD_KEYS if key in value)
    return score >= 3


def _property_candidates(payload: Any) -> list[tuple[str, Any]]:
    """Return every property-looking object from a raw TBS property JSON file.

    TBS Property Mod exports have appeared in several shapes over time:
    a direct list, a dict keyed by PropertyId, or nested under arbitrary save
    containers.  The Housing Market needs the raw list, so this walker indexes
    records by their JSON path instead of depending on one container name.
    """
    candidates: list[tuple[str, Any]] = []

    def walk(value: Any, path: str, source_key: str = "") -> None:
        if isinstance(value, dict):
            if _looks_like_property_record(value, source_key):
                candidates.append((path or source_key or "property", value))
                return
            for key, item in value.items():
                next_path = f"{path}.{key}" if path else str(key)
                walk(item, next_path, str(key))
        elif isinstance(value, list):
            for index, item in enumerate(value):
                walk(item, f"{path}[{index}]" if path else str(index), str(index))

    walk(payload, "")
    return candidates


def extract_shadowhaven_properties(payload: Any) -> list[dict[str, str]]:
    records: list[dict[str, str]] = []
    for source_key, value in _property_candidates(payload):
        if not isinstance(value, dict):
            continue
        raw = json.dumps(value, separators=(",", ":"), default=str)
        property_id = str(value.get("id") or value.get("PropertyId") or value.get("propertyId") or value.get("property_id") or source_key).strip()
        if not property_id:
            property_id = hashlib.sha256(raw.encode("utf-8")).hexdigest()[:24]
        def pick(*keys: str) -> str:
            for key in keys:
                if value.get(key) is not None and str(value.get(key)).strip():
                    return str(value.get(key)).strip()
            return ""
        owner_identity = pick("OwnerUid", "ownerUid", "ownerIdentity", "owner_identity", "ownerId", "owner_id", "identityId", "identity_id", "bohemiaId")
        status = pick("status", "state", "availability")
        if not status:
            status = "sold" if owner_identity else "available"
        records.append({
            "property_id": property_id[:180],
            "name": pick("name", "PropertyName", "propertyName", "property_name", "title", "displayName")[:180] or property_id[:80] or "Unnamed property",
            "address": pick("address", "location", "street", "coordinates")[:300],
            "owner_identity": owner_identity[:180],
            "status": status[:80],
            "price": pick("price", "purchasePrice", "purchase_price", "value", "cost")[:100],
            "rent": pick("RentPayments", "rentPayments", "rent", "rentRate", "rent_rate", "rentValue")[:100],
            "property_type": pick("type", "PropertyType", "propertyType", "property_type", "category")[:100] or "Housing",
            "raw_payload": raw[:50000],
        })
    return records


def sync_shadowhaven_properties_once() -> int:
    if not has_shadowhaven_sftp_credentials():
        return 0
    records_by_source: list[tuple[str, dict[str, str]]] = []
    read_sources: list[str] = []
    read_errors: list[str] = []
    transport = connect_shadowhaven_transport()
    try:
        sftp = paramiko.SFTPClient.from_transport(transport)
        try:
            for source_path in SHADOWHAVEN_PROPERTY_FILES:
                try:
                    with sftp.open(source_path, "r") as remote_file:
                        payload = json.loads(remote_file.read().decode("utf-8-sig"))
                except OSError as exc:
                    read_errors.append(f"{source_path}: {exc}")
                    continue
                records = extract_shadowhaven_properties(payload)
                if "rented" in source_path.lower():
                    for record in records:
                        if record.get("owner_identity") and record.get("status") in {"sold", "available"}:
                            record["status"] = "rented"
                read_sources.append(source_path)
                records_by_source.extend((source_path, record) for record in records)
        finally:
            sftp.close()
    finally:
        transport.close()
    if not read_sources:
        raise RuntimeError("No TBS Property Mod files could be read: " + "; ".join(read_errors[:6]))
    synced_at = now_iso()
    with conn() as db:
        for source_path in read_sources:
            db.execute("DELETE FROM game_property_records WHERE source_file = ?", (source_path[:255],))
        for source_path, record in records_by_source:
            db.execute(
                """
                INSERT INTO game_property_records
                (property_id, name, address, owner_identity, status, price_text, rent_text, property_type, raw_payload, source_file, synced_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                ON CONFLICT (property_id) DO UPDATE SET
                    name = EXCLUDED.name, address = EXCLUDED.address, owner_identity = EXCLUDED.owner_identity,
                    status = EXCLUDED.status, price_text = EXCLUDED.price_text, rent_text = EXCLUDED.rent_text,
                    property_type = EXCLUDED.property_type, raw_payload = EXCLUDED.raw_payload,
                    source_file = EXCLUDED.source_file, synced_at = EXCLUDED.synced_at
                """,
                (record["property_id"], record["name"], record["address"], record["owner_identity"], record["status"], record["price"], record["rent"], record["property_type"], record["raw_payload"], source_path[:255], synced_at),
            )
        db.execute(
            """
            INSERT INTO anticheat_sync_status
            (source_key, source_path, status, records, last_success_at, last_error, updated_at)
            VALUES ('property_mod', ?, 'synced', ?, ?, '', ?)
            ON CONFLICT (source_key) DO UPDATE SET source_path = EXCLUDED.source_path,
                status = 'synced', records = EXCLUDED.records, last_success_at = EXCLUDED.last_success_at,
                last_error = '', updated_at = EXCLUDED.updated_at
            """,
            (", ".join(read_sources)[:255], len(records_by_source), synced_at, synced_at),
        )
    return len(records_by_source)


def shadowhaven_property_sync_worker() -> None:
    if not has_shadowhaven_sftp_credentials():
        print("Shadowhaven TBS Property Mod sync disabled: credentials are not configured")
        return
    while True:
        try:
            accepted = sync_shadowhaven_properties_once()
            print(f"Shadowhaven TBS Property Mod sync updated {accepted} property record(s)")
        except Exception as exc:
            print(f"Shadowhaven TBS Property Mod sync failed: {type(exc).__name__}: {exc}")
        time.sleep(SHADOWHAVEN_PROPERTY_SYNC_SECONDS)


def roles_for(user: DbRow) -> list[str]:
    raw = user.get("roles", "[]")
    if isinstance(raw, list):
        roles = raw
    else:
        try:
            roles = json.loads(raw or "[]")
        except (TypeError, json.JSONDecodeError):
            roles = []
    normalized = [normalize_role(role) for role in roles]
    return sorted(set(["civ", *[role for role in normalized if role]]))


def has_any(user: DbRow, *roles: str) -> bool:
    owned = set(roles_for(user))
    return bool(owned.intersection(roles))


def public_user(user: DbRow) -> dict[str, Any]:
    return {
        "id": user["id"],
        "civ_number": user.get("civ_number"),
        "name": user["name"],
        "email": user["email"],
        "verified": bool(user["verified"]),
        # gang_leader is intentionally invisible outside staff operations.
        "roles": [role for role in roles_for(user) if role != "gang_leader"],
        "primary_agency": user["primary_agency"],
        "car_entry_code": user.get("car_entry_code") or "",
        "car_entry_code_required": not bool(str(user.get("car_entry_code") or "").strip()),
        "callsign": user.get("callsign") or "",
        "callsign_required": not bool(str(user.get("callsign") or "").strip()),
        # The legacy users.bank_balance column is intentionally not exposed.
        # FCRPMUSSALO is the authoritative bank and is applied by
        # public_user_with_game_bank where a database context is available.
        "bank_balance": 0,
        "bank_balance_source": "FCRPMUSSALO",
        "bank_balance_synced": False,
        "cash_balance": 0,
        "active_character_id": user.get("active_character_id"),
        "name_change_locked": bool(user.get("name_change_locked", 0)),
        "referral_code": user.get("referral_code") or "",
        "referred_by_user_id": user.get("referred_by_user_id"),
        "profile_photo": user.get("profile_photo") or "",
        "created_at": user["created_at"],
    }


def public_user_with_game_bank(db: Database, user: DbRow) -> dict[str, Any]:
    payload = public_user(user)
    game_bank = one(
        db,
        """
        SELECT b.balance, b.synced_at
        FROM arma_account_links l
        JOIN arma_game_bank_balances b ON b.identity_id = l.identity_id
        WHERE l.user_id = ?
        """,
        (user["id"],),
    )
    payload["bank_balance"] = round(float(game_bank["balance"] or 0), 2) if game_bank else 0
    payload["bank_balance_source"] = "FCRPMUSSALO"
    payload["bank_balance_synced"] = bool(game_bank)
    payload["bank_balance_synced_at"] = game_bank.get("synced_at") if game_bank else None
    return payload


def require_fields(payload: dict[str, Any], *fields: str) -> str | None:
    missing = [field for field in fields if payload.get(field) in (None, "")]
    if missing:
        return f"Missing required field: {missing[0]}"
    return None


def generate_civ_number(db: Database) -> str:
    for _ in range(50):
        number = f"{secrets.randbelow(900000) + 100000}"
        if not one(db, "SELECT id FROM users WHERE civ_number = ?", (number,)):
            return number
    raise RuntimeError("Unable to generate unique civilian ID")


def generate_referral_code(db: Database) -> str:
    alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"
    for _ in range(80):
        code = "FC" + "".join(secrets.choice(alphabet) for _ in range(6))
        if not one(db, "SELECT id FROM users WHERE referral_code = ?", (code,)):
            return code
    raise RuntimeError("Unable to generate unique referral code")


def clean_referral_code(value: Any) -> str:
    code = str(value or "").strip().upper().replace(" ", "").replace("-", "")
    if not code:
        return ""
    if len(code) < 4 or len(code) > 16:
        raise ValueError("Referral code is not valid")
    allowed = set("ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789")
    if any(character not in allowed for character in code):
        raise ValueError("Referral code can only use letters and numbers")
    return code


def clean_car_entry_code(value: Any) -> str:
    code = str(value or "").strip().upper()
    if not code:
        raise ValueError("Car entry code is required")
    if len(code) < 2 or len(code) > 32:
        raise ValueError("Car entry code must be 2-32 characters")
    allowed = set("ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_")
    if any(character not in allowed for character in code):
        raise ValueError("Car entry code can only use letters, numbers, dashes, or underscores")
    return code


def clean_callsign(value: Any) -> str:
    callsign = str(value or "").strip().upper()
    if not callsign:
        raise ValueError("Callsign is required")
    if len(callsign) < 2 or len(callsign) > 24:
        raise ValueError("Callsign must be 2-24 characters")
    allowed = set("ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_")
    if any(character not in allowed for character in callsign):
        raise ValueError("Callsign can only use letters, numbers, dashes, or underscores")
    return callsign


def generate_vehicle_vin(db: Database) -> str:
    alphabet = "ABCDEFGHJKLMNPRSTUVWXYZ0123456789"
    for _ in range(50):
        vin = "".join(secrets.choice(alphabet) for _ in range(17))
        if not one(db, "SELECT id FROM dmv_vehicles WHERE vin = ?", (vin,)):
            return vin
    raise RuntimeError("Unable to generate unique vehicle VIN")


def linked_game_vehicle_rows(db: Database, user_id: int) -> list[DbRow]:
    link = one(db, "SELECT identity_id, uid, rpl_identity FROM arma_account_links WHERE user_id = ?", (user_id,))
    if not link:
        return []
    # Vehicle ownership is correlated only by the stable Arma identity on the
    # linked Faircroft account. UID/RPL values and display names are not safe
    # ownership keys and can cross unrelated persistence records.
    identity_id = str(link.get("identity_id") or "").strip()
    if len(identity_id) < 8:
        return []
    return all_rows(
        db,
        """SELECT record_id, title, prefab, record_status, summary_payload, raw_payload, source_modified_at
            FROM game_persistence_records
            WHERE LOWER(category) = 'vehicles' AND owner_identity = ?
            ORDER BY source_modified_at DESC LIMIT 60""",
        (identity_id,),
    )


def imported_vehicle_belongs_to_account(db: Database, user_id: int, vehicle: DbRow) -> bool:
    """Keep unresolved legacy imports quarantined from resident accounts."""
    if str(vehicle.get("source") or "") != "fcrpmussalo":
        return True
    link = one(db, "SELECT identity_id FROM arma_account_links WHERE user_id = ?", (user_id,))
    identity_id = str(link.get("identity_id") or "").strip() if link else ""
    record_id = str(vehicle.get("source_record_id") or "").strip()
    if len(identity_id) < 8 or not record_id:
        return False
    return bool(one(db, """SELECT record_id FROM game_persistence_records
        WHERE LOWER(category)='vehicles' AND record_id=? AND owner_identity=?""", (record_id, identity_id)))


def imported_vehicle_details(row: DbRow) -> dict[str, Any]:
    try:
        raw = json.loads(row.get("raw_payload") or "{}")
    except (TypeError, json.JSONDecodeError):
        raw = {}
    fields = persistence_scalar_fields(raw, 4000)
    lowered = [(path.lower().rsplit(".", 1)[-1], value) for path, value in fields]

    def first(*needles: str) -> str:
        for leaf, value in lowered:
            if any(needle in leaf for needle in needles):
                return str(value).strip()
        return ""

    current_year = utcnow().year
    year_text = first("vehicleyear", "modelyear", "year")
    year_match = re.search(r"\b(19\d{2}|20\d{2})\b", year_text)
    year = int(year_match.group(1)) if year_match else current_year
    if year < 1900 or year > current_year + 1:
        year = current_year
    title = str(row.get("title") or "").strip()
    prefab_name = Path(str(row.get("prefab") or "")).stem.replace("_", " ").strip()
    make = first("manufacturer", "vehiclemake", "make")[:40] or "Imported"
    model = first("vehiclemodel", "model", "vehiclename", "displayname")[:40] or title[:40] or prefab_name[:40] or "Arma Vehicle"
    color = first("vehiclecolor", "colour", "color")[:30] or "Unspecified"
    return {"vehicle_year": year, "vehicle_make": make, "vehicle_model": model, "vehicle_color": color}


def imported_vehicle_plate(db: Database, record_id: str) -> str:
    base = f"FC{hashlib.sha256(record_id.encode('utf-8')).hexdigest()[:7]}".upper()
    plate = base
    suffix = 1
    while one(db, "SELECT id FROM dmv_vehicles WHERE plate = ?", (plate,)):
        suffix += 1
        plate = f"{base[:9]}{suffix}"[:12]
    return plate


def sync_linked_vehicles_to_dmv(db: Database, user_id: int) -> list[dict[str, Any]]:
    rows = linked_game_vehicle_rows(db, user_id)
    if not rows:
        return []
    if not one(db, "SELECT id FROM dmv_records WHERE user_id = ?", (user_id,)):
        create_default_dmv(db, user_id)
    ts = now_iso()
    imported: list[dict[str, Any]] = []
    for row in rows:
        record_id = str(row.get("record_id") or "").strip()[:180]
        if not record_id:
            continue
        existing = one(
            db,
            "SELECT * FROM dmv_vehicles WHERE user_id = ? AND source = 'fcrpmussalo' AND source_record_id = ?",
            (user_id, record_id),
        )
        if existing:
            imported.append(dict(existing))
            continue
        details = imported_vehicle_details(row)
        plate = imported_vehicle_plate(db, record_id)
        vin = generate_vehicle_vin(db)
        created = db.execute(
            """
            INSERT INTO dmv_vehicles
            (user_id, vehicle_year, vehicle_make, vehicle_model, vehicle_color, plate, vin,
             registration_status, insurance_status, source, source_record_id, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, 'Registration Required', 'Not Insured',
                    'fcrpmussalo', ?, ?, ?)
            ON CONFLICT DO NOTHING
            RETURNING *
            """,
            (
                user_id, details["vehicle_year"], details["vehicle_make"], details["vehicle_model"],
                details["vehicle_color"], plate, vin, record_id, ts, ts,
            ),
        ).fetchone()
        if created:
            imported.append(dict(created))
            add_message(
                db,
                user_id,
                "Vehicle detected — DMV action required",
                f"{details['vehicle_year']} {details['vehicle_make']} {details['vehicle_model']} was imported from your linked Arma profile. Confirm its registration details and add insurance before driving.",
            )
    return imported


def generate_record_number(db: Database, table: str, column: str, prefix: str) -> str:
    allowed = {
        ("cid_investigations", "case_number"),
        ("cid_warrants", "warrant_number"),
        ("cid_internal_affairs", "ia_number"),
        ("cad_after_call_reports", "report_number"),
        ("mdt_bolos", "bolo_number"),
        ("mdt_bookings", "booking_number"),
        ("rp_contracts", "contract_number"),
        ("business_applications", "application_number"),
        ("businesses", "license_number"),
        ("department_applications", "application_number"),
        ("treasury_requests", "request_number"),
        ("press_reports", "report_number"),
    }
    if (table, column) not in allowed:
        raise ValueError("Invalid record number target")
    for _ in range(50):
        number = f"{prefix}-{secrets.randbelow(900000) + 100000}"
        if not one(db, f"SELECT id FROM {table} WHERE {column} = ?", (number,)):
            return number
    raise RuntimeError("Unable to generate unique record number")


