    def api_citizenship(self, db: Database, user: DbRow | None) -> None:
        if not user:
            self.error(401, "Authentication required")
            return
        record = one(db, "SELECT * FROM citizenship_records WHERE user_id = ?", (user["id"],))
        if not record:
            db.execute(
                """
                INSERT INTO citizenship_records
                (user_id, citizenship_status, updated_at)
                VALUES (?, 'Undocumented', ?)
                """,
                (user["id"], now_iso()),
            )
            record = one(db, "SELECT * FROM citizenship_records WHERE user_id = ?", (user["id"],))
        attempts = all_rows(
            db,
            "SELECT score, total, passed, created_at FROM citizenship_exam_attempts WHERE user_id = ? ORDER BY id DESC LIMIT 10",
            (user["id"],),
        )
        self.send_json(
            200,
            {
                "record": dict(record or {}),
                "holder": {
                    "name": user["name"],
                    "civ_number": user.get("civ_number") or "",
                    "photo": user.get("profile_photo") or "",
                },
                "questions": [
                    {"number": index, "question": question, "options": list(options)}
                    for index, (question, options, _answer) in enumerate(FAIRCROFT_CITIZENSHIP_QUESTIONS, start=1)
                ] if str((record or {}).get("citizenship_status") or "").lower() != "valid citizen" else [],
                "attempts": [dict(item) for item in attempts],
            },
        )

    def api_citizenship_exam(self, db: Database, user: DbRow | None) -> None:
        if not user:
            self.error(401, "Authentication required")
            return
        payload = self.read_json()
        letters = ("A", "B", "C", "D")
        score = 0
        for index, (_question, _options, answer) in enumerate(FAIRCROFT_CITIZENSHIP_QUESTIONS, start=1):
            selected = str(payload.get(f"q{index}") or "").strip().upper()
            if selected not in letters:
                self.error(400, f"Question {index} requires an answer")
                return
            score += int(selected == answer)
        passed = score >= 5
        ts = now_iso()
        db.execute(
            "INSERT INTO citizenship_exam_attempts (user_id, score, total, passed, created_at) VALUES (?, ?, 6, ?, ?)",
            (user["id"], score, int(passed), ts),
        )
        db.execute(
            """
            INSERT INTO citizenship_records
            (user_id, citizenship_status, passport_number, issued_at, exam_passed_at, exam_attempts, updated_at)
            VALUES (?, ?, ?, ?, ?, 1, ?)
            ON CONFLICT (user_id) DO UPDATE SET
                citizenship_status = CASE WHEN EXCLUDED.exam_passed_at IS NOT NULL THEN 'Valid Citizen' ELSE citizenship_records.citizenship_status END,
                passport_number = COALESCE(citizenship_records.passport_number, EXCLUDED.passport_number),
                issued_at = COALESCE(citizenship_records.issued_at, EXCLUDED.issued_at),
                exam_passed_at = COALESCE(citizenship_records.exam_passed_at, EXCLUDED.exam_passed_at),
                exam_attempts = citizenship_records.exam_attempts + 1,
                updated_at = EXCLUDED.updated_at
            """,
            (
                user["id"],
                "Valid Citizen" if passed else "Undocumented",
                f"FCP-{str(user.get('civ_number') or user['id']).replace(' ', '').upper()}"[:40] if passed else None,
                ts if passed else None,
                ts if passed else None,
                ts,
            ),
        )
        self.send_json(200, {"passed": passed, "score": score, "total": 6})

    def _ice_camera_payload(self, db: Database) -> dict[str, Any]:
        rows = all_rows(
            db,
            "SELECT * FROM fluck_camera_events ORDER BY captured_at DESC LIMIT 300",
        )
        linked_rows = all_rows(
            db,
            """
            SELECT
                l.identity_id,
                l.player_name,
                l.user_id,
                u.name AS account_name,
                u.email AS account_email,
                u.civ_number AS account_civ_number,
                COALESCE(cr.citizenship_status, 'Undocumented') AS citizenship_status,
                cr.passport_number
            FROM arma_account_links l
            LEFT JOIN users u ON u.id = l.user_id
            LEFT JOIN citizenship_records cr ON cr.user_id = u.id
            WHERE l.identity_id <> '' OR l.player_name <> ''
            """,
        )
        linked_identities = {
            str(row["identity_id"]).strip().casefold(): row
            for row in linked_rows
            if row.get("identity_id")
        }
        linked_names = {
            str(row["player_name"]).strip().casefold(): row
            for row in linked_rows
            if row.get("player_name")
        }
        events: list[dict[str, Any]] = []
        cameras: dict[str, dict[str, Any]] = {}
        for row in rows:
            item = dict(row)
            identity_key = str(item.get("identity_id") or "").strip().casefold()
            name_key = str(item.get("subject_name") or "").strip().casefold()
            identity_match = linked_identities.get(identity_key) if identity_key else None
            name_match = linked_names.get(name_key) if name_key else None
            match = identity_match or name_match
            item["linked_account"] = bool(match)
            item["linked_match"] = "identity_id" if identity_match else ("player_name" if name_match else "")
            if match:
                item["linked_user_id"] = match.get("user_id")
                item["linked_account_name"] = match.get("account_name") or match.get("player_name") or "Matched Faircroft account"
                item["linked_account_email"] = match.get("account_email") or ""
                item["linked_civ_number"] = match.get("account_civ_number") or ""
                item["linked_player_name"] = match.get("player_name") or ""
                item["citizenship_status"] = match.get("citizenship_status") or "Undocumented"
                item["passport_number"] = match.get("passport_number") or ""
            else:
                item["citizenship_status"] = "Identity unresolved"
                item["passport_number"] = ""
            try:
                raw_payload = json.loads(str(item.get("raw_payload") or "{}"))
            except (TypeError, ValueError, json.JSONDecodeError):
                raw_payload = {}
            occupant_records: list[dict[str, Any]] = []
            for occupant in _camera_occupants(raw_payload if isinstance(raw_payload, dict) else {}):
                occupant_identity = str(occupant.get("identity_id") or "").strip().casefold()
                occupant_name = str(occupant.get("name") or "").strip().casefold()
                occupant_identity_match = linked_identities.get(occupant_identity) if occupant_identity else None
                occupant_name_match = linked_names.get(occupant_name) if occupant_name else None
                occupant_match = occupant_identity_match or occupant_name_match
                occupant_records.append({
                    **occupant,
                    "linked_account": bool(occupant_match),
                    "linked_match": "identity_id" if occupant_identity_match else ("player_name" if occupant_name_match else ""),
                    "linked_user_id": occupant_match.get("user_id") if occupant_match else None,
                    "linked_account_name": (occupant_match.get("account_name") or occupant_match.get("player_name") or "Matched Faircroft account") if occupant_match else "",
                    "linked_civ_number": occupant_match.get("account_civ_number") if occupant_match else "",
                    "citizenship_status": (occupant_match.get("citizenship_status") or "Undocumented") if occupant_match else "Identity unresolved",
                    "passport_number": occupant_match.get("passport_number") if occupant_match else "",
                })
            # Older FLUCK exports describe only the driver at the top level. Keep that
            # identity in the vehicle manifest without inventing passenger records.
            if not occupant_records and (item.get("subject_name") or item.get("identity_id")):
                occupant_records.append({
                    "name": item.get("subject_name") or item.get("linked_player_name") or "Observed driver",
                    "identity_id": item.get("identity_id") or "",
                    "role": "driver",
                    "linked_account": item["linked_account"],
                    "linked_match": item.get("linked_match") or "",
                    "linked_user_id": item.get("linked_user_id"),
                    "linked_account_name": item.get("linked_account_name") or "",
                    "linked_civ_number": item.get("linked_civ_number") or "",
                    "citizenship_status": item.get("citizenship_status") or "Identity unresolved",
                    "passport_number": item.get("passport_number") or "",
                })
            item["occupants"] = occupant_records
            item["occupant_count"] = len(occupant_records)
            camera_id = str(item.get("camera_id") or "Unknown camera").strip() or "Unknown camera"
            camera_record = cameras.setdefault(
                camera_id,
                {"camera_id": camera_id, "events": 0, "linked": 0, "last_seen": None, "locations": set()},
            )
            camera_record["events"] += 1
            if item["linked_account"]:
                camera_record["linked"] += 1
            if item.get("location"):
                camera_record["locations"].add(str(item.get("location")))
            captured = item.get("captured_at")
            if captured and (not camera_record["last_seen"] or str(captured) > str(camera_record["last_seen"])):
                camera_record["last_seen"] = captured
            item.pop("raw_payload", None)
            events.append(item)
        last_sync = one(db, "SELECT last_success_at, status, records FROM anticheat_sync_status WHERE source_key = 'fluck_camera'")
        cutoff = utcnow() - dt.timedelta(hours=24)
        recent = 0
        for item in events:
            try:
                if parse_bridge_datetime(item.get("captured_at")) >= cutoff:
                    recent += 1
            except (TypeError, ValueError):
                pass
        high = sum(1 for item in events if str(item.get("severity") or "").lower() in {"high", "critical", "urgent"})
        camera_list = sorted(
            (
                {
                    **camera,
                    "locations": sorted(camera["locations"])[:4],
                }
                for camera in cameras.values()
            ),
            key=lambda camera: (str(camera.get("last_seen") or ""), str(camera.get("camera_id") or "")),
            reverse=True,
        )
        linked_count = sum(1 for item in events if item.get("linked_account"))
        return {
            "events": events,
            "cameras": camera_list,
            "stats": {
                "total": len(events),
                "last_24_hours": recent,
                "high_priority": high,
                "camera_count": len(camera_list),
                "linked": linked_count,
                "unlinked": max(len(events) - linked_count, 0),
            },
            "source_file": SHADOWHAVEN_CAMERA_EVENTS_FILE,
            "last_sync": dict(last_sync) if last_sync else None,
            "operational": bool(last_sync and last_sync.get("status") == "synced"),
        }

    def api_ice_camera_events(self, db: Database, user: DbRow | None) -> None:
        err = ice_required(user)
        if err:
            self.error(403 if user else 401, err)
            return
        self.send_json(200, self._ice_camera_payload(db))

    def api_ice_account(self, db: Database, user: DbRow | None, target_id: int) -> None:
        err = ice_required(user)
        if err:
            self.error(403 if user else 401, err)
            return
        account = one(
            db,
            """
            SELECT u.*, l.id AS link_id, l.server_id, l.identity_id, l.uid,
                   l.rpl_identity, l.platform, l.player_name, l.linked_at,
                   l.last_seen_at, l.last_sync_at,
                   COALESCE(cr.citizenship_status, 'Undocumented') AS citizenship_status,
                   cr.passport_number, cr.issued_at AS passport_issued_at
            FROM users u
            LEFT JOIN arma_account_links l ON l.user_id = u.id
            LEFT JOIN citizenship_records cr ON cr.user_id = u.id
            WHERE u.id = ?
            """,
            (target_id,),
        )
        if not account:
            self.error(404, "Account not found")
            return
        if not account.get("link_id"):
            self.error(409, "This account does not have an active Arma link")
            return
        sanctions = all_rows(
            db,
            """
            SELECT s.*, creator.name AS created_by_name, revoker.name AS revoked_by_name
            FROM account_sanctions s
            JOIN users creator ON creator.id = s.created_by
            LEFT JOIN users revoker ON revoker.id = s.revoked_by
            WHERE s.user_id = ? ORDER BY s.created_at DESC LIMIT 100
            """,
            (target_id,),
        )
        warnings = all_rows(
            db,
            """
            SELECT w.*, creator.name AS created_by_name, resolver.name AS resolved_by_name
            FROM account_internal_warnings w
            JOIN users creator ON creator.id = w.created_by
            LEFT JOIN users resolver ON resolver.id = w.resolved_by
            WHERE w.user_id = ? ORDER BY w.created_at DESC LIMIT 100
            """,
            (target_id,),
        )
        arma_activity = all_rows(
            db,
            """
            SELECT * FROM arma_activity_logs
            WHERE user_id = ? ORDER BY received_at DESC LIMIT 150
            """,
            (target_id,),
        )
        characters = all_rows(
            db,
            "SELECT * FROM user_characters WHERE user_id = ? ORDER BY is_active DESC, updated_at DESC",
            (target_id,),
        )
        jobs = all_rows(
            db,
            """
            SELECT uj.*, j.title, j.market
            FROM user_jobs uj JOIN jobs j ON j.id = uj.job_id
            WHERE uj.user_id = ? ORDER BY uj.started_at DESC
            """,
            (target_id,),
        )
        citations = all_rows(
            db,
            """
            SELECT c.*
            FROM citations c
            WHERE c.civ_id = ? ORDER BY c.created_at DESC LIMIT 100
            """,
            (target_id,),
        )
        properties = all_rows(
            db,
            """
            SELECT p.* FROM properties p
            WHERE p.owner_id = ? ORDER BY p.created_at DESC
            """,
            (target_id,),
        )
        active_block = active_account_block(db, target_id)
        game_bank = one(
            db,
            "SELECT * FROM arma_game_bank_balances WHERE identity_id = ?",
            (account.get("identity_id") or "",),
        )
        self.send_dev_account_response(
            db,
            account,
            active_block,
            sanctions,
            warnings,
            arma_activity,
            characters,
            jobs,
            citations,
            properties,
            game_bank,
        )

    def api_ice_overview(self, db: Database, user: DbRow | None) -> None:
        err = ice_required(user)
        if err:
            self.error(403 if user else 401, err)
            return
        settings = get_system_settings(db)
        cases = all_rows(
            db,
            """
            SELECT c.*, subject.name AS subject_name, subject.civ_number,
                   opener.name AS opened_by_name, assignee.name AS assigned_to_name,
                   cr.citizenship_status, cr.passport_number
            FROM ice_cases c
            JOIN users subject ON subject.id = c.subject_user_id
            JOIN users opener ON opener.id = c.opened_by
            LEFT JOIN users assignee ON assignee.id = c.assigned_to
            LEFT JOIN citizenship_records cr ON cr.user_id = subject.id
            ORDER BY CASE c.status WHEN 'open' THEN 0 WHEN 'detained' THEN 1 ELSE 2 END, c.updated_at DESC
            LIMIT 150
            """,
        )
        stats = {
            "valid_citizens": int(one(db, "SELECT COUNT(*) AS count FROM citizenship_records WHERE LOWER(citizenship_status) = 'valid citizen'")["count"]),
            "undocumented": int(one(db, "SELECT COUNT(*) AS count FROM users u WHERE NOT EXISTS (SELECT 1 FROM citizenship_records c WHERE c.user_id = u.id AND LOWER(c.citizenship_status) = 'valid citizen')")["count"]),
            "open_cases": sum(1 for item in cases if item["status"] in ("open", "detained")),
        }
        can_command = has_any(user, "ice_commander")
        applications: list[dict[str, Any]] = []
        if can_command:
            application_rows = all_rows(
                db,
                """
                SELECT a.*, applicant.name AS applicant_name, applicant.civ_number AS applicant_civ_number,
                       character.character_name, reviewer.name AS reviewer_name
                FROM department_applications a
                JOIN users applicant ON applicant.id = a.user_id
                LEFT JOIN user_characters character ON character.id = a.character_id
                LEFT JOIN users reviewer ON reviewer.id = a.reviewed_by
                WHERE a.department_key = 'ice_agent'
                ORDER BY CASE a.status WHEN 'submitted' THEN 0 WHEN 'under_review' THEN 1 WHEN 'interview_requested' THEN 2 ELSE 3 END,
                         a.updated_at DESC
                LIMIT 150
                """,
            )
            for row in application_rows:
                item = dict(row)
                try:
                    packet = json.loads(item.get("statement") or "{}")
                except (TypeError, json.JSONDecodeError):
                    packet = {}
                item["qualification"] = {
                    "score": int(packet.get("score") or 0),
                    "total": int(packet.get("total") or 20),
                    "answers": packet.get("answers") if isinstance(packet.get("answers"), list) else [],
                }
                applications.append(item)
            stats["applications_pending"] = sum(1 for item in applications if item["status"] in ("submitted", "under_review", "interview_requested"))
        gang_affiliations = all_rows(db, """SELECT gm.id,gm.user_id,gm.character_id,gm.gang_role,gm.status,
            g.id AS gang_id,g.name AS gang_name,g.accent_color,c.character_name,u.civ_number,
            COALESCE(cr.citizenship_status,'Undocumented') AS citizenship_status,cr.passport_number
            FROM gang_members gm JOIN gangs g ON g.id=gm.gang_id JOIN user_characters c ON c.id=gm.character_id
            JOIN users u ON u.id=gm.user_id LEFT JOIN citizenship_records cr ON cr.user_id=u.id
            WHERE gm.status IN ('active','locked') AND g.status='active' ORDER BY g.name,c.character_name""")
        stats["gang_affiliations"] = len(gang_affiliations)
        self.send_json(
            200,
            {
                "cases": [dict(item) for item in cases],
                "stats": stats,
                "local_data_restricted": settings["ice_restrict_local_data"],
                "ordinance_notice": "Faircroft Local Ordinance restricts local police involvement with federal immigration operations. NCIC identity and safety checks remain available; local reports, BOLOs, and warrants are withheld when the restriction is active.",
                "can_command": can_command,
                "applications": applications,
                "gang_affiliations": [dict(row) for row in gang_affiliations],
                "fluck_camera": self._ice_camera_payload(db),
            },
        )

    def api_ice_search(self, db: Database, user: DbRow | None, query: dict[str, list[str]]) -> None:
        err = ice_required(user)
        if err:
            self.error(403 if user else 401, err)
            return
        term = (query.get("q") or [""])[0].strip()
        if len(term) < 2:
            self.send_json(200, {"results": []})
            return
        like = f"%{term}%"
        settings = get_system_settings(db)
        rows = all_rows(
            db,
            """
            SELECT u.id, u.name, u.civ_number, u.profile_photo,
                   COALESCE(c.citizenship_status, 'Undocumented') AS citizenship_status,
                   c.passport_number, c.issued_at,
                   d.license_status, d.license_class
            FROM users u
            LEFT JOIN citizenship_records c ON c.user_id = u.id
            LEFT JOIN dmv_records d ON d.user_id = u.id
            WHERE u.name ILIKE ? OR u.civ_number ILIKE ? OR c.passport_number ILIKE ?
            ORDER BY u.name LIMIT 30
            """,
            (like, like, like),
        )
        results = []
        for row in rows:
            item = dict(row)
            item["gang_affiliations"] = [dict(entry) for entry in all_rows(db, """SELECT g.id AS gang_id,g.name AS gang_name,g.accent_color,gm.gang_role,gm.status,c.character_name
                FROM gang_members gm JOIN gangs g ON g.id=gm.gang_id JOIN user_characters c ON c.id=gm.character_id
                WHERE gm.user_id=? AND gm.status IN ('active','locked') AND g.status='active' ORDER BY g.name""", (row["id"],))]
            item["vehicles"] = [
                dict(vehicle) for vehicle in all_rows(
                    db,
                    "SELECT plate, vehicle_year, vehicle_make, vehicle_model, registration_status, insurance_status FROM dmv_vehicles WHERE user_id = ? ORDER BY created_at DESC LIMIT 8",
                    (row["id"],),
                )
            ]
            if not settings["ice_restrict_local_data"]:
                item["warrants"] = [dict(entry) for entry in all_rows(db, "SELECT warrant_number, warrant_type, priority, status FROM cid_warrants WHERE subject_civ_id = ? ORDER BY updated_at DESC LIMIT 15", (row["id"],))]
                item["reports"] = [dict(entry) for entry in all_rows(db, "SELECT report_number, call_type, disposition, created_at FROM cad_after_call_reports WHERE involved_civ_id = ? ORDER BY created_at DESC LIMIT 15", (row["id"],))]
                item["bolos"] = [dict(entry) for entry in all_rows(db, "SELECT bolo_number, reason, caution_level, status FROM mdt_bolos WHERE target_name ILIKE ? ORDER BY updated_at DESC LIMIT 15", (f"%{row['name']}%",))]
            results.append(item)
        self.send_json(200, {"results": results, "local_data_restricted": settings["ice_restrict_local_data"]})

    def api_ice_create_case(self, db: Database, user: DbRow | None) -> None:
        err = ice_required(user)
        if err:
            self.error(403 if user else 401, err)
            return
        payload = self.read_json()
        subject_id = int(payload.get("subject_user_id") or 0)
        narrative = str(payload.get("narrative") or "").strip()
        if not one(db, "SELECT id FROM users WHERE id = ?", (subject_id,)) or len(narrative) < 10:
            self.error(400, "A valid subject and detailed immigration narrative are required")
            return
        ts = now_iso()
        created = db.execute(
            """
            INSERT INTO ice_cases
            (case_number, subject_user_id, opened_by, assigned_to, case_type, priority, status, location, narrative, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, 'open', ?, ?, ?, ?)
            RETURNING id, case_number
            """,
            (
                generate_record_number(db, "ice_cases", "case_number", "ICE"),
                subject_id, user["id"], user["id"],
                str(payload.get("case_type") or "Status Review").strip()[:80],
                str(payload.get("priority") or "standard").strip()[:30],
                str(payload.get("location") or "").strip()[:240],
                narrative[:5000], ts, ts,
            ),
        ).fetchone()
        self.send_json(201, {"ok": True, "id": int(created["id"]), "case_number": created["case_number"]})

    def api_ice_update_case(self, db: Database, user: DbRow | None, case_id: int) -> None:
        err = ice_required(user)
        if err:
            self.error(403 if user else 401, err)
            return
        if not has_any(user, "ice_commander"):
            self.error(403, "ICE Commander authorization required")
            return
        payload = self.read_json()
        status = str(payload.get("status") or "open").strip().lower()
        if status not in ("open", "detained", "released", "referred", "closed"):
            self.error(400, "Unsupported immigration case status")
            return
        ts = now_iso()
        db.execute(
            "UPDATE ice_cases SET status = ?, disposition = ?, updated_at = ?, closed_at = ? WHERE id = ?",
            (status, str(payload.get("disposition") or "").strip()[:3000], ts, ts if status == "closed" else None, case_id),
        )
        self.send_json(200, {"ok": True})

    def api_ice_review_application(self, db: Database, user: DbRow | None, application_id: int) -> None:
        err = ice_required(user)
        if err:
            self.error(403 if user else 401, err)
            return
        if not has_any(user, "ice_commander"):
            self.error(403, "ICE Commander authorization required")
            return
        application = one(db, "SELECT * FROM department_applications WHERE id = ? AND department_key = 'ice_agent'", (application_id,))
        if not application:
            self.error(404, "ICE application not found")
            return
        payload = self.read_json()
        action = str(payload.get("action") or "").strip().lower()
        status_map = {"review": "under_review", "interview": "interview_requested", "approve": "approved", "deny": "denied"}
        if action not in status_map:
            self.error(400, "Choose review, interview, approve, or deny")
            return
        try:
            exam = json.loads(application.get("statement") or "{}")
            score = int(exam.get("score") or 0)
            total = int(exam.get("total") or 20)
        except (TypeError, ValueError, json.JSONDecodeError):
            self.error(409, "This application does not contain a valid ICE qualification result")
            return
        if action in ("interview", "approve") and (score != 20 or total != 20):
            self.error(409, "Only a perfect 20/20 qualification result may advance")
            return
        notes = str(payload.get("reviewer_notes") or "").strip()[:1500]
        status = status_map[action]
        ts = now_iso()
        db.execute(
            "UPDATE department_applications SET status = ?, reviewed_by = ?, reviewer_notes = ?, updated_at = ? WHERE id = ?",
            (status, user["id"], notes, ts, application_id),
        )
        if action == "approve":
            applicant = one(db, "SELECT * FROM users WHERE id = ?", (application["user_id"],))
            if applicant:
                updated_roles = sorted(set([*roles_for(applicant), "ice_agent"]))
                db.execute(
                    "UPDATE users SET verified = 1, roles = ?, primary_agency = ? WHERE id = ?",
                    (json.dumps(updated_roles), "Faircroft Immigration & Customs Enforcement", application["user_id"]),
                )
        subject_map = {
            "review": "ICE application under command review",
            "interview": "ICE interview and training invitation",
            "approve": "ICE Agent appointment approved",
            "deny": "ICE application decision",
        }
        body_map = {
            "review": "ICE Command has opened your application for review.",
            "interview": "Your perfect qualification result has advanced to the ICE interview and training process.",
            "approve": "ICE Command approved your appointment. The ICE Agent role and ICE MDT access are now active.",
            "deny": "ICE Command did not advance your application.",
        }
        body = body_map[action] + (f"\n\nCommander notes: {notes}" if notes else "")
        add_message(db, application["user_id"], subject_map[action], body, user["id"])
        self.send_json(200, {"ok": True, "status": status, "role_granted": action == "approve"})

    def api_leaderboards(self, db: Database, user: DbRow | None) -> None:
        err = verified_required(user)
        if err:
            self.error(403 if user else 401, err)
            return

        def ranked(items: list[dict[str, Any]], key: str, limit: int = 25) -> list[dict[str, Any]]:
            ordered = sorted(items, key=lambda item: (float(item.get(key) or 0), str(item.get("name") or "")), reverse=True)
            return [{**item, "rank": index + 1} for index, item in enumerate(ordered[:limit])]

        def metric_int(value: Any) -> int:
            try:
                return max(0, int(float(value or 0)))
            except (TypeError, ValueError):
                return 0

        # The staff role is deliberately permission-neutral. It only removes the
        # account from public competition; authoritative economy and telemetry
        # records remain unchanged for Developer Tools and operational totals.
        staff_user_ids = {
            int(account["id"])
            for account in all_rows(db, "SELECT id, roles FROM users")
            if "staff" in roles_for(account)
        }

        def eligible(items: list[dict[str, Any]]) -> list[dict[str, Any]]:
            return [item for item in items if not item.get("user_id") or int(item["user_id"]) not in staff_user_ids]

        telemetry_rows = all_rows(
            db,
            """
            SELECT p.uid, p.player_name, p.is_online, p.last_seen_at, p.last_synced_at, p.raw_payload,
                   u.id AS user_id, u.name AS resident_name, u.civ_number, u.roles
            FROM anticheat_players p
            LEFT JOIN arma_account_links l ON l.identity_id = p.uid OR l.uid = p.uid
            LEFT JOIN users u ON u.id = l.user_id
            WHERE p.source_file = ?
            ORDER BY p.last_synced_at DESC
            """,
            (SHADOWHAVEN_ANTICHEAT_DATABASE_FILE[:255],),
        )
        telemetry: list[dict[str, Any]] = []
        for row in telemetry_rows:
            try:
                raw = json.loads(str(row.get("raw_payload") or "{}"))
            except (TypeError, ValueError, json.JSONDecodeError):
                raw = {}
            kills = metric_int(raw.get("kills"))
            deaths = metric_int(raw.get("deaths"))
            playtime = metric_int(raw.get("totalPlaytimeSeconds"))
            roles_text = str(row.get("roles") or "").lower()
            telemetry.append(
                {
                    "user_id": int(row["user_id"]) if row.get("user_id") else None,
                    "uid": str(row.get("uid") or ""),
                    "name": str(row.get("player_name") or row.get("resident_name") or "Unknown player"),
                    "resident_name": str(row.get("resident_name") or ""),
                    "civ_number": str(row.get("civ_number") or ""),
                    "linked": bool(row.get("user_id")),
                    "online": bool(row.get("is_online")),
                    "last_seen_at": row.get("last_seen_at") or row.get("last_synced_at"),
                    "playtime_seconds": playtime,
                    "current_session_seconds": metric_int(raw.get("currentSessionSeconds")),
                    "longest_session_seconds": metric_int(raw.get("longestSessionSeconds")),
                    "session_count": metric_int(raw.get("sessionCount")),
                    "kills": kills,
                    "deaths": deaths,
                    "suicides": metric_int(raw.get("suicides")),
                    "kd_ratio": round(kills / deaths, 2) if deaths else float(kills),
                    "roles": roles_text,
                }
            )

        wealth_rows = all_rows(
            db,
            """
            SELECT u.id AS user_id, u.name, u.civ_number, l.player_name,
                   b.identity_id, b.balance, b.synced_at
            FROM arma_game_bank_balances b
            JOIN arma_account_links l ON l.identity_id = b.identity_id
            JOIN users u ON u.id = l.user_id
            WHERE u.verified <> 0
            ORDER BY b.balance DESC, u.name
            LIMIT 100
            """,
        )
        wealth = [
            {
                "user_id": int(row["user_id"]),
                "name": str(row.get("player_name") or row.get("name") or "Linked player"),
                "resident_name": str(row.get("name") or ""),
                "civ_number": str(row.get("civ_number") or ""),
                "balance": round(float(row.get("balance") or 0), 2),
                "synced_at": row.get("synced_at"),
                "source_key": str(row.get("identity_id") or ""),
            }
            for row in wealth_rows
        ]

        credit_rows = all_rows(
            db,
            """
            SELECT u.id AS user_id, u.name, u.civ_number, l.player_name, r.player_key,
                   r.reputation, r.synced_at
            FROM arma_account_links l
            JOIN users u ON u.id = l.user_id
            JOIN arma_game_reputation r ON LOWER(r.player_key) = LOWER(l.player_name)
            WHERE u.verified <> 0
            ORDER BY r.reputation DESC, u.name
            LIMIT 100
            """,
        )
        credit: list[dict[str, Any]] = []
        seen_credit_users: set[int] = set()
        for row in credit_rows:
            user_id = int(row["user_id"])
            if user_id in seen_credit_users:
                continue
            seen_credit_users.add(user_id)
            snapshot = faircroft_credit_snapshot(int(row.get("reputation") or 0))
            credit.append(
                {
                    "user_id": user_id,
                    "name": str(row.get("player_name") or row.get("name") or "Linked player"),
                    "resident_name": str(row.get("name") or ""),
                    "civ_number": str(row.get("civ_number") or ""),
                    "score": int(snapshot["score"] or 0),
                    "rating": snapshot["rating"],
                    "reputation": int(snapshot["reputation"] or 0),
                    "synced_at": row.get("synced_at"),
                    "source_key": str(row.get("player_key") or ""),
                }
            )

        month_start = dt.datetime.now(dt.timezone.utc).date().replace(day=1).isoformat()
        snapshot_rows = all_rows(
            db,
            """
            SELECT metric_key, subject_key, snapshot_day, metric_value
            FROM leaderboard_metric_snapshots
            WHERE snapshot_day >= ?
              AND metric_key IN ('bank_balance', 'reputation')
            ORDER BY snapshot_day ASC
            """,
            (month_start,),
        )
        snapshot_ranges: dict[tuple[str, str], list[float]] = {}
        for snapshot in snapshot_rows:
            key = (str(snapshot["metric_key"]), str(snapshot["subject_key"]).casefold())
            snapshot_ranges.setdefault(key, []).append(float(snapshot.get("metric_value") or 0))
        bank_growth = []
        for item in wealth:
            values = snapshot_ranges.get(("bank_balance", item["source_key"].casefold()), [])
            if len(values) >= 2:
                bank_growth.append({**item, "growth": round(values[-1] - values[0], 2)})
        credit_improvement = []
        for item in credit:
            values = snapshot_ranges.get(("reputation", item["source_key"].casefold()), [])
            if len(values) >= 2:
                first_score = int(faircroft_credit_snapshot(int(values[0]))["score"])
                last_score = int(faircroft_credit_snapshot(int(values[-1]))["score"])
                credit_improvement.append({**item, "score_gain": last_score - first_score})

        def activity_board(sql: str, metric: str, params: tuple[Any, ...] = ()) -> list[dict[str, Any]]:
            rows = all_rows(db, sql, params)
            return [
                {
                    "user_id": int(row["user_id"]),
                    "name": str(row.get("player_name") or row.get("name") or "Faircroft resident"),
                    "resident_name": str(row.get("name") or ""),
                    "civ_number": str(row.get("civ_number") or ""),
                    metric: metric_int(row.get(metric)),
                }
                for row in rows
                if metric_int(row.get(metric)) > 0
            ]

        monthly_activity = activity_board(
            """
            SELECT u.id AS user_id, u.name, u.civ_number, l.player_name,
                   COALESCE(SUM(p.seconds), 0) AS monthly_seconds
            FROM user_presence p
            JOIN users u ON u.id = p.user_id
            LEFT JOIN arma_account_links l ON l.user_id = u.id
            WHERE p.day >= ?
            GROUP BY u.id, u.name, u.civ_number, l.player_name
            ORDER BY monthly_seconds DESC
            LIMIT 100
            """,
            "monthly_seconds",
            (month_start,),
        )
        vehicle_owners = activity_board(
            """
            SELECT u.id AS user_id, u.name, u.civ_number, l.player_name, COUNT(v.id) AS vehicle_count
            FROM dmv_vehicles v JOIN users u ON u.id = v.user_id
            LEFT JOIN arma_account_links l ON l.user_id = u.id
            GROUP BY u.id, u.name, u.civ_number, l.player_name
            ORDER BY vehicle_count DESC LIMIT 100
            """,
            "vehicle_count",
        )
        citations_received = activity_board(
            """
            SELECT u.id AS user_id, u.name, u.civ_number, l.player_name, COUNT(c.id) AS citation_count
            FROM citations c JOIN users u ON u.id = c.civ_id
            LEFT JOIN arma_account_links l ON l.user_id = u.id
            WHERE c.record_expunged_at IS NULL
            GROUP BY u.id, u.name, u.civ_number, l.player_name
            ORDER BY citation_count DESC LIMIT 100
            """,
            "citation_count",
        )
        citations_issued = activity_board(
            """
            SELECT u.id AS user_id, u.name, u.civ_number, l.player_name, COUNT(c.id) AS citation_count
            FROM citations c JOIN users u ON u.id = c.officer_id
            LEFT JOIN arma_account_links l ON l.user_id = u.id
            GROUP BY u.id, u.name, u.civ_number, l.player_name
            ORDER BY citation_count DESC LIMIT 100
            """,
            "citation_count",
        )
        arrests = activity_board(
            """
            SELECT u.id AS user_id, u.name, u.civ_number, l.player_name, COUNT(b.id) AS arrest_count
            FROM mdt_bookings b JOIN users u ON u.id = b.officer_id
            LEFT JOIN arma_account_links l ON l.user_id = u.id
            GROUP BY u.id, u.name, u.civ_number, l.player_name
            ORDER BY arrest_count DESC LIMIT 100
            """,
            "arrest_count",
        )
        most_wanted = activity_board(
            """
            SELECT u.id AS user_id, u.name, u.civ_number, l.player_name, COUNT(w.id) AS warrant_count
            FROM cid_warrants w JOIN users u ON u.id = w.subject_civ_id
            LEFT JOIN arma_account_links l ON l.user_id = u.id
            WHERE LOWER(w.status) = 'active'
            GROUP BY u.id, u.name, u.civ_number, l.player_name
            ORDER BY warrant_count DESC LIMIT 100
            """,
            "warrant_count",
        )
        court_victories = activity_board(
            """
            SELECT u.id AS user_id, u.name, u.civ_number, l.player_name, COUNT(c.id) AS victory_count
            FROM citations c JOIN users u ON u.id = c.civ_id
            LEFT JOIN arma_account_links l ON l.user_id = u.id
            WHERE LOWER(COALESCE(c.final_result, '') || ' ' || COALESCE(c.disposition, ''))
                  SIMILAR TO ?
            GROUP BY u.id, u.name, u.civ_number, l.player_name
            ORDER BY victory_count DESC LIMIT 100
            """,
            "victory_count",
            ("%(not guilty|dismiss)%",),
        )
        reports_submitted = activity_board(
            """
            SELECT u.id AS user_id, u.name, u.civ_number, l.player_name, COUNT(r.id) AS report_count
            FROM cad_after_call_reports r JOIN users u ON u.id = r.officer_id
            LEFT JOIN arma_account_links l ON l.user_id = u.id
            GROUP BY u.id, u.name, u.civ_number, l.player_name
            ORDER BY report_count DESC LIMIT 100
            """,
            "report_count",
        )
        press_submitted = activity_board(
            """
            SELECT u.id AS user_id, u.name, u.civ_number, l.player_name, COUNT(r.id) AS report_count
            FROM press_reports r JOIN users u ON u.id = r.author_id
            LEFT JOIN arma_account_links l ON l.user_id = u.id
            GROUP BY u.id, u.name, u.civ_number, l.player_name
            ORDER BY report_count DESC LIMIT 100
            """,
            "report_count",
        )
        community_veterans = [
            {
                "user_id": int(row["user_id"]),
                "name": str(row.get("player_name") or row.get("name") or "Faircroft resident"),
                "resident_name": str(row.get("name") or ""),
                "civ_number": str(row.get("civ_number") or ""),
                "created_at": row.get("created_at"),
                "member_days": max(
                    0,
                    (
                        dt.datetime.now(dt.timezone.utc)
                        - parse_iso(str(row.get("created_at") or ""))
                    ).days,
                ),
            }
            for row in all_rows(
                db,
                """
                SELECT u.id AS user_id, u.name, u.civ_number, u.created_at, l.player_name
                FROM users u LEFT JOIN arma_account_links l ON l.user_id = u.id
                WHERE u.verified <> 0 ORDER BY u.created_at ASC LIMIT 100
                """,
            )
        ]
        clean_drivers = activity_board(
            """
            SELECT u.id AS user_id, u.name, u.civ_number, l.player_name,
                   COUNT(v.id) AS compliant_vehicles
            FROM users u JOIN dmv_records d ON d.user_id = u.id
            JOIN dmv_vehicles v ON v.user_id = u.id
            LEFT JOIN arma_account_links l ON l.user_id = u.id
            WHERE LOWER(d.license_status) = 'valid'
              AND LOWER(v.registration_status) = 'active'
              AND LOWER(v.insurance_status) = 'active'
              AND NOT EXISTS (
                  SELECT 1 FROM citations c
                  WHERE c.civ_id = u.id AND c.record_expunged_at IS NULL
              )
            GROUP BY u.id, u.name, u.civ_number, l.player_name
            ORDER BY compliant_vehicles DESC LIMIT 100
            """,
            "compliant_vehicles",
        )
        public_safety = activity_board(
            """
            SELECT u.id AS user_id, u.name, u.civ_number, l.player_name,
                   (
                     (SELECT COUNT(*) FROM citations c WHERE c.officer_id = u.id)
                     + (SELECT COUNT(*) * 3 FROM mdt_bookings b WHERE b.officer_id = u.id)
                     + (SELECT COUNT(*) * 2 FROM cad_after_call_reports r WHERE r.officer_id = u.id)
                     + (SELECT COUNT(*) * 2 FROM mdt_bolos bo WHERE bo.created_by = u.id AND LOWER(bo.status) <> 'active')
                   ) AS safety_score
            FROM users u LEFT JOIN arma_account_links l ON l.user_id = u.id
            WHERE LOWER(u.roles) LIKE ?
               OR LOWER(u.roles) LIKE ?
               OR LOWER(u.roles) LIKE ?
               OR LOWER(u.roles) LIKE ?
            ORDER BY safety_score DESC LIMIT 100
            """,
            "safety_score",
            ("%leo%", "%sheriff%", "%fire%", "%ems%"),
        )

        reputation = [{**item, "reputation_score": item["reputation"]} for item in credit]
        current_sessions = [item for item in telemetry if item["online"] and item["current_session_seconds"] > 0]
        role_time = {
            "leo_hours": [item for item in telemetry if any(role in item["roles"] for role in ("leo", "sheriff", "police"))],
            "fire_hours": [item for item in telemetry if any(role in item["roles"] for role in ("fire", "ems"))],
            "civ_hours": [item for item in telemetry if "civ" in item["roles"]],
        }
        telemetry = eligible(telemetry)
        wealth = eligible(wealth)
        bank_growth = eligible(bank_growth)
        credit = eligible(credit)
        credit_improvement = eligible(credit_improvement)
        reputation = eligible(reputation)
        current_sessions = eligible(current_sessions)
        monthly_activity = eligible(monthly_activity)
        vehicle_owners = eligible(vehicle_owners)
        citations_received = eligible(citations_received)
        citations_issued = eligible(citations_issued)
        arrests = eligible(arrests)
        most_wanted = eligible(most_wanted)
        court_victories = eligible(court_victories)
        reports_submitted = eligible(reports_submitted)
        press_submitted = eligible(press_submitted)
        community_veterans = eligible(community_veterans)
        clean_drivers = eligible(clean_drivers)
        public_safety = eligible(public_safety)
        role_time = {key: eligible(items) for key, items in role_time.items()}
        current_user_excluded = int(user["id"]) in staff_user_ids
        ranked_boards = {
            "wealth": ranked(wealth, "balance"),
            "bank_growth": ranked([item for item in bank_growth if item["growth"] > 0], "growth"),
            "playtime": ranked([item for item in telemetry if item["playtime_seconds"] > 0], "playtime_seconds"),
            "monthly_activity": ranked(monthly_activity, "monthly_seconds"),
            "current_session": ranked(current_sessions, "current_session_seconds"),
            "deaths": ranked([item for item in telemetry if item["deaths"] > 0], "deaths"),
            "kills": ranked([item for item in telemetry if item["kills"] > 0], "kills"),
            "suicides": ranked([item for item in telemetry if item["suicides"] > 0], "suicides"),
            "kd_ratio": ranked([item for item in telemetry if item["kills"] >= 5], "kd_ratio"),
            "credit": ranked(credit, "score"),
            "credit_improvement": ranked([item for item in credit_improvement if item["score_gain"] > 0], "score_gain"),
            "reputation": ranked(reputation, "reputation_score"),
            "vehicles": ranked(vehicle_owners, "vehicle_count"),
            "citations_received": ranked(citations_received, "citation_count"),
            "citations_issued": ranked(citations_issued, "citation_count"),
            "arrests": ranked(arrests, "arrest_count"),
            "most_wanted": ranked(most_wanted, "warrant_count"),
            "court_victories": ranked(court_victories, "victory_count"),
            "cases_filed": ranked(citations_issued, "citation_count"),
            "reports_submitted": ranked(reports_submitted, "report_count"),
            "press_reports": ranked(press_submitted, "report_count"),
            "community_veteran": ranked(community_veterans, "member_days"),
            "leo_hours": ranked(role_time["leo_hours"], "playtime_seconds"),
            "fire_hours": ranked(role_time["fire_hours"], "playtime_seconds"),
            "civ_hours": ranked(role_time["civ_hours"], "playtime_seconds"),
            "clean_driver": ranked(clean_drivers, "compliant_vehicles"),
            "public_safety_mvp": ranked(public_safety, "safety_score"),
        }
        point_totals: dict[int, int] = {}
        for board_rows in ranked_boards.values():
            for row in board_rows:
                if not row.get("user_id"):
                    continue
                placement_points = max(25, 1000 - ((int(row["rank"]) - 1) * 35))
                row["division_points"] = placement_points
                point_totals[int(row["user_id"])] = point_totals.get(int(row["user_id"]), 0) + placement_points
        existing_progress = {int(row["user_id"]): row for row in all_rows(db, "SELECT * FROM leaderboard_progress")}
        for progress_user_id, earned in point_totals.items():
            previous = existing_progress.get(progress_user_id)
            redeemed_points = int(previous["redeemed_points"] or 0) if previous else 0
            # Keep redeemed points spent.  Rebuilding the leaderboard must not
            # refill a user's wallet from the raw placement total on every GET.
            available_from_rank = max(0, int(earned) - redeemed_points)
            season_points = max(int(previous["season_points"] or 0) if previous else 0, available_from_rank)
            lifetime_points = max(int(previous["lifetime_points"] or 0) if previous else 0, int(earned))
            db.execute("""INSERT INTO leaderboard_progress (user_id,season_points,lifetime_points,updated_at)
                VALUES (?,?,?,?) ON CONFLICT (user_id) DO UPDATE SET season_points=EXCLUDED.season_points,
                lifetime_points=EXCLUDED.lifetime_points,updated_at=EXCLUDED.updated_at""",
                (progress_user_id, season_points, lifetime_points, now_iso()))
        progress = one(db, "SELECT * FROM leaderboard_progress WHERE user_id=?", (user["id"],))
        points = int(progress["season_points"] or 0) if progress else 0
        lifetime_points = int(progress["lifetime_points"] or 0) if progress else points
        tiers = [("Bronze", 0), ("Silver", 500), ("Gold", 1250), ("Platinum", 2500), ("Diamond", 5000), ("Master", 9000), ("Apex", 15000), ("Crown", 25000)]
        current_tier = tiers[0]
        next_tier = None
        for tier in tiers:
            if points >= tier[1]:
                current_tier = tier
            elif next_tier is None:
                next_tier = tier
        span = max(1, (next_tier[1] - current_tier[1]) if next_tier else 1)
        tier_percent = 100 if not next_tier else max(0, min(100, round((points - current_tier[1]) / span * 100)))
        progression = {
            "points": points,
            "lifetime_points": lifetime_points,
            "redeemed_points": int(progress["redeemed_points"] or 0) if progress else 0,
            "division": current_tier[0],
            "next_division": next_tier[0] if next_tier else None,
            "next_threshold": next_tier[1] if next_tier else points,
            "progress_percent": tier_percent,
            "ranked_boards": sum(1 for board_rows in ranked_boards.values() if any(int(row.get("user_id") or 0) == int(user["id"]) for row in board_rows)),
            "perks": [
                {"type": "lottery_entry", "cost": 250, "label": "Bonus lottery entry", "detail": "Add one verified chance to the next Faircroft drawing."},
                {"type": "stock_share", "cost": 750, "label": "Starter stock share", "detail": "Receive one free share in the active Faircroft market."},
            ],
        }
        self.send_json(
            200,
            {
                "generated_at": now_iso(),
                "summary": {
                    "tracked_players": len(telemetry),
                    "online_players": sum(1 for item in telemetry if item["online"]),
                    "synced_balances": len(wealth),
                    "synced_credit_profiles": len(credit),
                    "staff_excluded": len(staff_user_ids),
                },
                "current_user_excluded": current_user_excluded,
                "boards": ranked_boards,
                "progression": progression,
                "sources": {
                    "wealth": "FCRPMUSSALO live bank sync",
                    "bank_growth": "Bank snapshot history begins after deployment",
                    "playtime": f"SHS {SHADOWHAVEN_ANTICHEAT_DATABASE_FILE}",
                    "monthly_activity": "RP OS monthly verified presence",
                    "current_session": f"SHS {SHADOWHAVEN_ANTICHEAT_DATABASE_FILE}",
                    "deaths": f"SHS {SHADOWHAVEN_ANTICHEAT_DATABASE_FILE}",
                    "kills": f"SHS {SHADOWHAVEN_ANTICHEAT_DATABASE_FILE}",
                    "suicides": f"SHS {SHADOWHAVEN_ANTICHEAT_DATABASE_FILE}",
                    "kd_ratio": f"SHS {SHADOWHAVEN_ANTICHEAT_DATABASE_FILE}",
                    "credit": "MedicalHud reputation credit model",
                    "credit_improvement": "Credit snapshot history begins after deployment",
                    "reputation": "MedicalHud synchronized reputation",
                    "vehicles": "Faircroft DMV and FCRPMUSSALO vehicle records",
                    "citations_received": "Faircroft court and citation ledger",
                    "citations_issued": "Faircroft citation ledger",
                    "arrests": "Faircroft MDT booking ledger",
                    "most_wanted": "Active CID warrant registry",
                    "court_victories": "Completed Faircroft court decisions",
                    "cases_filed": "Faircroft court filings",
                    "reports_submitted": "CAD after-action reports",
                    "press_reports": "FNN Press Desk submissions",
                    "community_veteran": "Verified RP OS account registry",
                    "leo_hours": f"SHS {SHADOWHAVEN_ANTICHEAT_DATABASE_FILE} and account roles",
                    "fire_hours": f"SHS {SHADOWHAVEN_ANTICHEAT_DATABASE_FILE} and account roles",
                    "civ_hours": f"SHS {SHADOWHAVEN_ANTICHEAT_DATABASE_FILE} and account roles",
                    "clean_driver": "DMV compliance and citation records",
                    "public_safety_mvp": "CAD, MDT, BOLO, and report activity",
                },
            },
        )

    def api_leaderboard_perk(self, db: Database, user: DbRow | None) -> None:
        err = verified_required(user)
        if err:
            self.error(403 if user else 401, err)
            return
        assert user is not None
        if "staff" in roles_for(user):
            self.error(403, "Staff observer accounts cannot redeem competitive perks.")
            return
        payload = self.read_json()
        perk_type = str(payload.get("perk_type") or "").strip().lower()
        perks = {
            "lottery_entry": (250, "Bonus Faircroft Lottery entry"),
            "stock_share": (750, "One free share in the active Faircroft market"),
        }
        if perk_type not in perks:
            self.error(400, "Choose a valid leaderboard perk.")
            return
        cost, reward_label = perks[perk_type]
        progress = one(db, "SELECT * FROM leaderboard_progress WHERE user_id=?", (user["id"],))
        if not progress or int(progress["season_points"] or 0) < cost:
            self.error(409, f"You need {cost:,} rank points for this perk.")
            return
        summary = reward_label
        if perk_type == "lottery_entry":
            settings = get_system_settings(db)
            if not settings["lottery_enabled"]:
                self.error(409, "Lottery entries are currently closed.")
                return
            excluded = sorted(set(roles_for(user)) & set(settings["lottery_excluded_roles"]))
            if excluded:
                self.error(403, "This account is excluded from lottery participation by role policy.")
                return
            draw = ensure_lottery_draw(db, settings)
            today = utcnow().astimezone(ZoneInfo(settings["lottery_timezone"])).date().isoformat()
            one(db, "SELECT id FROM users WHERE id=? FOR UPDATE", (user["id"],))
            next_number = int(one(db, "SELECT COALESCE(MAX(entry_number),0) AS maximum FROM lottery_entries WHERE user_id=? AND entry_date=?", (user["id"], today))["maximum"] or 0) + 1
            weight = max([settings["lottery_role_weights"].get(role, 1.0) for role in roles_for(user)] or [1.0])
            db.execute("INSERT INTO lottery_entries (draw_id,user_id,entry_date,entry_number,role_weight,source,created_at) VALUES (?,?,?,?,?,'leaderboard_perk',?)", (draw["id"], user["id"], today, next_number, weight, now_iso()))
            summary = f"Bonus lottery entry FC-{next_number:02d}"
        else:
            security = one(db, "SELECT * FROM market_securities WHERE active<>0 ORDER BY id LIMIT 1")
            if not security:
                self.error(409, "No active market security is available for this perk.")
                return
            account = one(db, "SELECT * FROM market_accounts WHERE user_id=?", (user["id"],))
            if not account:
                ts = now_iso()
                db.execute("INSERT INTO market_accounts (user_id,cash_balance,status,created_at,updated_at) VALUES (?,?,?,?,?)", (user["id"], 0, "active", ts, ts))
                account = one(db, "SELECT * FROM market_accounts WHERE user_id=?", (user["id"],))
            db.execute("""INSERT INTO market_holdings (account_id,security_id,quantity,average_cost) VALUES (?,?,?,0)
                ON CONFLICT (account_id,security_id) DO UPDATE SET quantity=market_holdings.quantity+EXCLUDED.quantity""", (account["id"], security["id"], 1))
            summary = f"1 share of {security['ticker']}"
        updated = one(db, """UPDATE leaderboard_progress SET season_points=season_points-?, redeemed_points=redeemed_points+?, updated_at=?
            WHERE user_id=? AND season_points>=? RETURNING season_points,redeemed_points""", (cost, cost, now_iso(), user["id"], cost))
        if not updated:
            self.error(409, "Your rank points changed. Refresh the leaderboard and try again.")
            return
        db.execute("INSERT INTO leaderboard_perk_redemptions (user_id,perk_type,cost,reward_summary,created_at) VALUES (?,?,?,?,?)", (user["id"], perk_type, cost, summary, now_iso()))
        add_admin_audit(db, int(user["id"]), "leaderboard.perk.redeemed", int(user["id"]), {"perk": perk_type, "cost": cost, "reward": summary})
        self.send_json(201, {"ok": True, "perk_type": perk_type, "reward_summary": summary, "points": int(updated["season_points"] or 0)})

    def api_generate_fnn(self, user: DbRow | None) -> None:
        if not user or not has_any(user, "owner", "dev"):
            self.error(403 if user else 401, "Developer access required")
            return
        result = generate_fnn_daily_edition(force=True)
        status = 201 if result["status"] == "published" else 200
        self.send_json(status, result)

    def api_press_reports(self, db: Database, user: DbRow | None) -> None:
        err = press_required(user)
        if err:
            self.error(403 if user else 401, err)
            return
        assert user is not None
        rows = all_rows(
            db,
            """
            SELECT r.*, u.name AS author_name
            FROM press_reports r
            JOIN users u ON u.id = r.author_id
            WHERE r.author_id = ? OR ? = 1
            ORDER BY r.created_at DESC
            LIMIT 100
            """,
            (user["id"], int(has_any(user, "owner", "dev"))),
        )
        top_story = one(db, """SELECT r.id,r.report_number,r.headline,u.name AS author_name
            FROM press_reports r JOIN users u ON u.id=r.author_id
            WHERE r.top_story=1 ORDER BY r.updated_at DESC LIMIT 1""")
        self.send_json(200, {
            "reports": [dict(row) for row in rows],
            "can_admin_delete": admin_required(user) is None,
            "top_story_available": top_story is None,
            "top_story_slot": dict(top_story) if top_story else None,
        })

    def api_create_press_report(self, db: Database, user: DbRow | None) -> None:
        err = press_required(user)
        if err:
            self.error(403 if user else 401, err)
            return
        assert user is not None
        payload = self.read_json()
        headline = str(payload.get("headline") or "").strip()[:180]
        facts = str(payload.get("facts") or "").strip()[:10000]
        if len(headline) < 5 or len(facts) < 80:
            self.error(400, "A headline and at least 80 characters of verified story facts are required")
            return
        category = str(payload.get("category") or "community").strip().lower()[:40]
        if category not in ("breaking", "community", "public_safety", "justice", "business", "events", "government", "opinion"):
            category = "community"
        wants_top_story = str(payload.get("top_story") or "").strip().lower() in ("1", "true", "yes", "on")
        if wants_top_story and one(db, "SELECT id FROM press_reports WHERE top_story=1 LIMIT 1"):
            self.error(409, "The Top Story slot is already reserved for this news cycle. It will reopen after the next edition publishes.")
            return
        ts = now_iso()
        created = db.execute(
            """
            INSERT INTO press_reports
            (report_number, author_id, headline, category, location, event_at, people,
             organizations, facts, quotes, background, public_impact, verification_notes,
             top_story, status, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'submitted', ?, ?)
            RETURNING id, report_number
            """,
            (
                generate_record_number(db, "press_reports", "report_number", "PRESS"),
                user["id"], headline, category,
                str(payload.get("location") or "").strip()[:240],
                str(payload.get("event_at") or "").strip()[:80],
                str(payload.get("people") or "").strip()[:2000],
                str(payload.get("organizations") or "").strip()[:2000],
                facts,
                str(payload.get("quotes") or "").strip()[:6000],
                str(payload.get("background") or "").strip()[:6000],
                str(payload.get("public_impact") or "").strip()[:4000],
                str(payload.get("verification_notes") or "").strip()[:4000],
                int(wants_top_story),
                ts, ts,
            ),
        ).fetchone()
        add_admin_audit(
            db,
            int(user["id"]),
            "press.report.submitted",
            int(user["id"]),
            {"report_number": str(created["report_number"]), "headline": headline, "category": category, "top_story": wants_top_story},
        )
        saved = one(
            db,
            """
            SELECT r.*, u.name AS author_name
            FROM press_reports r
            JOIN users u ON u.id = r.author_id
            WHERE r.id = ?
            """,
            (created["id"],),
        )
        add_message(
            db,
            int(user["id"]),
            "FNN story brief received",
            f"{created['report_number']} has been filed with the FNN newsroom and is available to the edition generator.",
        )
        self.send_json(
            201,
            {
                "ok": True,
                "id": int(created["id"]),
                "report_number": created["report_number"],
                "newsroom_eligible": True,
                "report": dict(saved) if saved else None,
            },
        )

    def api_admin_delete_press_report(self, db: Database, user: DbRow | None, report_id: int) -> None:
        err = fnn_content_control_required(user)
        if err:
            self.error(403 if user else 401, err); return
        report = one(db, "SELECT * FROM press_reports WHERE id = ?", (report_id,))
        if not report:
            self.error(404, "Press story not found"); return
        db.execute("DELETE FROM press_reports WHERE id = ?", (report_id,))
        add_admin_audit(db, int(user["id"]), "press.report.deleted", int(report["author_id"]), {
            "report_id": report_id, "report_number": report.get("report_number"), "headline": report.get("headline"),
            "status": report.get("status"), "reason": "Individual newsroom story removed by administrator",
        })
        self.send_json(200, {"ok": True, "deleted_id": report_id, "report_number": report.get("report_number")})

    def api_admin_delete_fnn_story(self, db: Database, user: DbRow | None, edition_id: int, story_index: int) -> None:
        err = fnn_content_control_required(user)
        if err:
            self.error(403 if user else 401, err); return
        edition = one(db, "SELECT * FROM fnn_editions WHERE id = ?", (edition_id,))
        if not edition:
            self.error(404, "FNN edition not found"); return
        try:
            stories = json.loads(edition.get("stories_json") or "[]")
        except (TypeError, json.JSONDecodeError):
            stories = []
        if story_index < 0 or story_index >= len(stories):
            self.error(404, "FNN story not found"); return
        removed = stories.pop(story_index)
        db.execute("UPDATE fnn_editions SET stories_json = ? WHERE id = ?", (json.dumps(stories, separators=(",", ":"), ensure_ascii=False), edition_id))
        add_admin_audit(db, int(user["id"]), "fnn.story.deleted", details={
            "edition_id": edition_id, "edition_date": edition.get("edition_date"), "story_index": story_index,
            "headline": removed.get("headline") if isinstance(removed, dict) else "Untitled story",
            "reason": "Individual published story removed by administrator",
        })
        self.send_json(200, {"ok": True, "edition_id": edition_id, "deleted_story_index": story_index})

    def api_roadmap(self, db: Database, user: DbRow | None) -> None:
        if not user:
            self.error(401, "Authentication required")
            return
        can_manage = has_any(user, "owner", "admin")
        visibility_sql = "" if can_manage else "WHERE i.is_visible = 1"
        rows = all_rows(
            db,
            f"""
            SELECT i.*,
                   (SELECT COUNT(*) FROM roadmap_votes rv WHERE rv.item_id = i.id AND rv.vote = 1) AS upvotes,
                   (SELECT COUNT(*) FROM roadmap_votes rv WHERE rv.item_id = i.id AND rv.vote = -1) AS downvotes,
                   COALESCE((SELECT rv.vote FROM roadmap_votes rv WHERE rv.item_id = i.id AND rv.user_id = ?), 0) AS user_vote
            FROM roadmap_items i
            {visibility_sql}
            ORDER BY i.sort_order, i.id
            """,
            (user["id"],),
        )
        items: list[dict[str, Any]] = []
        for row in rows:
            item = dict(row)
            item["progress"] = int(item.get("progress") or 0)
            item["sort_order"] = int(item.get("sort_order") or 0)
            item["is_visible"] = bool(item.get("is_visible"))
            item["upvotes"] = int(item.get("upvotes") or 0)
            item["downvotes"] = int(item.get("downvotes") or 0)
            item["score"] = item["upvotes"] - item["downvotes"]
            item["user_vote"] = int(item.get("user_vote") or 0)
            items.append(item)
        public_items = [item for item in items if item["is_visible"]]
        active = [item for item in public_items if item["status"] in ("building", "next")]
        shipped = [item for item in public_items if item["status"] == "shipped"]
        total_votes = sum(item["upvotes"] + item["downvotes"] for item in public_items)
        overall_progress = round(sum(item["progress"] for item in public_items) / max(len(public_items), 1))
        android = next((item for item in public_items if item["slug"] == "android-app-parity"), None)
        android_days = None
        if android and android.get("target_date"):
            android_days = max(0, (dt.date.fromisoformat(str(android["target_date"])) - utcnow().date()).days)
        self.send_json(
            200,
            {
                "items": items,
                "can_manage": can_manage,
                "stats": {
                    "overall_progress": overall_progress,
                    "active_phases": len(active),
                    "shipped_phases": len(shipped),
                    "community_votes": total_votes,
                    "android_days": android_days,
                    "android_target": android.get("target_date") if android else None,
                },
                "options": {
                    "statuses": list(ROADMAP_STATUSES),
                    "accents": list(ROADMAP_ACCENTS),
                    "icons": list(ROADMAP_ICONS),
                },
            },
        )

    def api_vote_roadmap_item(self, db: Database, user: DbRow | None, item_id: int) -> None:
        if not user:
            self.error(401, "Authentication required")
            return
        item = one(db, "SELECT id, is_visible FROM roadmap_items WHERE id = ?", (item_id,))
        if not item or (not bool(item["is_visible"]) and not has_any(user, "owner", "admin")):
            self.error(404, "Roadmap milestone not found")
            return
        payload = self.read_json()
        try:
            vote = int(payload.get("vote", 0))
        except (TypeError, ValueError):
            self.error(400, "Vote must be up, down, or cleared")
            return
        if vote not in (-1, 0, 1):
            self.error(400, "Vote must be up, down, or cleared")
            return
        if vote == 0:
            db.execute("DELETE FROM roadmap_votes WHERE item_id = ? AND user_id = ?", (item_id, user["id"]))
        else:
            db.execute(
                """
                INSERT INTO roadmap_votes (item_id, user_id, vote, updated_at)
                VALUES (?, ?, ?, ?)
                ON CONFLICT (item_id, user_id)
                DO UPDATE SET vote = excluded.vote, updated_at = excluded.updated_at
                """,
                (item_id, user["id"], vote, now_iso()),
            )
        counts = one(
            db,
            """
            SELECT
                (SELECT COUNT(*) FROM roadmap_votes WHERE item_id = ? AND vote = 1) AS upvotes,
                (SELECT COUNT(*) FROM roadmap_votes WHERE item_id = ? AND vote = -1) AS downvotes
            """,
            (item_id, item_id),
        ) or {"upvotes": 0, "downvotes": 0}
        upvotes = int(counts["upvotes"] or 0)
        downvotes = int(counts["downvotes"] or 0)
        self.send_json(200, {"ok": True, "item_id": item_id, "user_vote": vote, "upvotes": upvotes, "downvotes": downvotes, "score": upvotes - downvotes})

    def api_create_roadmap_item(self, db: Database, user: DbRow | None) -> None:
        err = admin_required(user)
        if err:
            self.error(403 if user else 401, err)
            return
        assert user is not None
        payload = self.read_json()
        values = roadmap_payload_values(payload)
        slug_base = "".join(character.lower() if character.isalnum() else "-" for character in values["title"])
        slug_base = "-".join(part for part in slug_base.split("-") if part)[:70] or "milestone"
        slug = slug_base
        suffix = 2
        while one(db, "SELECT id FROM roadmap_items WHERE slug = ?", (slug,)):
            slug = f"{slug_base[:64]}-{suffix}"
            suffix += 1
        ts = now_iso()
        created = db.execute(
            """
            INSERT INTO roadmap_items
            (slug, title, category, summary, details, status, progress, target_date, sort_order, accent, icon, is_visible, created_by, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            RETURNING id
            """,
            (
                slug,
                values["title"],
                values["category"],
                values["summary"],
                values["details"],
                values["status"],
                values["progress"],
                values["target_date"],
                values["sort_order"],
                values["accent"],
                values["icon"],
                values["is_visible"],
                user["id"],
                ts,
                ts,
            ),
        ).fetchone()
        self.send_json(201, {"ok": True, "id": int(created["id"]), "slug": slug})

    def api_update_roadmap_item(self, db: Database, user: DbRow | None, item_id: int) -> None:
        err = admin_required(user)
