    def api_profile_update_photo(self, db: Database, user: DbRow | None) -> None:
        if not user:
            self.error(401, "Authentication required")
            return
        photo = str(self.read_json().get("profile_photo") or "").strip()
        if not photo.startswith(("data:image/jpeg;base64,", "data:image/png;base64,", "data:image/webp;base64,")):
            self.error(400, "Profile photo must be a JPEG, PNG, or WebP image")
            return
        if len(photo) > 1_500_000:
            self.error(413, "Profile photo is too large; use a cropped face image under 1 MB")
            return
        db.execute("UPDATE users SET profile_photo = ? WHERE id = ?", (photo, user["id"]))
        self.send_json(200, {"ok": True, "profile_photo": photo})

    def api_profile_activate_character(self, db: Database, user: DbRow | None, character_id: int) -> None:
        if not user:
            self.error(401, "Authentication required")
            return
        character = one(db, "SELECT * FROM user_characters WHERE id = ? AND user_id = ?", (character_id, user["id"]))
        if not character:
            self.error(404, "Character not found")
            return
        if character["status"] != "active":
            self.error(409, "Only active characters can be selected")
            return
        ts = now_iso()
        db.execute("UPDATE user_characters SET is_active = 0 WHERE user_id = ?", (user["id"],))
        db.execute("UPDATE user_characters SET is_active = 1, updated_at = ? WHERE id = ?", (ts, character_id))
        db.execute("UPDATE users SET active_character_id = ?, name = ? WHERE id = ?", (character_id, character["character_name"], user["id"]))
        self.send_json(200, {"ok": True, "active_character_id": character_id, "name": character["character_name"]})

    def api_profile_assign_character_record(self, db: Database, user: DbRow | None) -> None:
        if not user:
            self.error(401, "Authentication required")
            return
        payload = self.read_json()
        record_type = str(payload.get("record_type") or "").strip()
        table_config = CHARACTER_RECORD_TABLES.get(record_type)
        if not table_config:
            self.error(400, "Unknown character record type")
            return
        try:
            record_id = int(payload.get("record_id"))
            character = require_owned_character(db, int(user["id"]), payload.get("character_id"))
        except (TypeError, ValueError) as exc:
            self.error(400, str(exc))
            return
        table, owner_column, _label, _date = table_config
        owned = one(
            db,
            f"SELECT id, character_id FROM {table} WHERE id = ? AND {owner_column} = ?",
            (record_id, user["id"]),
        )
        if not owned:
            self.error(404, "Record not found on this account")
            return
        if owned.get("character_id") is not None:
            self.error(409, "This record is already assigned to a character")
            return
        if record_type == "vehicle":
            vehicle = one(db, "SELECT * FROM dmv_vehicles WHERE id=?", (record_id,))
            if not vehicle or not imported_vehicle_belongs_to_account(db, int(user["id"]), vehicle):
                self.error(403, "This imported vehicle is not verified against your linked Arma identity")
                return
        db.execute(f"UPDATE {table} SET character_id = ? WHERE id = ?", (character["id"], record_id))
        add_admin_audit(
            db,
            int(user["id"]),
            "character.legacy_record.assigned",
            int(user["id"]),
            {"record_type": record_type, "record_id": record_id, "character_id": int(character["id"])},
        )
        self.send_json(200, {"ok": True, "remaining": len(unassigned_character_records(db, int(user["id"])))})

    def api_profile_change_name(self, db: Database, user: DbRow | None) -> None:
        if not user:
            self.error(401, "Authentication required")
            return
        active_character = ensure_default_character(db, int(user["id"]), str(user["name"] or "Civilian"))
        status = name_change_status(db, int(user["id"]))
        if status["locked"]:
            self.error(423, "Name changes are locked until an admin unlocks this account.")
            return
        if status["used"] >= NAME_CHANGE_LIMIT:
            db.execute("UPDATE users SET name_change_locked = 1 WHERE id = ?", (user["id"],))
            self.error(423, "Name change limit reached. An admin must unlock this account before another name change.")
            return
        payload = self.read_json()
        new_name = clean_character_name(payload.get("name") or payload.get("character_name"))
        old_name = str(active_character["character_name"])
        if old_name.lower() == new_name.lower():
            self.error(400, "New name must be different from the current name")
            return
        ts = now_iso()
        db.execute("UPDATE user_characters SET character_name = ?, updated_at = ? WHERE id = ?", (new_name, ts, active_character["id"]))
        db.execute("UPDATE users SET name = ? WHERE id = ?", (new_name, user["id"]))
        db.execute(
            "INSERT INTO profile_name_changes (user_id, character_id, old_name, new_name, changed_at) VALUES (?, ?, ?, ?, ?)",
            (user["id"], active_character["id"], old_name, new_name, ts),
        )
        updated_status = name_change_status(db, int(user["id"]))
        if updated_status["used"] >= NAME_CHANGE_LIMIT:
            db.execute("UPDATE users SET name_change_locked = 1 WHERE id = ?", (user["id"],))
            updated_status = name_change_status(db, int(user["id"]))
        add_message(db, user["id"], "Profile name changed", f"Your active character name changed from {old_name} to {new_name}.")
        self.send_json(200, {"ok": True, "name": new_name, "name_change": updated_status})

    def api_claim_arma_link(self, db: Database, user: DbRow | None) -> None:
        if not user:
            self.error(401, "Authentication required")
            return
        payload = self.read_json()
        query = parse_qs(urlparse(self.path).query)
        code_value = (
            payload.get("code")
            or payload.get("LinkCode")
            or payload.get("linkCode")
            or payload.get("link_code")
            or (query.get("code") or [""])[0]
        )
        if not str(code_value or "").strip():
            self.error(400, "No link code was sent. Type the in-game code shown by TBS RP LINKING SYSTEM, for example 1-145595.")
            return
        code = self.normalize_arma_link_code(code_value)
        request = one(
            db,
            """
            SELECT * FROM arma_link_codes
            WHERE (
                    UPPER(code) = UPPER(?)
                    OR REPLACE(REPLACE(UPPER(code), '-', ''), ' ', '') = REPLACE(REPLACE(UPPER(?), '-', ''), ' ', '')
                  )
              AND status = 'pending'
            ORDER BY created_at DESC
            LIMIT 1
            """,
            (code, code),
        )
        if not request:
            self.error(404, "Link code was not found in Railway yet. Wait for the TBS bridge to sync the in-game code, then try again.")
            return
        if parse_iso(request["expires_at"]) < utcnow():
            db.execute("UPDATE arma_link_codes SET status = 'expired' WHERE id = ?", (request["id"],))
            self.error(410, "Link code expired. Generate a fresh code in-game.")
            return
        identity_id = str(request["identity_id"] or "").strip()
        if not identity_id:
            self.error(409, "Link code is missing Arma identity data")
            return
        other = one(db, "SELECT * FROM arma_account_links WHERE identity_id = ? AND user_id <> ?", (identity_id, user["id"]))
        if other:
            self.error(409, "That Arma account is already linked to another PWA profile")
            return
        ts = now_iso()
        db.execute(
            """
            INSERT INTO arma_account_links
            (user_id, server_id, identity_id, uid, rpl_identity, platform, player_name, linked_at, last_seen_at, last_sync_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT (user_id) DO UPDATE SET
                server_id = excluded.server_id,
                identity_id = excluded.identity_id,
                uid = excluded.uid,
                rpl_identity = excluded.rpl_identity,
                platform = excluded.platform,
                player_name = excluded.player_name,
                last_seen_at = excluded.last_seen_at,
                last_sync_at = excluded.last_sync_at
            """,
            (
                user["id"],
                request["server_id"],
                identity_id,
                request.get("uid") or "",
                request.get("rpl_identity") or "",
                request.get("platform") or "",
                request.get("player_name") or "",
                ts,
                request["created_at"],
                ts,
            ),
        )
        db.execute("UPDATE users SET arma_id = ? WHERE id = ?", (identity_id, user["id"]))
        db.execute("UPDATE arma_link_codes SET status = 'claimed', claimed_by = ?, claimed_at = ? WHERE id = ?", (user["id"], ts, request["id"]))
        add_message(db, user["id"], "Arma account linked", f"Linked Arma player {request.get('player_name') or identity_id} from {request['server_id']}.")
        self.send_json(200, {"ok": True})

    def api_unlink_arma(self, db: Database, user: DbRow | None) -> None:
        if not user:
            self.error(401, "Authentication required")
            return
        payload = self.read_json()
        if payload.get("confirmation") != "UNLINK FOR DEVELOPMENT":
            self.error(400, "Confirm that unlinking is for development reasons and is being done with server engineer guidance.")
            return
        dev_code = str(payload.get("dev_code") or "").strip().upper()
        if not dev_code:
            self.error(400, "A specialized developer unlink code is required")
            return
        code_hash = hashlib.sha256(dev_code.encode("utf-8")).hexdigest()
        code_record = one(
            db,
            """
            SELECT * FROM developer_unlink_codes
            WHERE code_hash = ?
              AND revoked_at IS NULL
              AND uses_remaining > 0
              AND expires_at > ?
            """,
            (code_hash, now_iso()),
        )
        if not code_record:
            self.error(403, "Developer unlink code is invalid, expired, or already used")
            return
        link = one(db, "SELECT * FROM arma_account_links WHERE user_id = ?", (user["id"],))
        if not link:
            self.error(404, "No linked Arma account was found")
            return
        db.execute("DELETE FROM arma_account_links WHERE user_id = ?", (user["id"],))
        db.execute("UPDATE users SET arma_id = NULL WHERE id = ?", (user["id"],))
        db.execute(
            "UPDATE arma_link_codes SET status = 'unlinked' WHERE claimed_by = ? AND status = 'claimed'",
            (user["id"],),
        )
        db.execute(
            """
            UPDATE developer_unlink_codes
            SET uses_remaining = uses_remaining - 1, used_by = ?, used_at = ?
            WHERE id = ?
            """,
            (user["id"], now_iso(), code_record["id"]),
        )
        add_admin_audit(
            db,
            int(code_record["created_by"]),
            "arma.development_unlink",
            int(user["id"]),
            {"code_hint": code_record["code_hint"], "identity_id": link["identity_id"]},
        )
        add_message(
            db,
            user["id"],
            "Arma account unlinked",
            "The Arma account link was removed for development testing with server engineer guidance.",
        )
        self.send_json(200, {"ok": True})

    def bridge_payload_data(self, payload: dict[str, Any]) -> dict[str, Any]:
        for key in ("Data", "data", "Payload", "payload"):
            data = payload.get(key)
            if isinstance(data, dict):
                return data
            if isinstance(data, list):
                return {"Requests": data}
        return payload

    def bridge_value(self, source: dict[str, Any], *keys: str, default: Any = "") -> Any:
        for key in keys:
            value = source.get(key)
            if value not in (None, ""):
                return value
        return default

    def normalize_arma_link_code(self, value: Any) -> str:
        code = str(value or "").strip().upper()
        for dash in ("–", "—", "−", "‑"):
            code = code.replace(dash, "-")
        return re.sub(r"\s+", "", code)[:80]

    def api_arma_link_requests(self, db: Database) -> None:
        err = self.bridge_error()
        if err:
            self.error(403, err)
            return
        payload = self.read_json()
        data = self.bridge_payload_data(payload)
        requests = self.bridge_value(data, "Requests", "requests", "LinkRequests", "linkRequests", default=[])
        if not isinstance(requests, list):
            requests = [data] if self.bridge_value(data, "LinkCode", "code", "linkCode", "link_code") else []
        accepted: list[str] = []
        rejected: list[dict[str, str]] = []
        for index, request in enumerate(requests):
            if not isinstance(request, dict):
                rejected.append({"index": str(index), "reason": "Request was not an object"})
                continue
            code = self.normalize_arma_link_code(self.bridge_value(request, "LinkCode", "code", "linkCode", "link_code"))
            identity_id = str(self.bridge_value(request, "IdentityId", "Uid", "identityId", "identity_id", "uid", "PlayerUid", "playerUid")).strip()
            rpl_identity = str(self.bridge_value(request, "RplIdentityValue", "RplIdentity", "rplIdentityValue", "rplIdentity"))[:160]
            request_id = str(self.bridge_value(request, "RequestId", "requestId", "request_id"))[:120]
            player_name = str(self.bridge_value(request, "PlayerName", "playerName", "player_name"))[:120]
            if not code:
                rejected.append({"index": str(index), "request_id": request_id, "player_name": player_name, "reason": "Missing LinkCode"})
                continue
            if not identity_id:
                rejected.append({"index": str(index), "code": code, "request_id": request_id, "player_name": player_name, "reason": "Missing IdentityId/Uid"})
                continue
            request_server_id = str(self.bridge_value(request, "ServerId", "serverId", "server_id")).strip()
            data_server_id = str(self.bridge_value(data, "ServerId", "serverId", "server_id")).strip()
            if request_server_id and request_server_id.lower() != "default":
                server_id = request_server_id
            elif data_server_id:
                server_id = data_server_id
            else:
                server_id = request_server_id or "default"
            existing = one(db, "SELECT * FROM arma_link_codes WHERE server_id = ? AND UPPER(code) = UPPER(?)", (server_id, code))
            if existing and existing["status"] == "claimed":
                accepted.append(code)
                continue
            created_at_dt = parse_bridge_datetime(str(self.bridge_value(request, "CreatedAtUtc", "createdAtUtc", "created_at_utc", "CreatedAt", "createdAt")))
            created_at = created_at_dt.isoformat()
            expires_at = (created_at_dt + dt.timedelta(minutes=max(5, ARMA_LINK_CODE_TTL_MINUTES))).isoformat()
            raw_payload = json.dumps(request, separators=(",", ":"), default=str)[:4000]
            if existing:
                db.execute(
                    """
                    UPDATE arma_link_codes
                    SET request_id = ?, identity_id = ?, uid = ?, rpl_identity = ?, platform = ?, player_name = ?,
                        status = 'pending', created_at = ?, expires_at = ?, raw_payload = ?
                    WHERE id = ?
                    """,
                    (
                        request_id,
                        identity_id,
                        str(self.bridge_value(request, "Uid", "uid", "PlayerUid", "playerUid"))[:160],
                        rpl_identity,
                        str(self.bridge_value(request, "Platform", "platform", "PlatformName", "platformName"))[:60],
                        player_name,
                        created_at,
                        expires_at,
                        raw_payload,
                        existing["id"],
                    ),
                )
            else:
                db.execute(
                    """
                    INSERT INTO arma_link_codes
                    (code, request_id, server_id, identity_id, uid, rpl_identity, platform, player_name, status, created_at, expires_at, raw_payload)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'pending', ?, ?, ?)
                    """,
                    (
                        code,
                        request_id,
                        server_id,
                        identity_id,
                        str(self.bridge_value(request, "Uid", "uid", "PlayerUid", "playerUid"))[:160],
                        rpl_identity,
                        str(self.bridge_value(request, "Platform", "platform", "PlatformName", "platformName"))[:60],
                        player_name,
                        created_at,
                        expires_at,
                        raw_payload,
                    ),
                )
            accepted.append(code)
        self.send_json(200, {"ok": True, "accepted": accepted, "rejected": rejected, "count": len(accepted), "rejected_count": len(rejected)})

    def api_arma_snapshot(self, db: Database) -> None:
        err = self.bridge_error()
        if err:
            self.error(403, err)
            return
        rows = all_rows(
            db,
            """
            SELECT l.*, u.id AS website_user_id, u.name AS website_username, u.civ_number, u.verified, u.roles,
                   u.primary_agency, COALESCE(game_bank.balance, 0) AS game_bank_balance
            FROM arma_account_links l
            JOIN users u ON u.id = l.user_id
            LEFT JOIN arma_game_bank_balances game_bank ON game_bank.identity_id = l.identity_id
            ORDER BY l.linked_at DESC
            """,
        )
        players = []
        ts = now_iso()
        for row in rows:
            user_roles = roles_for(row)
            metadata = [
                {"Key": "civ_number", "Value": row.get("civ_number") or ""},
                {"Key": "primary_agency", "Value": row.get("primary_agency") or ""},
            ]
            players.append(
                {
                    "IdentityId": row["identity_id"],
                    "Uid": row.get("uid") or row["identity_id"],
                    "RplIdentityValue": row.get("rpl_identity") or "",
                    "Platform": row.get("platform") or "",
                    "Name": row.get("player_name") or row["website_username"],
                    "DiscordId": "",
                    "WebsiteUserId": str(row["website_user_id"]),
                    "WebsiteUsername": row["website_username"],
                    "SteamId": "",
                    "XboxId": "",
                    "Linked": 1,
                    "Whitelisted": 1 if bool(row["verified"]) or "owner" in user_roles or "admin" in user_roles else 0,
                    "Banned": 0,
                    "KickReason": "",
                    "Cash": 0,
                    "Bank": int(float(row["game_bank_balance"] or 0)),
                    "RoleIds": user_roles,
                    "PermissionIds": [],
                    "Metadata": metadata,
                }
            )
        db.execute("UPDATE arma_account_links SET last_sync_at = ? WHERE id IN (SELECT id FROM arma_account_links)", (ts,))
        self.send_json(
            200,
            {
                "Data": {
                    "SchemaVersion": 1,
                    "FileName": "TBS RP Linking Server Snapshot",
                    "Description": "Written by the Railway PWA API for TBS RP LINKING SYSTEM.",
                    "ServerId": rows[0]["server_id"] if rows else "default",
                    "SnapshotRevision": int(utcnow().timestamp()),
                    "UpdatedAtUtc": ts,
                    "Players": players,
                }
            },
        )

    def find_arma_link_for_event(self, db: Database, event: dict[str, Any]) -> DbRow | None:
        identity_id = str(self.bridge_value(event, "IdentityId", "identityId", "identity_id")).strip()
        uid = str(self.bridge_value(event, "Uid", "uid", "PlayerUid", "playerUid")).strip()
        rpl_identity = str(self.bridge_value(event, "RplIdentityValue", "rplIdentityValue", "RplIdentity", "rplIdentity")).strip()
        return one(
            db,
            """
            SELECT * FROM arma_account_links
            WHERE (? <> '' AND identity_id = ?)
               OR (? <> '' AND uid = ?)
               OR (? <> '' AND rpl_identity = ?)
            ORDER BY linked_at DESC
            LIMIT 1
            """,
            (identity_id, identity_id, uid, uid, rpl_identity, rpl_identity),
        )

    def api_arma_events(self, db: Database) -> None:
        err = self.bridge_error()
        if err:
            self.error(403, err)
            return
        payload = self.read_json()
        data = self.bridge_payload_data(payload)
        events = self.bridge_value(data, "PendingEvents", "pendingEvents", "pending_events", "Events", "events", default=[])
        if not isinstance(events, list):
            events = [data] if self.bridge_value(data, "EventTypeName", "eventTypeName", "EventType", "eventType", "event_type") else []
        accepted: list[str] = []
        skipped: list[str] = []
        for event in events:
            if not isinstance(event, dict):
                continue
            event_id = str(self.bridge_value(event, "EventId", "eventId", "event_id")).strip()
            if not event_id:
                sequence = self.bridge_value(event, "EventSequence", "eventSequence", "event_sequence", "Sequence", "sequence", default=secrets.token_hex(4))
                event_server = self.bridge_value(event, "ServerId", "serverId", "server_id") or self.bridge_value(data, "ServerId", "serverId", "server_id", default="default")
                event_id = f"{event_server}-{sequence}"
            if one(db, "SELECT id FROM arma_activity_logs WHERE event_id = ?", (event_id,)):
                skipped.append(event_id)
                continue
            link = self.find_arma_link_for_event(db, event)
            user_id = link["user_id"] if link else None
            try:
                amount = round(float(self.bridge_value(event, "Amount", "amount", default=0) or 0), 2)
            except (TypeError, ValueError):
                amount = 0.0
            currency = str(self.bridge_value(event, "Currency", "currency")).strip().lower()
            event_type = str(self.bridge_value(event, "EventTypeName", "eventTypeName", "EventType", "eventType", "event_type", default="player.action")).strip()[:80]
            action = str(self.bridge_value(event, "Action", "action")).strip()[:80]
            reason = str(self.bridge_value(event, "Reason", "reason")).strip()[:240]
            source_system = str(self.bridge_value(event, "SourceSystem", "sourceSystem", "source_system", default="TBS_RP_LINKING_SYSTEM")).strip()[:120]
            created_at = parse_bridge_datetime(str(self.bridge_value(event, "CreatedAtUtc", "createdAtUtc", "created_at_utc", "CreatedAt", "createdAt"))).isoformat()
            received_at = now_iso()
            db.execute(
                """
                INSERT INTO arma_activity_logs
                (event_id, user_id, server_id, event_type, action, source_system, reason, amount, currency, balance_after,
                 identity_id, uid, rpl_identity, platform, player_name, raw_payload, created_at, received_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    event_id,
                    user_id,
                    str(self.bridge_value(event, "ServerId", "serverId", "server_id") or self.bridge_value(data, "ServerId", "serverId", "server_id", default="default"))[:80],
                    event_type,
                    action,
                    source_system,
                    reason,
                    amount,
                    currency,
                    round(float(self.bridge_value(event, "BalanceAfter", "balanceAfter", "balance_after", default=0) or 0), 2),
                    str(self.bridge_value(event, "IdentityId", "identityId", "identity_id"))[:160],
                    str(self.bridge_value(event, "Uid", "uid", "PlayerUid", "playerUid"))[:160],
                    str(self.bridge_value(event, "RplIdentityValue", "rplIdentityValue", "RplIdentity", "rplIdentity"))[:160],
                    str(self.bridge_value(event, "Platform", "platform", "PlatformName", "platformName"))[:60],
                    str(self.bridge_value(event, "PlayerName", "playerName", "player_name"))[:120],
                    json.dumps(event, separators=(",", ":"), default=str)[:4000],
                    created_at,
                    received_at,
                ),
            )
            if user_id and event_type.startswith("money.") and amount:
                add_transaction(db, user_id, f"arma_{action or 'money'}", amount, reason or source_system)
            if link:
                db.execute("UPDATE arma_account_links SET last_seen_at = ?, last_sync_at = ? WHERE id = ?", (created_at, received_at, link["id"]))
            presence_values = {action.strip().lower(), event_type.strip().lower()}
            joined_presence = bool(
                presence_values
                & {
                    "anticheat.player_joined",
                    "player.joined",
                    "player.connected",
                    "player_joined",
                }
            )
            heartbeat_presence = bool(
                presence_values
                & {
                    "anticheat.player_heartbeat",
                    "player.heartbeat",
                    "player.presence",
                    "player_heartbeat",
                }
            )
            departed_presence = bool(
                presence_values
                & {
                    "anticheat.player_left",
                    "anticheat.player_disconnected",
                    "player.left",
                    "player.disconnected",
                    "player_left",
                }
            )
            if joined_presence or heartbeat_presence or departed_presence:
                player_uid = str(event.get("Uid") or event.get("IdentityId") or "").strip()[:160]
                if player_uid:
                    server_id = str(event.get("ServerId") or data.get("ServerId") or "default")[:80]
                    player_name = str(event.get("PlayerName") or "")[:120]
                    if departed_presence:
                        db.execute(
                            """
                            UPDATE anticheat_live_sessions
                            SET player_name = CASE WHEN ? <> '' THEN ? ELSE player_name END,
                                linked_user_id = COALESCE(?, linked_user_id),
                                last_heartbeat_at = ?, status = 'offline'
                            WHERE server_id = ? AND player_uid = ?
                            """,
                            (player_name, player_name, user_id, received_at, server_id, player_uid),
                        )
                    elif joined_presence:
                        db.execute(
                            """
                            INSERT INTO anticheat_live_sessions
                            (server_id, player_uid, player_name, linked_user_id, joined_at,
                             last_heartbeat_at, status)
                            VALUES (?, ?, ?, ?, ?, ?, 'online')
                            ON CONFLICT (server_id, player_uid) DO UPDATE SET
                                player_name = EXCLUDED.player_name,
                                linked_user_id = EXCLUDED.linked_user_id,
                                joined_at = EXCLUDED.joined_at,
                                last_heartbeat_at = EXCLUDED.last_heartbeat_at,
                                status = 'online'
                            """,
                            (server_id, player_uid, player_name, user_id, created_at, received_at),
                        )
                    else:
                        db.execute(
                            """
                            INSERT INTO anticheat_live_sessions
                            (server_id, player_uid, player_name, linked_user_id, joined_at,
                             last_heartbeat_at, status)
                            VALUES (?, ?, ?, ?, ?, ?, 'online')
                            ON CONFLICT (server_id, player_uid) DO UPDATE SET
                                player_name = EXCLUDED.player_name,
                                linked_user_id = EXCLUDED.linked_user_id,
                                last_heartbeat_at = EXCLUDED.last_heartbeat_at,
                                status = 'online'
                            """,
                            (server_id, player_uid, player_name, user_id, created_at, received_at),
                        )
            grey_screen_values = {action.strip().lower(), event_type.strip().lower()}
            grey_screen_event = bool(grey_screen_values & {"anticheat.grey_screened", "grey_screened", "grey_screen", "profile.locked"})
            if grey_screen_event:
                player_uid = str(event.get("Uid") or event.get("IdentityId") or "").strip()[:160]
                player_name = str(event.get("PlayerName") or "Unknown player")[:120]
                if player_uid:
                    lock_result = upsert_anticheat_profile_lock(
                        db,
                        player_uid,
                        player_name,
                        reason or "Thunder Buddies Anti-Cheat grey screen",
                        json.dumps(event, separators=(",", ":"), default=str)[:4000],
                        created_at,
                        event_id,
                        int(user_id) if user_id else None,
                    )
                    db.execute(
                        """
                        INSERT INTO anticheat_players
                        (uid, player_name, reported_system, is_online, last_seen_at, profile_locked, grey_screened,
                         grey_screen_reason, grey_screened_at, grey_screen_evidence, raw_payload, source_file,
                         first_synced_at, last_synced_at)
                        VALUES (?, ?, ?, 1, ?, 1, 1, ?, ?, ?, ?, 'arma_event_outbox', ?, ?)
                        ON CONFLICT (uid) DO UPDATE SET
                            player_name = EXCLUDED.player_name,
                            reported_system = CASE WHEN EXCLUDED.reported_system <> '' THEN EXCLUDED.reported_system ELSE anticheat_players.reported_system END,
                            is_online = 1,
                            last_seen_at = EXCLUDED.last_seen_at,
                            profile_locked = 1,
                            grey_screened = 1,
                            grey_screen_reason = EXCLUDED.grey_screen_reason,
                            grey_screened_at = EXCLUDED.grey_screened_at,
                            grey_screen_evidence = EXCLUDED.grey_screen_evidence,
                            raw_payload = EXCLUDED.raw_payload,
                            source_file = EXCLUDED.source_file,
                            last_synced_at = EXCLUDED.last_synced_at
                        """,
                        (
                            player_uid, player_name, str(event.get("Platform") or "")[:80], created_at,
                            reason or "Thunder Buddies Anti-Cheat grey screen", created_at,
                            json.dumps(event, separators=(",", ":"), default=str)[:4000],
                            json.dumps(event, separators=(",", ":"), default=str)[:20000], received_at, received_at,
                        ),
                    )
                    print(f"Faircroft anti-cheat lock recorded for {player_name} ({player_uid}); linked_user_id={lock_result.get('linked_user_id')}")
            accepted.append(event_id)
        self.send_json(200, {"ok": True, "accepted_event_ids": accepted, "skipped_event_ids": skipped})

    def api_arma_game_banks(self, db: Database) -> None:
        err = self.bridge_error()
        if err:
            self.error(403, err)
            return
        payload = self.read_json()
        data = self.bridge_payload_data(payload)
        balances = data.get("Balances") or data.get("m_Banks") or {}
        if not isinstance(balances, dict):
            self.error(400, "Bank payload must contain a Balances map")
            return
        source_file = str(data.get("SourceFile") or "")[:255]
        source_saved_at = str(data.get("SourceSavedAt") or data.get("m_iLastSaved") or "")[:80]
        synced_at = now_iso()
        accepted = 0
        linked = 0
        for identity_id, raw_balance in balances.items():
            identity = str(identity_id or "").strip()[:160]
            if not identity:
                continue
            try:
                balance = round(float(raw_balance or 0), 2)
            except (TypeError, ValueError):
                continue
            db.execute(
                """
                INSERT INTO arma_game_bank_balances
                (identity_id, balance, source_file, source_saved_at, raw_payload, synced_at)
                VALUES (?, ?, ?, ?, ?, ?)
                ON CONFLICT (identity_id) DO UPDATE SET
                    balance = EXCLUDED.balance,
                    source_file = EXCLUDED.source_file,
                    source_saved_at = EXCLUDED.source_saved_at,
                    raw_payload = EXCLUDED.raw_payload,
                    synced_at = EXCLUDED.synced_at
                """,
                (identity, balance, source_file, source_saved_at, json.dumps({"balance": balance}), synced_at),
            )
            if one(db, "SELECT id FROM arma_account_links WHERE identity_id = ?", (identity,)):
                linked += 1
            accepted += 1
        self.send_json(200, {"ok": True, "accepted": accepted, "matched_linked_accounts": linked, "synced_at": synced_at})

    def api_jobs(self, db: Database, user: DbRow | None) -> None:
        if not user:
            self.error(401, "Authentication required")
            return
        active_character = ensure_default_character(db, int(user["id"]), str(user["name"] or "Civilian"))
        applications = all_rows(
            db,
            """
            SELECT a.*, reviewer.name AS reviewer_name
            FROM department_applications a
            LEFT JOIN users reviewer ON reviewer.id = a.reviewed_by
            WHERE a.user_id = ? AND a.character_id = ?
            ORDER BY a.updated_at DESC
            """,
            (user["id"], active_character["id"]),
        )
        self.send_json(
            200,
            {
                "jobs": [],
                "active_jobs": [],
                "income": income_snapshot(db, user),
                "department_postings": [
                    {**dict(posting), "accepting_applications": get_system_settings(db)["application_intake"].get(str(posting["key"]), True)}
                    for posting in DEPARTMENT_POSTINGS
                ],
                "applications_accepting": get_system_settings(db)["applications_accepting"],
                "exam_questions": {
                    key: [[question, list(options)] for question, options, _answer in questions]
                    for key, questions in BAR_EXAM_BANKS.items()
                },
                "department_applications": [dict(row) for row in applications],
                "characters": [dict(row) for row in all_rows(db, "SELECT id, character_name, is_active FROM user_characters WHERE user_id = ? AND status = 'active' ORDER BY is_active DESC, created_at", (user["id"],))],
                "active_character": dict(active_character),
            },
        )

    def api_apply_department(self, db: Database, user: DbRow | None) -> None:
        if not user:
            self.error(401, "Authentication required")
            return
        payload = self.read_json()
        try:
            character = require_owned_character(db, int(user["id"]), payload.get("character_id"))
        except ValueError as exc:
            self.error(400, str(exc))
            return
        department_key = str(payload.get("department_key") or "").strip().lower()
        posting = next((item for item in DEPARTMENT_POSTINGS if item["key"] == department_key), None)
        if not posting:
            self.error(400, "Unknown department posting")
            return
        settings = get_system_settings(db)
        if not settings["application_intake"].get(department_key, settings["applications_accepting"]):
            self.error(403, f"{posting['label']} applications are not being accepted at this time. Please try again later. Sincerely, Faircroft Government.")
            return
        existing = one(
            db,
            """
            SELECT id, status
            FROM department_applications
            WHERE user_id = ? AND character_id = ? AND department_key = ? AND status NOT IN ('denied','withdrawn','closed')
            ORDER BY created_at DESC
            LIMIT 1
            """,
            (user["id"], character["id"], department_key),
        )
        if existing:
            self.error(409, f"You already have an active {posting['label']} application")
            return
        message_body = ""
        if posting.get("form_type") == "law_enforcement":
            try:
                statement, message_body = clean_law_enforcement_application(payload, posting, user)
            except ValueError as exc:
                self.error(400, str(exc))
                return
        elif posting.get("form_type") in ("bar_exam", "press_exam", "ice_exam"):
            try:
                statement, message_body = clean_bar_exam_application(payload, posting, user)
            except ValueError as exc:
                self.error(400, str(exc))
                return
        else:
            statement = str(payload.get("statement") or "").strip()
            if len(statement) < 20:
                self.error(400, "Application statement must be at least 20 characters")
                return
            statement = statement[:4000]
            message_body = statement
        ts = now_iso()
        created = db.execute(
            """
            INSERT INTO department_applications
            (application_number, user_id, character_id, department_key, department_name, desired_role, status, statement, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, 'submitted', ?, ?, ?)
            RETURNING id, application_number
            """,
            (
                generate_record_number(db, "department_applications", "application_number", "DEPT"),
                user["id"],
                character["id"],
                posting["key"],
                posting["division"],
                posting["role_key"],
                statement,
                ts,
                ts,
            ),
        ).fetchone()
        press_pass_awarded = False
        press_pass_capacity_reached = False
        ice_qualified = False
        if posting.get("form_type") == "press_exam":
            exam_record = json.loads(statement)
            if int(exam_record.get("score") or 0) >= 8:
                settings = get_system_settings(db)
                pass_limit = int(settings["fnn_press_pass_limit"])
                press_holders = sum(1 for account in all_rows(db, "SELECT roles FROM users") if has_any(account, "press"))
                if press_holders < pass_limit:
                    applicant = one(db, "SELECT * FROM users WHERE id = ?", (user["id"],))
                    updated_roles = sorted(set([*roles_for(applicant), "press"])) if applicant else ["press"]
                    db.execute(
                        """UPDATE users SET verified = 1, roles = ?, press_pass_status = 'active',
                           press_pass_reason = '', press_pass_action_at = ?, press_pass_notice_pending = 0
                           WHERE id = ?""",
                        (json.dumps(updated_roles), ts, user["id"]),
                    )
                    db.execute(
                        "UPDATE department_applications SET status = 'approved', reviewer_notes = ?, updated_at = ? WHERE id = ?",
                        ("Automatically certified by the FNN examination system.", ts, created["id"]),
                    )
                    press_pass_awarded = True
                else:
                    press_pass_capacity_reached = True
        if posting.get("form_type") == "ice_exam":
            exam_record = json.loads(statement)
            ice_qualified = int(exam_record.get("score") or 0) == 20 and int(exam_record.get("total") or 0) == 20
            if ice_qualified:
                db.execute(
                    "UPDATE department_applications SET reviewer_notes = ?, updated_at = ? WHERE id = ?",
                    ("Qualification passed 20/20. Awaiting ICE Command interview and training review.", ts, created["id"]),
                )
            else:
                db.execute(
                    "UPDATE department_applications SET status = 'denied', reviewer_notes = ?, updated_at = ? WHERE id = ?",
                    ("Qualification threshold not met. Application was not forwarded to ICE Command.", ts, created["id"]),
                )
        if not press_pass_awarded and posting.get("form_type") != "ice_exam":
            add_message(db, user["id"], "Department application submitted", f"Your {posting['label']} application {created['application_number']} was submitted for review.")
        if press_pass_awarded:
            add_message(db, user["id"], "FNN Press Pass issued", "You passed the FNN examination. Your Press Pass was issued automatically and Press Desk access is now active.")
        elif press_pass_capacity_reached:
            add_message(db, user["id"], "FNN Press Pass waitlisted", "You passed the FNN examination, but the current Press Pass limit has been reached. Your result remains on file for newsroom review.")
        elif posting.get("form_type") == "ice_exam" and ice_qualified:
            add_message(db, user["id"], "ICE qualification passed", "You earned a perfect 20/20 result. Your application has entered the ICE Command interview and training review queue.")
        elif posting.get("form_type") == "ice_exam":
            add_message(db, user["id"], "ICE qualification not advanced", "Your ICE Agent application did not meet the perfect qualification threshold and was not forwarded to command.")
        recipient_roles = ("ice_commander",) if posting.get("form_type") == "ice_exam" else posting_command_roles(posting)
        recipient_patterns = tuple(f"%{role}%" for role in recipient_roles)
        staff = all_rows(
            db,
            "SELECT id FROM users WHERE " + " OR ".join(["roles LIKE ?"] * len(recipient_patterns)) + " ORDER BY id LIMIT 120",
            recipient_patterns,
        )
        for row in staff:
            if posting.get("form_type") == "ice_exam" and not ice_qualified:
                continue
            if row["id"] != user["id"]:
                add_message(
                    db,
                    row["id"],
                    "Department application pending",
                    f"{user['name']} applied for {posting['label']} ({created['application_number']}).\n\n{message_body}",
                    user["id"],
                )
        self.send_json(201, {"ok": True, "id": int(created["id"]), "application_number": created["application_number"], "press_pass_awarded": press_pass_awarded, "press_pass_capacity_reached": press_pass_capacity_reached})

    def api_apply_job(self, db: Database, user: DbRow | None, job_id: int) -> None:
        self.error(410, "Passive income jobs have been removed from this server.")
        return

    def _consume_bearer_receipt(self, db: Database, user_id: int, raw_code: str) -> DbRow | None:
        raw_code = str(raw_code or "").strip()
        if not re.fullmatch(r"\d{4}", raw_code):
            return None
        code_hash = hashlib.sha256(raw_code.encode("utf-8")).hexdigest()
        row = one(db, """SELECT * FROM market_cash_codes WHERE code_hash=?
            AND (target_user_id IS NULL OR target_user_id=?) AND transaction_type IN ('deposit','universal')
            AND used_at IS NULL AND revoked_at IS NULL AND expires_at > ?""", (code_hash, user_id, now_iso()))
        if not row:
            legacy = one(db, """SELECT * FROM myfaircroft_payment_codes WHERE code_hash=?
                AND (target_user_id IS NULL OR target_user_id=?) AND used_at IS NULL
                AND revoked_at IS NULL AND expires_at > ?""", (code_hash, user_id, now_iso()))
            if legacy:
                db.execute("""INSERT INTO market_cash_codes
                    (code_hash, code_hint, target_user_id, transaction_type, amount, created_by, expires_at, created_at)
                    VALUES (?, ?, ?, 'universal', 0, ?, ?, ?) ON CONFLICT(code_hash) DO NOTHING""",
                    (code_hash, legacy["code_hint"], legacy.get("target_user_id"), legacy["created_by"], legacy["expires_at"], legacy["created_at"]))
                row = one(db, "SELECT * FROM market_cash_codes WHERE code_hash=? AND used_at IS NULL AND revoked_at IS NULL", (code_hash,))
        if not row:
            return None
        ts = now_iso()
        db.execute("UPDATE market_cash_codes SET target_user_id=COALESCE(target_user_id,?), used_by=?, used_at=? WHERE id=? AND used_at IS NULL", (user_id, user_id, ts, row["id"]))
        db.execute("UPDATE myfaircroft_payment_codes SET target_user_id=COALESCE(target_user_id,?), used_by=?, used_at=? WHERE code_hash=? AND used_at IS NULL", (user_id, user_id, ts, code_hash))
        return row

    def api_insurance(self, db: Database, user: DbRow | None) -> None:
        err = verified_required(user)
        if err:
            self.error(403 if user else 401, err); return
        policies = all_rows(db, """SELECT p.*, c.character_name FROM insurance_policies p
            JOIN user_characters c ON c.id=p.character_id WHERE p.user_id=? ORDER BY p.created_at DESC""", (user["id"],))
        claims = all_rows(db, """SELECT c.*,p.policy_number,p.coverage_tier,uc.character_name
            FROM insurance_claims c JOIN insurance_policies p ON p.id=c.policy_id
            JOIN user_characters uc ON uc.id=c.character_id WHERE c.user_id=? ORDER BY c.created_at DESC""", (user["id"],))
        bank = one(db, """SELECT b.balance,b.synced_at FROM arma_account_links l
            JOIN arma_game_bank_balances b ON b.identity_id=l.identity_id
            WHERE l.user_id=? ORDER BY l.linked_at DESC LIMIT 1""", (user["id"],))
        self.send_json(200, {"policies": [dict(row) for row in policies], "claims": [dict(row) for row in claims],
            "bank": dict(bank) if bank else {"balance": 0, "synced_at": None},
            "tiers": [
                {"id":"essential","name":"Continuity Essential","premium":3500,"coverage_percent":50},
                {"id":"preferred","name":"Continuity Preferred","premium":4250,"coverage_percent":70},
                {"id":"premier","name":"Continuity Premier","premium":5000,"coverage_percent":90}],
            "characters": [dict(row) for row in all_rows(db,
            "SELECT id,character_name,is_active FROM user_characters WHERE user_id=? AND status='active' ORDER BY is_active DESC,created_at", (user["id"],))]})

    def api_insurance_create(self, db: Database, user: DbRow | None) -> None:
        err = verified_required(user)
        if err:
            self.error(403 if user else 401, err); return
        payload = self.read_json()
        try: character_id = int(payload.get("character_id") or 0)
        except (TypeError, ValueError): character_id = 0
        character = one(db, "SELECT * FROM user_characters WHERE id=? AND user_id=? AND status='active'", (character_id, user["id"]))
        policy_type = str(payload.get("policy_type") or "").strip().lower()
        tier = str(payload.get("coverage_tier") or "standard").strip().lower()
        subject = str(payload.get("subject_label") or "").strip()[:120]
        valid_types = {"compensation", "vehicle", "property", "life", "business", "general"}
        tiers = {"essential": (50, 3500), "preferred": (70, 4250), "standard": (70, 4250), "premier": (90, 5000)}
        if not character or policy_type not in valid_types or tier not in tiers or not subject:
            self.error(400, "Select a character, policy, coverage tier, and insured subject."); return
        if policy_type == "compensation" and one(db, """SELECT id FROM insurance_policies
            WHERE user_id=? AND policy_type='compensation' AND status='active' AND expires_at>? LIMIT 1""",
            (user["id"], now_iso())):
            self.error(409, "An active continuity policy already protects this linked bank account."); return
        receipt = self._consume_bearer_receipt(db, int(user["id"]), str(payload.get("code") or ""))
        if not receipt:
            self.error(403, "A valid unused four-digit Faircroft receipt PIN is required after staff receives payment in game."); return
        coverage_percent, premium = tiers[tier]
        bank = one(db, """SELECT b.balance FROM arma_account_links l JOIN arma_game_bank_balances b
            ON b.identity_id=l.identity_id WHERE l.user_id=? ORDER BY l.linked_at DESC LIMIT 1""", (user["id"],))
        protected_balance = max(0.0, float(bank["balance"] or 0)) if bank else 0.0
        coverage = round(protected_balance * coverage_percent / 100.0, 2)
        deductible = 0
        issued = utcnow(); expires = issued + dt.timedelta(days=30)
        policy_number = f"FCI-{issued.strftime('%y%m')}-{secrets.randbelow(900000)+100000}"
        questionnaire = {key: str(payload.get(key) or "").strip()[:500] for key in ("risk_use", "location", "beneficiary", "notes")}
        db.execute("""INSERT INTO insurance_policies
            (user_id,character_id,policy_number,policy_type,coverage_tier,subject_label,coverage_amount,coverage_percent,protected_bank_balance,premium_amount,deductible_amount,questionnaire,status,receipt_code_id,issued_at,expires_at,created_at,updated_at)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,'active',?,?,?,?,?)""",
            (user["id"], character_id, policy_number, policy_type, tier, subject, coverage, coverage_percent, protected_balance, premium, deductible,
             json.dumps(questionnaire, separators=(",", ":")), receipt["id"], issued.isoformat(), expires.isoformat(), issued.isoformat(), issued.isoformat()))
        add_admin_audit(db, int(user["id"]), "insurance.policy.issued", int(user["id"]), {"policy_number": policy_number, "character_id": character_id, "premium": premium})
        self.send_json(201, {"ok": True, "policy_number": policy_number})

    def api_insurance_claim_create(self, db: Database, user: DbRow | None) -> None:
        err = verified_required(user)
        if err:
            self.error(403 if user else 401, err); return
        payload = self.read_json()
        try: policy_id = int(payload.get("policy_id") or 0)
        except (TypeError, ValueError): policy_id = 0
        policy = one(db, "SELECT * FROM insurance_policies WHERE id=? AND user_id=?", (policy_id, user["id"]))
        summary = str(payload.get("incident_summary") or "").strip()[:1500]
        expiry = parse_iso(policy["expires_at"]) if policy else None
        if not policy or policy["policy_type"] != "compensation" or policy["status"] != "active" or not expiry or expiry <= utcnow():
            self.error(409, "Select an active continuity policy."); return
        if len(summary) < 20 or not bool(payload.get("confirmed_reset")):
            self.error(400, "Confirm the reset or wipe and provide at least 20 characters of claim details."); return
        if one(db, "SELECT id FROM insurance_claims WHERE policy_id=? AND status IN ('pending','approved')", (policy_id,)):
            self.error(409, "This policy already has a claim under review."); return
        bank = one(db, """SELECT b.balance FROM arma_account_links l JOIN arma_game_bank_balances b
            ON b.identity_id=l.identity_id WHERE l.user_id=? ORDER BY l.linked_at DESC LIMIT 1""", (user["id"],))
        current_balance = max(0.0, float(bank["balance"] or 0)) if bank else 0.0
        protected_balance = max(current_balance, float(policy.get("protected_bank_balance") or 0))
        coverage_percent = float(policy.get("coverage_percent") or {"essential":50,"standard":70,"preferred":70,"premier":90}.get(policy["coverage_tier"], 0))
        requested = round(protected_balance * coverage_percent / 100.0, 2)
        ts = now_iso(); claim_number = f"FCIC-{utcnow().strftime('%y%m')}-{secrets.randbelow(900000)+100000}"
        db.execute("""INSERT INTO insurance_claims
            (claim_number,policy_id,user_id,character_id,incident_type,incident_summary,bank_balance_snapshot,coverage_percent,requested_amount,status,created_at,updated_at)
            VALUES (?,?,?,?, 'server_reset', ?,?,?,?,'pending',?,?)""",
            (claim_number, policy_id, user["id"], policy["character_id"], summary, protected_balance, coverage_percent, requested, ts, ts))
        add_admin_audit(db, int(user["id"]), "insurance.claim.filed", int(user["id"]), {"claim_number":claim_number,"requested_amount":requested})
        self.send_json(201, {"ok":True,"claim_number":claim_number,"requested_amount":requested,"status":"pending"})

    def _gang_payload(self, db: Database, user: DbRow) -> dict[str, Any]:
        characters = all_rows(db, "SELECT id,character_name,is_active FROM user_characters WHERE user_id=? AND status='active' ORDER BY is_active DESC,created_at", (user["id"],))
        memberships = all_rows(db, """SELECT gm.*,g.name AS gang_name,g.description,g.accent_color,g.locked,g.member_limit,
            c.character_name FROM gang_members gm JOIN gangs g ON g.id=gm.gang_id JOIN user_characters c ON c.id=gm.character_id
            WHERE gm.user_id=? AND gm.status IN ('active','locked') ORDER BY gm.joined_at""", (user["id"],))
        gangs: list[dict[str, Any]] = []
        for membership in memberships:
            item = dict(membership)
            item["members"] = [dict(row) for row in all_rows(db, """SELECT gm.id,gm.character_id,gm.gang_role,gm.status,gm.joined_at,c.character_name
                FROM gang_members gm JOIN user_characters c ON c.id=gm.character_id WHERE gm.gang_id=? ORDER BY CASE gm.gang_role WHEN 'leader' THEN 0 WHEN 'officer' THEN 1 ELSE 2 END,c.character_name""", (membership["gang_id"],))]
            item["invite_codes"] = [dict(row) for row in all_rows(db, """SELECT id,code_hint,uses_remaining,expires_at,redeemed_at,revoked_at,created_at
                FROM gang_invite_codes WHERE gang_id=? AND issued_by_user_id=? ORDER BY created_at DESC LIMIT 20""", (membership["gang_id"], user["id"]))] if membership["gang_role"] == "leader" else []
            gangs.append(item)
        return {"characters": [dict(x) for x in characters], "memberships": gangs, "settings": {"creation_enabled": get_system_settings(db)["gang_creation_enabled"]}}

    def api_gangs(self, db: Database, user: DbRow | None) -> None:
        err = verified_required(user)
        if err: self.error(403 if user else 401, err); return
        self.send_json(200, self._gang_payload(db, user))

    def api_gang_create(self, db: Database, user: DbRow | None) -> None:
        err = verified_required(user)
        if err: self.error(403 if user else 401, err); return
        settings = get_system_settings(db); payload = self.read_json()
        try: character_id = int(payload.get("character_id") or 0)
        except (TypeError, ValueError): character_id = 0
        character = one(db, "SELECT * FROM user_characters WHERE id=? AND user_id=? AND status='active'", (character_id, user["id"]))
        name = re.sub(r"\s+", " ", str(payload.get("name") or "").strip())[:60]
        description = str(payload.get("description") or "").strip()[:500]
        color = str(payload.get("accent_color") or "#41e6b0").strip()[:16]
        created_count = one(db, "SELECT COUNT(*) AS count FROM gangs WHERE leader_user_id=? AND status='active'", (user["id"],))
        total = one(db, "SELECT COUNT(*) AS count FROM gangs WHERE status='active'")
        if not settings["gang_creation_enabled"]: self.error(409, "Gang creation is currently closed."); return
        if not character or len(name) < 3: self.error(400, "Select the exact character and enter a gang name."); return
        if one(db, "SELECT id FROM gang_members WHERE character_id=? AND status IN ('active','locked')", (character_id,)): self.error(409, "This character already belongs to a gang."); return
        if int(created_count["count"] or 0) >= settings["gang_max_creations_per_user"] or int(total["count"] or 0) >= settings["gang_global_limit"]: self.error(409, "The configured gang creation limit has been reached."); return
        try:
            gang = db.execute("""INSERT INTO gangs (name,description,accent_color,leader_user_id,leader_character_id,status,member_limit,locked,created_at,updated_at)
                VALUES (?,?,?,?,?,'active',?,0,?,?) RETURNING id""", (name, description, color, user["id"], character_id, settings["gang_default_member_limit"], now_iso(), now_iso())).fetchone()
        except Exception:
            self.error(409, "That gang name is already registered."); return
        db.execute("INSERT INTO gang_members (gang_id,user_id,character_id,gang_role,status,joined_at,updated_at) VALUES (?,?,?,'leader','active',?,?)", (gang["id"], user["id"], character_id, now_iso(), now_iso()))
        updated_roles = sorted(set([*roles_for(user), "gang_leader"]))
        db.execute("UPDATE users SET roles=? WHERE id=?", (json.dumps(updated_roles), user["id"]))
        add_admin_audit(db, int(user["id"]), "gang.created", int(user["id"]), {"gang_id": gang["id"], "name": name, "character_id": character_id})
        self.send_json(201, {"ok": True, "gang_id": gang["id"]})

    def api_gang_invite(self, db: Database, user: DbRow | None) -> None:
        err = verified_required(user)
        if err: self.error(403 if user else 401, err); return
        payload = self.read_json()
        try: gang_id = int(payload.get("gang_id") or 0); character_id = int(payload.get("character_id") or 0); uses = max(1, min(25, int(payload.get("uses") or 1)))
        except (TypeError, ValueError): gang_id=character_id=0; uses=1
        leader = one(db, """SELECT gm.* FROM gang_members gm JOIN gangs g ON g.id=gm.gang_id
            WHERE gm.gang_id=? AND gm.user_id=? AND gm.character_id=? AND gm.gang_role='leader' AND gm.status='active' AND g.locked=0""", (gang_id, user["id"], character_id))
        if not leader: self.error(403, "Only the active character registered as gang leader can issue a join PIN."); return
        raw = ""; code_hash = ""
        for _attempt in range(40):
            raw = f"{secrets.randbelow(10000):04d}"
            code_hash = hashlib.sha256(raw.encode()).hexdigest()
            if not one(db, "SELECT id FROM gang_invite_codes WHERE code_hash=? AND revoked_at IS NULL AND uses_remaining>0 AND expires_at>?", (code_hash, now_iso())):
                break
        else:
            self.error(503, "A unique gang PIN could not be issued. Try again in a moment."); return
        expires = (utcnow()+dt.timedelta(minutes=30)).isoformat()
        db.execute("""INSERT INTO gang_invite_codes (gang_id,code_hash,code_hint,issued_by_user_id,issued_by_character_id,uses_remaining,expires_at,created_at)
            VALUES (?,?,?,?,?,?,?,?)""", (gang_id, code_hash, raw, user["id"], character_id, uses, expires, now_iso()))
        self.send_json(201, {"ok": True, "code": raw, "expires_at": expires, "uses": uses})

    def api_gang_join(self, db: Database, user: DbRow | None) -> None:
        err = verified_required(user)
        if err: self.error(403 if user else 401, err); return
        payload = self.read_json()
        try: character_id = int(payload.get("character_id") or 0)
        except (TypeError, ValueError): character_id = 0
        character = one(db, "SELECT * FROM user_characters WHERE id=? AND user_id=? AND status='active'", (character_id, user["id"]))
        raw = str(payload.get("code") or "").strip(); code_hash = hashlib.sha256(raw.encode()).hexdigest()
        invite = one(db, """SELECT i.*,g.member_limit,g.locked,g.status FROM gang_invite_codes i JOIN gangs g ON g.id=i.gang_id
            WHERE i.code_hash=? AND i.revoked_at IS NULL AND i.uses_remaining>0 AND i.expires_at>? AND g.status='active'""", (code_hash, now_iso()))
        if not character or not re.fullmatch(r"\d{4}", raw) or not invite: self.error(400, "Select the joining character and enter a valid active four-digit gang PIN."); return
        if invite["locked"]: self.error(409, "This gang is locked by Faircroft staff."); return
        if one(db, "SELECT id FROM gang_members WHERE character_id=? AND status IN ('active','locked')", (character_id,)): self.error(409, "This character already belongs to a gang."); return
        count = one(db, "SELECT COUNT(*) AS count FROM gang_members WHERE gang_id=? AND status IN ('active','locked')", (invite["gang_id"],))
        if int(count["count"] or 0) >= int(invite["member_limit"]): self.error(409, "This gang has reached its member limit."); return
        ts=now_iso(); db.execute("INSERT INTO gang_members (gang_id,user_id,character_id,gang_role,status,joined_at,updated_at) VALUES (?,?,?,'member','active',?,?)", (invite["gang_id"], user["id"], character_id, ts, ts))
        db.execute("UPDATE gang_invite_codes SET uses_remaining=uses_remaining-1,redeemed_by_user_id=?,redeemed_character_id=?,redeemed_at=? WHERE id=?", (user["id"], character_id, ts, invite["id"]))
        self.send_json(201, {"ok": True})

    def api_gang_member_update(self, db: Database, user: DbRow | None, member_id: int) -> None:
        err = verified_required(user)
        if err: self.error(403 if user else 401, err); return
        member = one(db, "SELECT * FROM gang_members WHERE id=?", (member_id,)); payload=self.read_json()
        if not member: self.error(404, "Gang member not found."); return
        leader = one(db, "SELECT id FROM gang_members WHERE gang_id=? AND user_id=? AND gang_role='leader' AND status='active'", (member["gang_id"], user["id"]))
        if not leader: self.error(403, "Gang leader access required."); return
        if member["gang_role"] == "leader": self.error(409, "The registered leader cannot be altered from the member roster."); return
        action=str(payload.get("action") or "").lower(); role=str(payload.get("gang_role") or "member").lower()
        if action == "remove": db.execute("UPDATE gang_members SET status='removed',updated_at=? WHERE id=?", (now_iso(), member_id))
        elif action in ("lock","unlock"): db.execute("UPDATE gang_members SET status=?,updated_at=? WHERE id=?", ("locked" if action=="lock" else "active",now_iso(),member_id))
        elif role in ("member","officer","enforcer","treasurer"): db.execute("UPDATE gang_members SET gang_role=?,updated_at=? WHERE id=?", (role,now_iso(),member_id))
        else: self.error(400, "Choose a supported member action or gang role."); return
        self.send_json(200, {"ok": True})

    def market_apply_programs(self, db: Database) -> None:
        current = utcnow()
        programs = all_rows(db, "SELECT * FROM market_price_programs WHERE status = 'active' ORDER BY id")
        for program in programs:
            try:
                starts = parse_iso(program["starts_at"])
                ends = parse_iso(program["ends_at"])
            except (TypeError, ValueError):
                db.execute("UPDATE market_price_programs SET status = 'cancelled' WHERE id = ?", (program["id"],))
                continue
            if current < starts:
                continue
            progress = 1.0 if current >= ends else max(0.0, min(1.0, (current - starts).total_seconds() / max(1, (ends - starts).total_seconds())))
            targets = all_rows(db, "SELECT id, price FROM market_securities WHERE active = 1" + (" AND id = ?" if program.get("security_id") else ""), ((program["security_id"],) if program.get("security_id") else ()))
            for security in targets:
                start_price = float(program.get("start_price") or security["price"])
                new_price = max(0.01, start_price * (1 + float(program["percent_change"]) * progress / 100.0))
                db.execute("UPDATE market_securities SET previous_price = price, price = ?, updated_at = ? WHERE id = ?", (round(new_price, 4), now_iso(), security["id"]))
            if progress >= 1:
                db.execute("UPDATE market_price_programs SET status = 'completed' WHERE id = ?", (program["id"],))

    def market_payload(self, db: Database, user: DbRow) -> dict[str, Any]:
        self.market_apply_programs(db)
        settings = get_system_settings(db)
        account = one(db, "SELECT * FROM market_accounts WHERE user_id = ?", (user["id"],))
        securities = all_rows(db, "SELECT * FROM market_securities WHERE active = 1 ORDER BY security_type, ticker")
        holdings: list[DbRow] = []
        orders: list[DbRow] = []
        cash_log: list[DbRow] = []
        transfers: list[DbRow] = []
        promo_redemptions: list[DbRow] = []
        if account:
            holdings = all_rows(db, """SELECT h.*, s.ticker, s.name, s.price, s.previous_price, s.security_type
                FROM market_holdings h JOIN market_securities s ON s.id = h.security_id
                WHERE h.account_id = ? AND h.quantity > 0 ORDER BY (h.quantity * s.price) DESC""", (account["id"],))
            orders = all_rows(db, """SELECT o.*, s.ticker, s.name FROM market_orders o JOIN market_securities s ON s.id = o.security_id
                WHERE o.account_id = ? ORDER BY o.created_at DESC LIMIT 50""", (account["id"],))
            cash_log = all_rows(db, """SELECT t.*, issuer.name AS processed_by_name FROM market_cash_transactions t
                LEFT JOIN users issuer ON issuer.id = t.processed_by WHERE t.account_id = ? ORDER BY t.created_at DESC LIMIT 30""", (account["id"],))
            transfers = all_rows(db, """SELECT t.*, s.ticker, fu.name AS from_name, tu.name AS to_name
                FROM market_transfers t JOIN market_securities s ON s.id=t.security_id
                JOIN market_accounts fa ON fa.id=t.from_account_id JOIN users fu ON fu.id=fa.user_id
                JOIN market_accounts ta ON ta.id=t.to_account_id JOIN users tu ON tu.id=ta.user_id
                WHERE t.from_account_id=? OR t.to_account_id=? ORDER BY t.created_at DESC LIMIT 30""", (account["id"], account["id"]))
            promo_redemptions = all_rows(db, """SELECT r.reward_summary,r.redeemed_at,p.campaign_name
                FROM market_promo_redemptions r JOIN market_promo_codes p ON p.id=r.promo_id
                WHERE r.account_id=? ORDER BY r.redeemed_at DESC LIMIT 20""", (account["id"],))
        portfolio_value = sum(float(row["quantity"]) * float(row["price"]) for row in holdings)
        return {"account": dict(account) if account else None, "securities": [dict(x) for x in securities], "holdings": [dict(x) for x in holdings],
                "orders": [dict(x) for x in orders], "cash_transactions": [dict(x) for x in cash_log], "transfers": [dict(x) for x in transfers],
                "promo_redemptions": [dict(x) for x in promo_redemptions],
                "portfolio_value": round(portfolio_value, 2), "market_open": settings["market_open"],
                "transfer_fee_percent": settings["market_transfer_fee_percent"], "trade_fee_percent": settings["market_trade_fee_percent"]}

