    def api_wallstreet_cash(self, db: Database, user: DbRow | None) -> None:
        err = verified_required(user)
        if err:
            self.error(403 if user else 401, err); return
        account = one(db, "SELECT * FROM market_accounts WHERE user_id = ?", (user["id"],))
        if not account:
            self.error(409, "Create your Ravenhood account first."); return
        payload = self.read_json(); tx_type = str(payload.get("transaction_type") or "").lower()
        try: amount = round(float(payload.get("amount") or 0), 2)
        except (TypeError, ValueError): amount = 0
        raw_code = str(payload.get("code") or "").strip()
        if tx_type not in ("deposit", "withdrawal") or amount <= 0 or len(raw_code) != 4:
            self.error(400, "Transaction type, positive amount, and four-digit receipt code are required."); return
        code_hash = hashlib.sha256(raw_code.encode("utf-8")).hexdigest()
        code = one(db, """SELECT * FROM market_cash_codes WHERE code_hash=? AND (target_user_id IS NULL OR target_user_id=?)
            AND transaction_type IN (?, 'universal') AND used_at IS NULL AND revoked_at IS NULL AND expires_at > ?""",
            (code_hash, user["id"], tx_type, now_iso()))
        if not code:
            legacy = one(db, """SELECT * FROM myfaircroft_payment_codes WHERE code_hash=? AND (target_user_id IS NULL OR target_user_id=?)
                AND used_at IS NULL AND revoked_at IS NULL AND expires_at > ?""", (code_hash, user["id"], now_iso()))
            if legacy:
                db.execute("""INSERT INTO market_cash_codes
                    (code_hash, code_hint, target_user_id, transaction_type, amount, created_by, expires_at, created_at)
                    VALUES (?, ?, ?, 'universal', 0, ?, ?, ?) ON CONFLICT(code_hash) DO NOTHING""",
                    (code_hash, legacy["code_hint"], legacy.get("target_user_id"), legacy["created_by"], legacy["expires_at"], legacy["created_at"]))
                code = one(db, "SELECT * FROM market_cash_codes WHERE code_hash=? AND used_at IS NULL AND revoked_at IS NULL", (code_hash,))
        if not code:
            self.error(400, "Receipt code is invalid, expired, or already used."); return
        balance = float(account["cash_balance"] or 0)
        if tx_type == "withdrawal" and balance < amount:
            self.error(409, "Insufficient settled cash. Sell holdings before requesting this withdrawal."); return
        new_balance = balance + amount if tx_type == "deposit" else balance - amount
        ts = now_iso()
        db.execute("UPDATE market_accounts SET cash_balance=?, updated_at=? WHERE id=?", (round(new_balance, 2), ts, account["id"]))
        db.execute("UPDATE market_cash_codes SET target_user_id=COALESCE(target_user_id,?), used_by=?, used_at=? WHERE id=? AND used_at IS NULL", (user["id"], user["id"], ts, code["id"]))
        db.execute("UPDATE myfaircroft_payment_codes SET target_user_id=COALESCE(target_user_id,?), used_by=?, used_at=? WHERE code_hash=? AND used_at IS NULL", (user["id"], user["id"], ts, code_hash))
        db.execute("INSERT INTO market_cash_transactions (account_id, code_id, transaction_type, amount, processed_by, created_at) VALUES (?, ?, ?, ?, ?, ?)", (account["id"], code["id"], tx_type, amount, code["created_by"], ts))
        self.send_json(200, {"ok": True, "balance": round(new_balance, 2), "transaction_type": tx_type, "amount": amount})

    def api_wallstreet_order(self, db: Database, user: DbRow | None) -> None:
        err = verified_required(user)
        if err:
            self.error(403 if user else 401, err); return
        settings = get_system_settings(db)
        if not settings["market_open"]:
            self.error(409, "Ravenhood Markets is currently closed."); return
        account = one(db, "SELECT * FROM market_accounts WHERE user_id=?", (user["id"],))
        payload = self.read_json(); ticker = str(payload.get("ticker") or "").upper().strip(); side = str(payload.get("side") or "").lower()
        try: quantity = round(float(payload.get("quantity") or 0), 6)
        except (TypeError, ValueError): quantity = 0
        security = one(db, "SELECT * FROM market_securities WHERE ticker=? AND active=1", (ticker,))
        if not account or not security or side not in ("buy", "sell") or quantity <= 0:
            self.error(400, "Valid account, ticker, side, and quantity are required."); return
        price = float(security["price"]); gross = round(price * quantity, 2); fee = round(gross * settings["market_trade_fee_percent"] / 100, 2)
        holding = one(db, "SELECT * FROM market_holdings WHERE account_id=? AND security_id=?", (account["id"], security["id"]))
        cash = float(account["cash_balance"] or 0)
        if side == "buy":
            total = gross + fee
            if cash < total: self.error(409, "Insufficient settled cash."); return
            old_qty = float(holding["quantity"] or 0) if holding else 0; old_cost = float(holding["average_cost"] or 0) if holding else 0
            avg = ((old_qty * old_cost) + gross) / (old_qty + quantity)
            db.execute("""INSERT INTO market_holdings (account_id, security_id, quantity, average_cost) VALUES (?, ?, ?, ?)
                ON CONFLICT(account_id, security_id) DO UPDATE SET quantity=market_holdings.quantity+excluded.quantity, average_cost=excluded.average_cost""", (account["id"], security["id"], quantity, round(avg, 4)))
            new_cash = cash - total
        else:
            if not holding or float(holding["quantity"] or 0) < quantity: self.error(409, "You do not own enough shares."); return
            db.execute("UPDATE market_holdings SET quantity=quantity-? WHERE id=?", (quantity, holding["id"]))
            new_cash = cash + gross - fee
        db.execute("UPDATE market_accounts SET cash_balance=?, updated_at=? WHERE id=?", (round(new_cash, 2), now_iso(), account["id"]))
        db.execute("INSERT INTO market_orders (account_id, security_id, side, quantity, unit_price, gross_amount, fee_amount, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)", (account["id"], security["id"], side, quantity, price, gross, fee, now_iso()))
        set_system_setting(db, "market_holding_balance", str(round(settings["market_holding_balance"] + fee, 2)))
        self.send_json(201, {"ok": True, "gross": gross, "fee": fee})

    def api_wallstreet_recipient(self, db: Database, user: DbRow | None, query: dict[str, list[str]]) -> None:
        err = verified_required(user)
        if err:
            self.error(403 if user else 401, err); return
        civ_number = str((query.get("civ") or [""])[0]).strip()
        if not civ_number:
            self.error(400, "Enter a CIV number."); return
        target_user = one(db, "SELECT id, name, civ_number FROM users WHERE civ_number=?", (civ_number,))
        if not target_user or target_user["id"] == user["id"]:
            self.error(404, "No eligible Ravenhood recipient was found for that CIV number."); return
        if not one(db, "SELECT id FROM market_accounts WHERE user_id=?", (target_user["id"],)):
            self.error(409, "That resident must create a Ravenhood account before receiving positions."); return
        self.send_json(200, {"recipient": {"name": target_user["name"], "civ_number": target_user["civ_number"], "market_account": True}})

    def api_wallstreet_transfer(self, db: Database, user: DbRow | None) -> None:
        err = verified_required(user)
        if err:
            self.error(403 if user else 401, err); return
        payload = self.read_json(); recipient = str(payload.get("recipient_civ_number") or "").strip(); ticker = str(payload.get("ticker") or "").upper().strip()
        try: quantity = round(float(payload.get("quantity") or 0), 6)
        except (TypeError, ValueError): quantity = 0
        sender = one(db, "SELECT * FROM market_accounts WHERE user_id=?", (user["id"],)); target_user = one(db, "SELECT * FROM users WHERE civ_number=?", (recipient,))
        security = one(db, "SELECT * FROM market_securities WHERE ticker=?", (ticker,))
        if not sender or not target_user or target_user["id"] == user["id"] or not security or quantity <= 0:
            self.error(400, "A confirmed recipient CIV, ticker, and quantity are required."); return
        target = one(db, "SELECT * FROM market_accounts WHERE user_id=?", (target_user["id"],))
        if not target: self.error(409, "Recipient must create a Ravenhood account first."); return
        holding = one(db, "SELECT * FROM market_holdings WHERE account_id=? AND security_id=?", (sender["id"], security["id"]))
        if not holding or float(holding["quantity"] or 0) < quantity: self.error(409, "Insufficient shares."); return
        settings = get_system_settings(db); fee = round(float(security["price"]) * quantity * settings["market_transfer_fee_percent"] / 100, 2)
        if float(sender["cash_balance"] or 0) < fee: self.error(409, "Insufficient settled cash for transfer fee."); return
        db.execute("UPDATE market_holdings SET quantity=quantity-? WHERE id=?", (quantity, holding["id"]))
        db.execute("""INSERT INTO market_holdings (account_id, security_id, quantity, average_cost) VALUES (?, ?, ?, ?)
            ON CONFLICT(account_id, security_id) DO UPDATE SET quantity=market_holdings.quantity+excluded.quantity""", (target["id"], security["id"], quantity, holding["average_cost"]))
        db.execute("UPDATE market_accounts SET cash_balance=cash_balance-?, updated_at=? WHERE id=?", (fee, now_iso(), sender["id"]))
        db.execute("INSERT INTO market_transfers (from_account_id, to_account_id, security_id, quantity, fee_amount, created_at) VALUES (?, ?, ?, ?, ?, ?)", (sender["id"], target["id"], security["id"], quantity, fee, now_iso()))
        set_system_setting(db, "market_holding_balance", str(round(settings["market_holding_balance"] + fee, 2)))
        self.send_json(201, {"ok": True, "fee": fee})

    def api_wallstreet_redeem_promo(self, db: Database, user: DbRow | None) -> None:
        err = verified_required(user)
        if err:
            self.error(403 if user else 401, err); return
        assert user is not None
        entered_code = str(self.read_json().get("code") or "").upper()
        raw_code = "".join(entered_code.split())
        if len(raw_code) < 6:
            self.error(400, "Enter a valid Ravenhood promotional code."); return
        code_candidates = [raw_code]
        compact_code = raw_code.replace("-", "")
        if compact_code != raw_code:
            code_candidates.append(compact_code)
        promo = None
        for candidate in code_candidates:
            promo = one(db, """SELECT p.*,s.ticker,s.name AS security_name FROM market_promo_codes p
                LEFT JOIN market_securities s ON s.id=p.security_id WHERE p.code_hash=? AND p.active=1""",
                (hashlib.sha256(candidate.encode("utf-8")).hexdigest(),))
            if promo:
                break
        if not promo or (promo.get("expires_at") and promo["expires_at"] <= now_iso()):
            self.error(404, "This promotional code is invalid or no longer active."); return
        if int(promo["redemption_count"] or 0) >= int(promo["max_redemptions"] or 0):
            self.error(409, "This promotional campaign has reached its redemption limit."); return
        if one(db, "SELECT id FROM market_promo_redemptions WHERE promo_id=? AND user_id=?", (promo["id"], user["id"])):
            self.error(409, "You have already redeemed this campaign."); return
        ts = now_iso()
        db.execute("""INSERT INTO market_accounts (user_id,cash_balance,status,created_at,updated_at)
            VALUES (?,0,'active',?,?) ON CONFLICT(user_id) DO NOTHING""", (user["id"], ts, ts))
        account = one(db, "SELECT * FROM market_accounts WHERE user_id=?", (user["id"],))
        reward_type = str(promo["reward_type"]); summary = ""
        if reward_type == "cash":
            amount = round(float(promo["cash_amount"] or 0), 2)
            db.execute("UPDATE market_accounts SET cash_balance=cash_balance+?,updated_at=? WHERE id=?", (amount, ts, account["id"]))
            summary = f"${amount:,.2f} Ravenhood buying power"
        else:
            securities: list[DbRow]
            if reward_type == "stock":
                securities = [one(db, "SELECT * FROM market_securities WHERE id=? AND active=1", (promo["security_id"],))]
                securities = [row for row in securities if row]
            else:
                pool = all_rows(db, "SELECT * FROM market_securities WHERE active=1 AND security_type='stock' ORDER BY ticker")
                securities = []
                for _ in range(min(int(promo["bundle_size"] or 0), len(pool))):
                    picked = pool.pop(secrets.randbelow(len(pool))); securities.append(picked)
            if not securities:
                self.error(409, "The securities assigned to this campaign are unavailable."); return
            quantity = round(float(promo["share_quantity"] or 1), 6)
            for security in securities:
                db.execute("""INSERT INTO market_holdings (account_id,security_id,quantity,average_cost) VALUES (?,?,?,0)
                    ON CONFLICT(account_id,security_id) DO UPDATE SET quantity=market_holdings.quantity+excluded.quantity""",
                    (account["id"], security["id"], quantity))
            summary = ", ".join(f"{quantity:g} {security['ticker']}" for security in securities)
        db.execute("""INSERT INTO market_promo_redemptions (promo_id,user_id,account_id,reward_summary,redeemed_at)
            VALUES (?,?,?,?,?)""", (promo["id"], user["id"], account["id"], summary, ts))
        db.execute("UPDATE market_promo_codes SET redemption_count=redemption_count+1 WHERE id=?", (promo["id"],))
        add_admin_audit(db, int(user["id"]), "market.promotion.redeemed", int(user["id"]), {
            "campaign": promo["campaign_name"],
            "code": promo["code_plain"] or promo["code_hint"],
            "reward": summary,
        })
        self.send_json(200, {"ok": True, "campaign_name": promo["campaign_name"], "reward_summary": summary})

    def api_lottery(self, db: Database, user: DbRow | None) -> None:
        err = verified_required(user)
        if err:
            self.error(403 if user else 401, err); return
        assert user is not None
        settings = get_system_settings(db); run_due_lottery_draws(db); run_due_quick_draws(db, settings); draw = ensure_lottery_draw(db, settings)
        roles = roles_for(user); excluded = sorted(set(roles) & set(settings["lottery_excluded_roles"]))
        weight = max([settings["lottery_role_weights"].get(role, 1.0) for role in roles] or [1.0])
        today = utcnow().astimezone(ZoneInfo(settings["lottery_timezone"])).date().isoformat()
        entries = all_rows(db, "SELECT * FROM lottery_entries WHERE draw_id=? AND user_id=? ORDER BY created_at DESC", (draw["id"], user["id"]))
        today_count = sum(1 for entry in entries if entry["entry_date"] == today and str(entry.get("source") or "standard") == "standard")
        funding = lottery_funding_snapshot(db, settings)
        latest = one(db, """SELECT d.*,u.name AS winner_name,u.civ_number AS winner_civ FROM lottery_draws d LEFT JOIN users u ON u.id=d.winner_user_id WHERE d.status='completed' ORDER BY d.completed_at DESC LIMIT 1""")
        latest_prizes = [dict(row) for row in all_rows(db, "SELECT prize_name,prize_type,provider,display_value,quantity,sponsor FROM lottery_special_prizes WHERE draw_id=? AND status='awarded' ORDER BY id", (latest["id"],))] if latest else []
        scratch_cards = [dict(row) for row in all_rows(db, "SELECT * FROM lottery_scratch_cards WHERE user_id=? AND card_date=? ORDER BY card_number", (user["id"], today))]
        quick_draw = ensure_quick_draw(db, settings)
        quick_entries = [dict(row) for row in all_rows(db, "SELECT * FROM lottery_quick_draw_entries WHERE draw_id=? AND user_id=? ORDER BY entry_number", (quick_draw["id"], user["id"]))]
        quick_latest = one(db, "SELECT d.*,u.name AS winner_name,u.civ_number AS winner_civ FROM lottery_quick_draws d LEFT JOIN users u ON u.id=d.winner_user_id WHERE d.status='completed' ORDER BY d.completed_at DESC LIMIT 1")
        self.send_json(200, {"enabled": settings["lottery_enabled"], "draw": dict(draw), "funding": funding, "player_pool": lottery_player_pool_status(db, settings), "entries": [dict(row) for row in entries], "entries_today": today_count, "daily_limit": settings["lottery_daily_entries"], "remaining_today": max(0, settings["lottery_daily_entries"]-today_count), "role_weight": weight, "excluded": bool(excluded), "excluded_roles": excluded, "latest_result": dict(latest) if latest else None, "latest_special_prizes": latest_prizes, "timezone": settings["lottery_timezone"], "scratch": {"enabled": settings["lottery_scratch_enabled"], "daily_limit": settings["lottery_scratch_daily_cards"], "cards": scratch_cards}, "quick_draw": {"enabled": settings["lottery_quick_draw_enabled"], "draw": dict(quick_draw), "daily_limit": settings["lottery_quick_draw_entries"], "entries": quick_entries, "latest_result": dict(quick_latest) if quick_latest else None}})

    def api_lottery_entry(self, db: Database, user: DbRow | None) -> None:
        err = verified_required(user)
        if err:
            self.error(403 if user else 401, err); return
        assert user is not None
        settings = get_system_settings(db)
        if not settings["lottery_enabled"]:
            self.error(409, "Lottery entries are currently closed."); return
        roles = roles_for(user); excluded = sorted(set(roles) & set(settings["lottery_excluded_roles"]))
        if excluded:
            self.error(403, "This account is excluded from lottery participation by role policy."); return
        draw = ensure_lottery_draw(db, settings); today = utcnow().astimezone(ZoneInfo(settings["lottery_timezone"])).date().isoformat()
        # Serialize this resident's daily entry allocation. The database key is
        # (user_id, entry_date, entry_number), not draw_id, so draw rollover and
        # fast repeated requests must share one daily number sequence.
        one(db, "SELECT id FROM users WHERE id=? FOR UPDATE", (user["id"],))
        count = int(one(db, "SELECT COUNT(*) AS count FROM lottery_entries WHERE user_id=? AND entry_date=? AND source='standard'", (user["id"], today))["count"] or 0)
        if count >= settings["lottery_daily_entries"]:
            self.error(409, "All daily lottery entries have already been submitted."); return
        weight = max([settings["lottery_role_weights"].get(role, 1.0) for role in roles] or [1.0])
        next_number = int(one(db, "SELECT COALESCE(MAX(entry_number),0) AS maximum FROM lottery_entries WHERE user_id=? AND entry_date=?", (user["id"], today))["maximum"] or 0) + 1
        db.execute("INSERT INTO lottery_entries (draw_id,user_id,entry_date,entry_number,role_weight,source,created_at) VALUES (?,?,?,?,?,'standard',?)", (draw["id"], user["id"], today, next_number, weight, now_iso()))
        self.send_json(201, {"ok": True, "entry_number": next_number, "remaining_today": settings["lottery_daily_entries"]-count-1})

    def api_lottery_scratch(self, db: Database, user: DbRow | None) -> None:
        err = verified_required(user)
        if err:
            self.error(403 if user else 401, err); return
        assert user is not None
        settings = get_system_settings(db)
        if not settings["lottery_enabled"] or not settings["lottery_scratch_enabled"]:
            self.error(409, "Scratch cards are currently unavailable."); return
        excluded = sorted(set(roles_for(user)) & set(settings["lottery_excluded_roles"]))
        if excluded:
            self.error(403, "This account is excluded from lottery participation by role policy."); return
        today = utcnow().astimezone(ZoneInfo(settings["lottery_timezone"])).date().isoformat()
        existing = all_rows(db, "SELECT * FROM lottery_scratch_cards WHERE user_id=? AND card_date=? ORDER BY card_number", (user["id"], today))
        if len(existing) >= settings["lottery_scratch_daily_cards"]:
            self.error(409, "All daily scratch cards have already been revealed."); return
        roll = secrets.randbelow(1000)
        outcome, bonus = ("jackpot", 3) if roll < 10 else (("bonus", 1) if roll < 180 else ("no_win", 0))
        number = len(existing) + 1
        db.execute("INSERT INTO lottery_scratch_cards (user_id,card_date,card_number,status,outcome,bonus_entries,revealed_at,created_at) VALUES (?,?,?,'revealed',?,?,?,?)", (user["id"], today, number, outcome, bonus, now_iso(), now_iso()))
        if bonus:
            award_lottery_bonus_entries(db, int(user["id"]), bonus, "scratch_bonus")
            add_message(db, user["id"], "Faircroft Lottery Scratch", f"Your scratch card revealed {bonus} bonus official drawing {'entry' if bonus == 1 else 'entries'}. They are now attached to your next weekly drawing.")
        self.send_json(201, {"ok": True, "outcome": outcome, "bonus_entries": bonus, "card_number": number})

