    def api_dev_generate_admin_2fa_code(self, db: Database, user: DbRow | None) -> None:
        err = developer_required(user)
        if err:
            self.error(403 if user else 401, err)
            return
        payload = self.read_json()
        try:
            expiry_minutes = max(5, min(int(payload.get("expiry_minutes") or 15), 120))
        except (TypeError, ValueError):
            self.error(400, "Expiry must be a number of minutes")
            return
        alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"
        raw_code = "ADM-" + "".join(secrets.choice(alphabet) for _ in range(4)) + "-" + "".join(secrets.choice(alphabet) for _ in range(4))
        code_hash = hashlib.sha256(raw_code.upper().encode("utf-8")).hexdigest()
        created_at = utcnow()
        expires_at = created_at + dt.timedelta(minutes=expiry_minutes)
        db.execute(
            """
            INSERT INTO admin_2fa_codes
            (code_hash, code_hint, purpose, created_by, expires_at, uses_remaining, created_at)
            VALUES (?, ?, 'admin_enforcement', ?, ?, 1, ?)
            """,
            (code_hash, raw_code[-4:], user["id"], expires_at.isoformat(), created_at.isoformat()),
        )
        add_admin_audit(db, int(user["id"]), "admin.2fa.created", details={"code_hint": raw_code[-4:], "expires_at": expires_at.isoformat()})
        self.send_json(201, {"ok": True, "code": raw_code, "expires_at": expires_at.isoformat(), "uses": 1})

    def api_dev_market_code(self, db: Database, user: DbRow | None) -> None:
        err = developer_required(user)
        if err:
            self.error(403 if user else 401, err); return
        payload = self.read_json()
        try:
            target_user_id = None
            expiry = max(5, min(int(payload.get("expiry_minutes") or 30), 120))
        except (TypeError, ValueError):
            self.error(400, "Enter a valid expiry window."); return
        tx_type = str(payload.get("transaction_type") or "").lower()
        confirmation = str(payload.get("confirmation") or "").strip().upper()
        required = "MONEY RECEIVED" if tx_type == "deposit" else "WITHDRAWAL APPROVED"
        if tx_type not in ("deposit", "withdrawal") or confirmation != required:
            self.error(400, f"Confirm {required} only after the in-game handoff is complete."); return
        raw_code = ""; code_hash = ""
        for _ in range(30):
            raw_code = f"{secrets.randbelow(10000):04d}"; code_hash = hashlib.sha256(raw_code.encode("utf-8")).hexdigest()
            market_match = one(db, "SELECT id FROM market_cash_codes WHERE code_hash=? AND used_at IS NULL AND revoked_at IS NULL", (code_hash,))
            myfc_match = one(db, "SELECT id FROM myfaircroft_payment_codes WHERE code_hash=? AND used_at IS NULL AND revoked_at IS NULL", (code_hash,))
            if not market_match and not myfc_match: break
        created = utcnow(); expires = created + dt.timedelta(minutes=expiry)
        db.execute("""INSERT INTO market_cash_codes (code_hash, code_hint, target_user_id, transaction_type, amount, created_by, expires_at, created_at)
            VALUES (?, ?, ?, ?, 0, ?, ?, ?)""", (code_hash, raw_code[-2:], target_user_id, tx_type, user["id"], expires.isoformat(), created.isoformat()))
        db.execute("""INSERT INTO myfaircroft_payment_codes
            (code_hash, code_hint, target_user_id, authorized_amount, created_by, expires_at, created_at)
            VALUES (?, ?, NULL, 0, ?, ?, ?) ON CONFLICT(code_hash) DO NOTHING""",
            (code_hash, raw_code[-2:], user["id"], expires.isoformat(), created.isoformat()))
        add_admin_audit(db, int(user["id"]), f"market.{tx_type}.code_created", target_user_id, {"expires_at": expires.isoformat(), "unassigned": True, "amount_bound": False})
        self.send_json(201, {"ok": True, "code": raw_code, "transaction_type": tx_type, "unassigned": True, "expires_at": expires.isoformat()})

    def api_dev_market_promotion(self, db: Database, user: DbRow | None) -> None:
        err = developer_required(user)
        if err:
            self.error(403 if user else 401, err); return
        assert user is not None
        payload = self.read_json(); reward_type = str(payload.get("reward_type") or "").lower()
        campaign_name = str(payload.get("campaign_name") or "").strip()[:120]
        if reward_type not in ("cash", "stock", "random_bundle") or not campaign_name:
            self.error(400, "Campaign name and a valid reward type are required."); return
        try:
            cash_amount = round(max(0, float(payload.get("cash_amount") or 0)), 2)
            share_quantity = round(max(0.000001, float(payload.get("share_quantity") or 1)), 6)
            bundle_size = int(payload.get("bundle_size") or 0)
            max_redemptions = max(1, min(100000, int(payload.get("max_redemptions") or 1)))
            expiry_days = max(1, min(365, int(payload.get("expiry_days") or 30)))
        except (TypeError, ValueError):
            self.error(400, "Reward values, limits, and expiration must be numeric."); return
        if reward_type == "cash" and cash_amount <= 0:
            self.error(400, "Enter a positive Ravenhood cash reward."); return
        if reward_type == "random_bundle" and bundle_size not in (3, 5, 9):
            self.error(400, "Random starter bundles must contain 3, 5, or 9 stocks."); return
        security = None
        if reward_type == "stock":
            security = one(db, "SELECT id,ticker FROM market_securities WHERE ticker=? AND active=1", (str(payload.get("ticker") or "").upper().strip(),))
            if not security:
                self.error(400, "Select an active Ravenhood security."); return
        alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"
        custom = str(payload.get("custom_code") or "").upper().strip().replace(" ", "")
        raw_code = custom or "FCX-" + "".join(secrets.choice(alphabet) for _ in range(4)) + "-" + "".join(secrets.choice(alphabet) for _ in range(4))
        if len(raw_code) < 6 or len(raw_code) > 32:
            self.error(400, "Promo codes must contain between 6 and 32 characters."); return
        canonical_code = raw_code.replace("-", "")
        code_hash = hashlib.sha256(canonical_code.encode("utf-8")).hexdigest()
        legacy_hash = hashlib.sha256(raw_code.encode("utf-8")).hexdigest()
        if one(db, "SELECT id FROM market_promo_codes WHERE code_hash IN (?,?)", (code_hash, legacy_hash)):
            self.error(409, "That promotional code already exists."); return
        created = utcnow(); expires = created + dt.timedelta(days=expiry_days)
        db.execute("""INSERT INTO market_promo_codes
            (campaign_name,code_hash,code_hint,code_plain,reward_type,cash_amount,security_id,share_quantity,bundle_size,max_redemptions,expires_at,created_by,created_at)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)""", (campaign_name, code_hash, raw_code[-4:], raw_code, reward_type, cash_amount,
            security["id"] if security else None, share_quantity, bundle_size, max_redemptions, expires.isoformat(), user["id"], created.isoformat()))
        add_admin_audit(db, int(user["id"]), "market.promotion.created", details={
            "campaign": campaign_name,
            "code": raw_code,
            "reward_type": reward_type,
            "max_redemptions": max_redemptions,
        })
        self.send_json(201, {"ok": True, "code": raw_code, "campaign_name": campaign_name, "expires_at": expires.isoformat()})

