    def api_dev_generate_myfaircroft_payment_code(self, db: Database, user: DbRow | None) -> None:
        err = developer_required(user)
        if err:
            self.error(403 if user else 401, err)
            return
        assert user is not None
        payload = self.read_json()
        try:
            target_user_id = None
            expiry_minutes = max(5, min(int(payload.get("expiry_minutes") or 30), 120))
        except (TypeError, ValueError):
            self.error(400, "Enter a valid expiry window")
            return
        target = None
        raw_code = ""
        code_hash = ""
        for _ in range(30):
            raw_code = f"{secrets.randbelow(10000):04d}"
            code_hash = hashlib.sha256(raw_code.encode("utf-8")).hexdigest()
            myfc_match = one(db, "SELECT id FROM myfaircroft_payment_codes WHERE code_hash = ? AND used_at IS NULL AND revoked_at IS NULL AND expires_at > ?", (code_hash, now_iso()))
            market_match = one(db, "SELECT id FROM market_cash_codes WHERE code_hash = ? AND used_at IS NULL AND revoked_at IS NULL AND expires_at > ?", (code_hash, now_iso()))
            if not myfc_match and not market_match:
                break
        created_at = utcnow()
        expires_at = created_at + dt.timedelta(minutes=expiry_minutes)
        db.execute(
            """INSERT INTO myfaircroft_payment_codes
               (code_hash, code_hint, target_user_id, authorized_amount, created_by, expires_at, created_at)
               VALUES (?, ?, ?, ?, ?, ?, ?)""",
            (code_hash, raw_code[-2:], target_user_id, 0, user["id"], expires_at.isoformat(), created_at.isoformat()),
        )
        db.execute("""INSERT INTO market_cash_codes
            (code_hash, code_hint, target_user_id, transaction_type, amount, created_by, expires_at, created_at)
            VALUES (?, ?, NULL, 'universal', 0, ?, ?, ?) ON CONFLICT(code_hash) DO NOTHING""",
            (code_hash, raw_code[-2:], user["id"], expires_at.isoformat(), created_at.isoformat()))
        add_admin_audit(
            db, int(user["id"]), "myfaircroft.payment_code.created", target_user_id,
            {"expires_at": expires_at.isoformat(), "notice": "Unassigned bearer receipt issued after in-game handoff", "amount_bound": False},
        )
        self.send_json(201, {
            "ok": True, "code": raw_code,
            "target_name": target["name"] if target else "Any eligible resident", "unassigned": target is None, "expires_at": expires_at.isoformat(),
        })

    def api_dev_account(self, db: Database, user: DbRow | None, target_id: int) -> None:
        err = developer_required(user)
        if err:
            self.error(403 if user else 401, err)
            return
        account = one(
            db,
            """
            SELECT u.*, l.id AS link_id, l.server_id, l.identity_id, l.uid,
                   l.rpl_identity, l.platform, l.player_name, l.linked_at,
                   l.last_seen_at, l.last_sync_at
            FROM users u
            LEFT JOIN arma_account_links l ON l.user_id = u.id
            WHERE u.id = ?
            """,
            (target_id,),
        )
        if not account:
            self.error(404, "Account not found")
            return
        if not account.get("link_id"):
            self.error(409, "This account does not have an active Arma link")
            return
        sanctions = all_rows(
            db,
            """
            SELECT s.*, creator.name AS created_by_name, revoker.name AS revoked_by_name
            FROM account_sanctions s
            JOIN users creator ON creator.id = s.created_by
            LEFT JOIN users revoker ON revoker.id = s.revoked_by
            WHERE s.user_id = ? ORDER BY s.created_at DESC LIMIT 100
            """,
            (target_id,),
        )
        warnings = all_rows(
            db,
            """
            SELECT w.*, creator.name AS created_by_name, resolver.name AS resolved_by_name
            FROM account_internal_warnings w
            JOIN users creator ON creator.id = w.created_by
            LEFT JOIN users resolver ON resolver.id = w.resolved_by
            WHERE w.user_id = ? ORDER BY w.created_at DESC LIMIT 100
            """,
            (target_id,),
        )
        arma_activity = all_rows(
            db,
            """
            SELECT * FROM arma_activity_logs
            WHERE user_id = ? ORDER BY received_at DESC LIMIT 150
            """,
            (target_id,),
        )
        characters = all_rows(
            db,
            "SELECT * FROM user_characters WHERE user_id = ? ORDER BY is_active DESC, updated_at DESC",
            (target_id,),
        )
        jobs = all_rows(
            db,
            """
            SELECT uj.*, j.title, j.market
            FROM user_jobs uj JOIN jobs j ON j.id = uj.job_id
            WHERE uj.user_id = ? ORDER BY uj.started_at DESC
            """,
            (target_id,),
        )
        citations = all_rows(
            db,
            """
            SELECT c.*
            FROM citations c
            WHERE c.civ_id = ? ORDER BY c.created_at DESC LIMIT 100
            """,
            (target_id,),
        )
        properties = all_rows(
            db,
            """
            SELECT p.* FROM properties p
            WHERE p.owner_id = ? ORDER BY p.created_at DESC
            """,
            (target_id,),
        )
        active_block = active_account_block(db, target_id)
        game_bank = one(
            db,
            "SELECT * FROM arma_game_bank_balances WHERE identity_id = ?",
            (account.get("identity_id") or "",),
        )
        self.send_dev_account_response(
            db,
            account,
            active_block,
            sanctions,
            warnings,
            arma_activity,
            characters,
            jobs,
            citations,
            properties,
            game_bank,
        )

    def api_dev_update_application_intake(self, db: Database, user: DbRow | None) -> None:
        err = developer_required(user)
        if err:
            self.error(403 if user else 401, err)
            return
        assert user is not None
        payload = self.read_json()
        raw_intake = payload.get("application_intake")
        valid_keys = {str(posting["key"]) for posting in DEPARTMENT_POSTINGS}
        if isinstance(raw_intake, dict):
            intake = {key: bool(raw_intake.get(key, True)) for key in valid_keys}
        else:
            accepting = bool(payload.get("accepting"))
            intake = {key: accepting for key in valid_keys}
        set_system_setting(db, "application_intake", json.dumps(intake, separators=(",", ":"), sort_keys=True))
        accepting = any(intake.values())
        set_system_setting(db, "applications_accepting", "1" if accepting else "0")
        add_admin_audit(
            db,
            int(user["id"]),
            "system.application_intake.updated",
            details={"accepting": accepting, "application_intake": intake},
        )
        self.send_json(200, {"ok": True, "applications_accepting": accepting, "application_intake": intake})

    def api_dev_update_fnn_settings(self, db: Database, user: DbRow | None) -> None:
        err = developer_required(user)
        if err:
            self.error(403 if user else 401, err)
            return
        assert user is not None
        payload = self.read_json()
        try:
            pass_limit = max(0, min(500, int(payload.get("press_pass_limit"))))
        except (TypeError, ValueError):
            self.error(400, "Press Pass limit must be a whole number from 0 to 500")
            return
        autopilot_enabled = bool(payload.get("autopilot_enabled"))
        morning_time = str(payload.get("morning_time") or "05:00").strip()
        evening_time = str(payload.get("evening_time") or "17:00").strip()
        timezone_name = str(payload.get("timezone") or "America/New_York").strip()[:80]
        if not re.fullmatch(r"(?:[01]\d|2[0-3]):[0-5]\d", morning_time) or not re.fullmatch(r"(?:[01]\d|2[0-3]):[0-5]\d", evening_time):
            self.error(400, "News cycle times must use a valid 24-hour HH:MM time")
            return
        try:
            ZoneInfo(timezone_name)
        except Exception:
            self.error(400, "Enter a valid IANA newsroom timezone")
            return
        set_system_setting(db, "fnn_press_pass_limit", str(pass_limit))
        set_system_setting(db, "fnn_autopilot_enabled", "1" if autopilot_enabled else "0")
        set_system_setting(db, "fnn_autopilot_morning_time", morning_time)
        set_system_setting(db, "fnn_autopilot_evening_time", evening_time)
        set_system_setting(db, "fnn_autopilot_timezone", timezone_name)
        active_count = sum(1 for account in all_rows(db, "SELECT roles FROM users") if has_any(account, "press"))
        issued_now = 0
        if active_count < pass_limit:
            waiting = all_rows(
                db,
                """
                SELECT a.*, applicant.roles
                FROM department_applications a
                JOIN users applicant ON applicant.id = a.user_id
                WHERE a.department_key = 'press' AND a.status IN ('submitted','under_review')
                ORDER BY a.created_at ASC
                """,
            )
            for application in waiting:
                if active_count >= pass_limit:
                    break
                try:
                    exam = json.loads(application["statement"])
                    eligible = int(exam.get("score") or 0) >= 8
                except (TypeError, ValueError, json.JSONDecodeError):
                    eligible = False
                if not eligible:
                    continue
                updated_roles = sorted(set([*roles_for(application), "press"]))
                ts = now_iso()
                db.execute(
                    """UPDATE users SET verified = 1, roles = ?, press_pass_status = 'active',
                       press_pass_reason = '', press_pass_action_at = ?, press_pass_notice_pending = 0
                       WHERE id = ?""",
                    (json.dumps(updated_roles), ts, application["user_id"]),
                )
                db.execute(
                    "UPDATE department_applications SET status = 'approved', reviewer_notes = ?, updated_at = ? WHERE id = ?",
                    ("Automatically certified after FNN Press Pass capacity became available.", ts, application["id"]),
                )
                add_message(db, application["user_id"], "FNN Press Pass issued", "Press Pass capacity became available. Your passing examination was certified automatically and Press Desk access is now active.")
                active_count += 1
                issued_now += 1
        add_admin_audit(db, int(user["id"]), "fnn.settings.updated", details={"press_pass_limit": pass_limit, "issued_now": issued_now, "autopilot_enabled": autopilot_enabled, "morning_time": morning_time, "evening_time": evening_time, "timezone": timezone_name})
        self.send_json(200, {"ok": True, "press_pass_limit": pass_limit, "issued_now": issued_now, "autopilot_enabled": autopilot_enabled})

