    def send_dev_account_response(
        self,
        db: Database,
        account: DbRow,
        active_block: DbRow | None,
        sanctions: list[DbRow],
        warnings: list[DbRow],
        arma_activity: list[DbRow],
        characters: list[DbRow],
        jobs: list[DbRow],
        citations: list[DbRow],
        properties: list[DbRow],
        game_bank: DbRow | None,
    ) -> None:
        identity_candidates = [
            str(account.get("identity_id") or "").strip(),
            str(account.get("uid") or "").strip(),
            str(account.get("rpl_identity") or "").strip(),
        ]
        # Short numeric RPL values and generic component IDs occur throughout EPF
        # payloads. Only stable, sufficiently specific identifiers may correlate
        # a persistence record to a player.
        identity_candidates = [
            value for value in dict.fromkeys(identity_candidates)
            if len(value) >= 8
        ]
        persistence_records: list[DbRow] = []
        if identity_candidates:
            clauses: list[str] = []
            params: list[str] = []
            for identity in identity_candidates:
                clauses.extend([
                    "record_id = ?",
                    "owner_identity = ?",
                    "identity_values LIKE ?",
                ])
                params.extend([identity, identity, f'%"{identity}"%'])
            persistence_records = all_rows(
                db,
                f"""
                SELECT source_path, category, record_id, title, owner_identity,
                       identity_values, component_types, prefab, record_status,
                       amount_text, summary_payload, source_modified_at, synced_at
                FROM game_persistence_records
                WHERE {" OR ".join(clauses)}
                ORDER BY category, source_modified_at DESC, record_id
                LIMIT 500
                """,
                tuple(params),
            )
        normalized_persistence: list[dict[str, Any]] = []
        for row in persistence_records:
            record = dict(row)
            for key, fallback in (("identity_values", []), ("component_types", []), ("summary_payload", {})):
                try:
                    record[key] = json.loads(record.get(key) or json.dumps(fallback))
                except json.JSONDecodeError:
                    record[key] = fallback
            record["match_confidence"] = "verified identifier"
            normalized_persistence.append(record)
        persistence_sync = one(
            db,
            "SELECT * FROM game_persistence_sync_status ORDER BY updated_at DESC LIMIT 1",
        )
        anticheat_record = one(
            db,
            """
            SELECT p.*,
                   COALESCE(NULLIF(p.reported_system, ''), NULLIF(?, ''), 'Unknown') AS detected_system
            FROM anticheat_players p
            WHERE p.uid = ? OR p.uid = ?
            ORDER BY p.last_synced_at DESC
            LIMIT 1
            """,
            (
                account.get("platform") or "",
                account.get("uid") or "",
                account.get("identity_id") or "",
            ),
        )
        response_account = public_user(account)
        response_account.update(
            {
                "identity_id": account.get("identity_id") or "",
                "uid": account.get("uid") or "",
                "rpl_identity": account.get("rpl_identity") or "",
                "platform": account.get("platform") or "",
                "player_name": account.get("player_name") or "",
                "server_id": account.get("server_id") or "",
                "linked_at": account.get("linked_at"),
                "last_seen_at": account.get("last_seen_at"),
                "last_sync_at": account.get("last_sync_at"),
            }
        )
        self.send_json(
            200,
            {
                "account": response_account,
                "active_block": dict(active_block) if active_block else None,
                "sanctions": [dict(row) for row in sanctions],
                "warnings": [dict(row) for row in warnings],
                "arma_activity": [dict(row) for row in arma_activity],
                "characters": [dict(row) for row in characters],
                "jobs": [dict(row) for row in jobs],
                "citations": [dict(row) for row in citations],
                "properties": [dict(row) for row in properties],
                "anti_cheat": dict(anticheat_record) if anticheat_record else {
                    "detected_system": account.get("platform") or "Unknown",
                    "reported_system": "",
                    "status": "awaiting_anti_cheat_match",
                },
                "game_database": {
                    "status": "synced" if game_bank or persistence_records else "awaiting_sync",
                    "source": "FCRPMUSSALO",
                    "collections": [
                        "Banks", "Characters", "CopChats", "Criminals", "Items",
                        "PoliceReports", "RootEntityCollections", "Turrets", "Vehicles",
                    ],
                    "bank": dict(game_bank) if game_bank else None,
                    "records": normalized_persistence,
                    "sync": dict(persistence_sync) if persistence_sync else None,
                    "read_only": True,
                    "transaction_history_available": False,
                },
            },
        )

    def api_dev_create_sanction(self, db: Database, user: DbRow | None) -> None:
        err = developer_required(user)
        if err:
            self.error(403 if user else 401, err)
            return
        payload = self.read_json()
        missing = require_fields(payload, "user_id", "sanction_type", "reason")
        if missing:
            self.error(400, missing)
            return
        sanction_type = str(payload["sanction_type"]).strip().lower()
        if sanction_type not in ("ban", "timeout", "sanction"):
            self.error(400, "Sanction type must be ban, timeout, or sanction")
            return
        report_fields = (
            "rule_code",
            "incident_at",
            "incident_summary",
            "evidence",
            "staff_findings",
            "appeal_guidance",
        )
        if sanction_type in ("ban", "timeout"):
            report_missing = require_fields(payload, *report_fields)
            if report_missing:
                self.error(400, f"A complete enforcement report is required: {report_missing}")
                return
            if len(str(payload.get("incident_summary") or "").strip()) < 40:
                self.error(400, "Incident summary must contain at least 40 characters")
                return
            if len(str(payload.get("staff_findings") or "").strip()) < 30:
                self.error(400, "Staff findings must contain at least 30 characters")
                return
            if len(str(payload.get("evidence") or "").strip()) < 10:
                self.error(400, "Evidence and log references must contain at least 10 characters")
                return
        target_id = int(payload["user_id"])
        target = one(db, "SELECT * FROM users WHERE id = ?", (target_id,))
        if not target:
            self.error(404, "Target account not found")
            return
        if has_any(target, "owner") and not has_any(user, "owner"):
            self.error(403, "Only the owner can sanction an owner account")
            return
        starts_at = utcnow()
        report_number = f"FR-{starts_at.strftime('%Y%m%d')}-{secrets.randbelow(900000) + 100000}"
        expires_at: str | None = None
        try:
            bail_amount = max(0.0, min(float(payload.get("bail_amount") or 0), 10_000_000.0))
        except (TypeError, ValueError):
            self.error(400, "Bail amount must be a valid number")
            return
        if sanction_type == "timeout":
            try:
                duration_minutes = max(1, min(int(payload.get("duration_minutes") or 60), 525600))
            except (TypeError, ValueError):
                self.error(400, "Timeout duration must be a number of minutes")
                return
            expires_at = (starts_at + dt.timedelta(minutes=duration_minutes)).isoformat()
        elif sanction_type == "sanction" and payload.get("duration_minutes"):
            expires_at = (starts_at + dt.timedelta(minutes=max(1, int(payload["duration_minutes"])))).isoformat()
        game_enforcement = {"status": "not_required", "response": ""}
        identity = one(
            db,
            "SELECT identity_id FROM arma_account_links WHERE user_id = ? ORDER BY linked_at DESC LIMIT 1",
            (target_id,),
        )
        if sanction_type in ("ban", "timeout"):
            if not identity or not str(identity.get("identity_id") or "").strip():
                self.error(409, "This account has no linked Bohemia identity, so the game ban cannot be applied")
                return
            if not arma_rcon_configured():
                self.error(503, "Arma RCON is not configured. Set ARMA_RCON_HOST, ARMA_RCON_PORT, and ARMA_RCON_PASSWORD.")
                return
            duration_seconds = 0
            if sanction_type == "timeout":
                duration_seconds = duration_minutes * 60
            rcon_reason = " ".join(str(payload["reason"]).replace("#", "").split())[:240]
            try:
                game_enforcement = execute_arma_rcon(
                    f"#ban create {identity['identity_id']} {duration_seconds} {rcon_reason}"
                )
            except (OSError, RuntimeError) as exc:
                add_admin_audit(
                    db,
                    int(user["id"]),
                    f"account.{sanction_type}.rcon_failed",
                    target_id,
                    {"report_number": report_number, "identity_id": identity["identity_id"], "error": str(exc)[:500]},
                )
                self.error(502, f"The enforcement report was not created because Arma RCON failed: {exc}")
                return
        created = db.execute(
            """
            INSERT INTO account_sanctions
            (user_id, sanction_type, reason, report_number, rule_code, incident_at,
             incident_summary, evidence, witness_names, staff_findings, player_statement,
             appeal_guidance, internal_notes, bail_amount, starts_at, expires_at, created_by, created_at,
             game_enforcement_status, game_enforcement_response, game_enforcement_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) RETURNING id
            """,
            (
                target_id,
                sanction_type,
                str(payload["reason"]).strip()[:1200],
                report_number,
                str(payload.get("rule_code") or "").strip()[:40],
                str(payload.get("incident_at") or "").strip()[:80],
                str(payload.get("incident_summary") or "").strip()[:5000],
                str(payload.get("evidence") or "").strip()[:5000],
                str(payload.get("witness_names") or "").strip()[:1200],
                str(payload.get("staff_findings") or "").strip()[:5000],
                str(payload.get("player_statement") or "").strip()[:3000],
                str(payload.get("appeal_guidance") or "").strip()[:2000],
                str(payload.get("internal_notes") or "").strip()[:2000],
                bail_amount,
                starts_at.isoformat(),
                expires_at,
                user["id"],
                starts_at.isoformat(),
                game_enforcement["status"],
                game_enforcement["response"],
                starts_at.isoformat() if game_enforcement["status"] == "applied" else None,
            ),
        ).fetchone()
        add_admin_audit(db, int(user["id"]), f"account.{sanction_type}.created", target_id, {"report_number": report_number, "rule_code": payload.get("rule_code"), "reason": payload["reason"], "expires_at": expires_at, "game_enforcement_status": game_enforcement["status"], "identity_id": identity.get("identity_id") if identity else None})
        self.send_json(
            201,
            {
                "ok": True,
                "id": int(created["id"]),
                "report_number": report_number,
                "expires_at": expires_at,
                "game_enforcement_status": game_enforcement["status"],
                "game_enforcement_response": game_enforcement["response"],
            },
        )

    def api_dev_revoke_sanction(self, db: Database, user: DbRow | None, sanction_id: int) -> None:
        err = developer_required(user)
        if err:
            self.error(403 if user else 401, err)
            return
        sanction = one(db, "SELECT * FROM account_sanctions WHERE id = ?", (sanction_id,))
        if not sanction:
            self.error(404, "Sanction not found")
            return
        if sanction.get("revoked_at"):
            self.error(409, "Sanction is already revoked")
            return
        payload = self.read_json()
        reason = str(payload.get("reason") or "Revoked by staff").strip()[:1000]
        game_enforcement = {"status": "not_required", "response": ""}
        if sanction.get("sanction_type") in ("ban", "timeout"):
            identity = one(
                db,
                "SELECT identity_id FROM arma_account_links WHERE user_id = ? ORDER BY linked_at DESC LIMIT 1",
                (sanction["user_id"],),
            )
            if not identity or not str(identity.get("identity_id") or "").strip():
                self.error(409, "This account has no linked Bohemia identity, so it cannot be unbanned in Arma")
                return
            if not arma_rcon_configured():
                self.error(503, "Arma RCON is not configured. Set ARMA_RCON_HOST, ARMA_RCON_PORT, and ARMA_RCON_PASSWORD.")
                return
            try:
                game_enforcement = execute_arma_rcon(f"#ban remove {identity['identity_id']}")
            except (OSError, RuntimeError) as exc:
                add_admin_audit(
                    db,
                    int(user["id"]),
                    "account.unban.rcon_failed",
                    int(sanction["user_id"]),
                    {"sanction_id": sanction_id, "identity_id": identity["identity_id"], "error": str(exc)[:500]},
                )
                self.error(502, f"The CAD sanction remains active because Arma RCON unban failed: {exc}")
                return
        db.execute(
            """UPDATE account_sanctions
               SET revoked_by = ?, revoked_at = ?, revoke_reason = ?,
                   game_enforcement_status = ?, game_enforcement_response = ?, game_enforcement_at = ?
               WHERE id = ?""",
            (user["id"], now_iso(), reason, game_enforcement["status"], game_enforcement["response"], now_iso() if game_enforcement["status"] == "applied" else None, sanction_id),
        )
        audit_action = "account.unban.applied" if sanction.get("sanction_type") in ("ban", "timeout") else "account.sanction.revoked"
        add_admin_audit(db, int(user["id"]), audit_action, int(sanction["user_id"]), {"sanction_id": sanction_id, "reason": reason, "game_enforcement_status": game_enforcement["status"]})
        self.send_json(200, {"ok": True, "game_enforcement_status": game_enforcement["status"], "game_enforcement_response": game_enforcement["response"]})

    def api_dev_create_warning(self, db: Database, user: DbRow | None) -> None:
        err = developer_required(user)
        if err:
            self.error(403 if user else 401, err)
            return
        payload = self.read_json()
        missing = require_fields(payload, "user_id", "subject", "body")
        if missing:
            self.error(400, missing)
            return
        target_id = int(payload["user_id"])
        if not one(db, "SELECT id FROM users WHERE id = ?", (target_id,)):
            self.error(404, "Target account not found")
            return
        severity = str(payload.get("severity") or "standard").strip().lower()
        if severity not in ("low", "standard", "high", "critical"):
            self.error(400, "Invalid warning severity")
            return
        created = db.execute(
            """
            INSERT INTO account_internal_warnings
            (user_id, severity, subject, body, created_by, created_at)
            VALUES (?, ?, ?, ?, ?, ?) RETURNING id
            """,
            (target_id, severity, str(payload["subject"]).strip()[:160], str(payload["body"]).strip()[:3000], user["id"], now_iso()),
        ).fetchone()
        add_admin_audit(db, int(user["id"]), "account.internal_warning.created", target_id, {"severity": severity, "subject": payload["subject"]})
        self.send_json(201, {"ok": True, "id": int(created["id"])})

    def api_dev_resolve_warning(self, db: Database, user: DbRow | None, warning_id: int) -> None:
        err = developer_required(user)
        if err:
            self.error(403 if user else 401, err)
            return
        warning = one(db, "SELECT * FROM account_internal_warnings WHERE id = ?", (warning_id,))
        if not warning:
            self.error(404, "Warning not found")
            return
        payload = self.read_json()
        notes = str(payload.get("notes") or "Resolved by staff").strip()[:1200]
        db.execute(
            "UPDATE account_internal_warnings SET resolved_by = ?, resolved_at = ?, resolution_notes = ? WHERE id = ?",
            (user["id"], now_iso(), notes, warning_id),
        )
        add_admin_audit(db, int(user["id"]), "account.internal_warning.resolved", int(warning["user_id"]), {"warning_id": warning_id, "notes": notes})
        self.send_json(200, {"ok": True})

    def fine_settlement_payload(self, db: Database) -> dict[str, Any]:
        outstanding_accounts = all_rows(
            db,
            """
            SELECT u.id AS user_id, u.name, u.civ_number,
                   COUNT(c.id) AS outstanding_count, COALESCE(SUM(c.fine_amount), 0) AS outstanding_total,
                   MIN(c.created_at) AS oldest_fine_at, MAX(c.created_at) AS newest_fine_at,
                   COALESCE(d.license_status, 'No license') AS license_status
            FROM citations c
            JOIN users u ON u.id = c.civ_id
            LEFT JOIN dmv_records d ON d.user_id = u.id
            WHERE c.status IN ('issued', 'reviewed', 'reduced', 'closed')
              AND COALESCE(c.disposition, '') NOT IN ('not_guilty', 'dismissed')
            GROUP BY u.id, u.name, u.civ_number, d.license_status
            ORDER BY outstanding_total DESC, oldest_fine_at
            """
        )
        notice_history = all_rows(
            db,
            """SELECT n.*, recipient.name AS recipient_name, recipient.civ_number,
                      creator.name AS created_by_name
               FROM settlement_notices n
               JOIN users recipient ON recipient.id = n.user_id
               JOIN users creator ON creator.id = n.created_by
               ORDER BY n.created_at DESC LIMIT 100""",
        )
        unpaid = all_rows(
            db,
            """
            SELECT c.id, c.charge_code, c.charge_title, c.fine_amount, c.status,
                   c.created_at, u.id AS user_id, u.name, u.civ_number,
                   l.identity_id, b.balance, b.synced_at
            FROM citations c
            JOIN users u ON u.id = c.civ_id
            LEFT JOIN arma_account_links l ON l.user_id = u.id
            LEFT JOIN arma_game_bank_balances b ON b.identity_id = l.identity_id
            LEFT JOIN fine_settlement_items i ON i.citation_id = c.id
            WHERE c.status IN ('issued', 'reviewed', 'reduced', 'closed') AND i.id IS NULL
              AND COALESCE(c.disposition, '') NOT IN ('not_guilty', 'dismissed')
              AND l.identity_id IS NOT NULL AND b.balance IS NOT NULL
              AND b.balance >= c.fine_amount
            ORDER BY c.created_at ASC
            """
        )
        batches = all_rows(
            db,
            """
            SELECT b.*, creator.name AS created_by_name, approver.name AS approved_by_name,
                   COUNT(i.id) AS item_count, COALESCE(SUM(i.fine_amount), 0) AS total_amount
            FROM fine_settlement_batches b
            JOIN users creator ON creator.id = b.created_by
            LEFT JOIN users approver ON approver.id = b.approved_by
            LEFT JOIN fine_settlement_items i ON i.batch_id = b.id
            GROUP BY b.id, creator.name, approver.name
            ORDER BY b.created_at DESC LIMIT 30
            """
        )
        result_batches: list[dict[str, Any]] = []
        for batch in batches:
            item = dict(batch)
            item["items"] = [
                dict(row)
                for row in all_rows(
                    db,
                    """
                    SELECT i.*, c.charge_code, c.charge_title, u.name, u.civ_number,
                           COALESCE(d.license_status, 'No license') AS license_status
                    FROM fine_settlement_items i
                    JOIN citations c ON c.id = i.citation_id
                    JOIN users u ON u.id = i.user_id
                    LEFT JOIN dmv_records d ON d.user_id = i.user_id
                    WHERE i.batch_id = ? ORDER BY i.id
                    """,
                    (batch["id"],),
                )
            ]
            result_batches.append(item)
        tax_ready = all_rows(
            db,
            """
            SELECT b.id AS business_id, b.business_name, b.license_number, u.id AS user_id,
                   u.name AS owner_name, u.civ_number, l.identity_id, bank.balance, bank.synced_at,
                   COUNT(t.id) AS assessment_count, SUM(t.amount) AS tax_amount
            FROM business_tax_assessments t
            JOIN businesses b ON b.id = t.business_id
            JOIN users u ON u.id = b.owner_id
            JOIN arma_account_links l ON l.user_id = u.id
            JOIN arma_game_bank_balances bank ON bank.identity_id = l.identity_id
            WHERE t.status = 'unpaid' AND t.settlement_batch_id IS NULL
            GROUP BY b.id, b.business_name, b.license_number, u.id, u.name, u.civ_number,
                     l.identity_id, bank.balance, bank.synced_at
            HAVING bank.balance >= SUM(t.amount)
            ORDER BY b.business_name
            """
        )
        tax_license_rows = all_rows(
            db,
            """
            SELECT b.*, u.name AS owner_name, u.civ_number AS owner_civ_number,
                   l.identity_id, bank.balance, bank.synced_at,
                   (SELECT COALESCE(SUM(t.amount), 0) FROM business_tax_assessments t
                    WHERE t.business_id = b.id AND t.status = 'unpaid') AS unpaid_tax
            FROM businesses b
            JOIN users u ON u.id = b.owner_id
            LEFT JOIN arma_account_links l ON l.user_id = u.id
            LEFT JOIN arma_game_bank_balances bank ON bank.identity_id = l.identity_id
            WHERE b.status IN ('active', 'suspended', 'revoked', 'expired')
            ORDER BY CASE b.status WHEN 'active' THEN 0 WHEN 'suspended' THEN 1 WHEN 'revoked' THEN 2 ELSE 3 END,
                     unpaid_tax DESC, b.business_name
            """
        )
        tax_licenses = [self.business_license_payload(row) for row in tax_license_rows]
        property_tax_rows = all_rows(
            db,
            """
            SELECT p.*, COALESCE(ra.owner_user_id,l.user_id) AS owner_user_id, u.name AS owner_name,
                   u.civ_number AS owner_civ_number,
                   (SELECT COALESCE(SUM(a.amount), 0)
                      FROM property_tax_assessments a
                     WHERE a.property_id = p.property_id AND a.status = 'unpaid') AS unpaid_property_tax,
                   (SELECT e.action FROM property_enforcement_actions e
                     WHERE e.property_id = p.property_id ORDER BY e.id DESC LIMIT 1) AS latest_enforcement
            FROM game_property_records p
            LEFT JOIN realty_property_assignments ra ON ra.property_id = p.property_id
            LEFT JOIN arma_account_links l
              ON l.identity_id = p.owner_identity OR l.uid = p.owner_identity
            LEFT JOIN users u ON u.id = COALESCE(ra.owner_user_id,l.user_id)
            WHERE (COALESCE(p.owner_identity, '') <> '' OR ra.owner_user_id IS NOT NULL)
              AND LOWER(COALESCE(p.source_file, '')) NOT LIKE '%rented%'
            ORDER BY u.name, p.name, p.property_id
            """,
        )
        property_tax_accounts: list[dict[str, Any]] = []
        property_owner_totals: dict[str, dict[str, Any]] = {}
        for row in property_tax_rows:
            item = dict(row)
            assessed_value = PROPERTY_TAX_BASE_VALUE
            item["source_assessed_value"] = round(assessed_value, 2)
            item["property_tax_rate"] = 0.14
            item["projected_tax"] = round(assessed_value * 0.14, 2)
            item["tax_rate_options"] = [
                {"rate": rate, "percent": int(rate * 100), "amount": round(assessed_value * rate, 2)}
                for rate in PROPERTY_TAX_ALLOWED_RATES
            ]
            item["unpaid_property_tax"] = round(float(item.get("unpaid_property_tax") or 0), 2)
            item["enforcement_state"] = "clear" if item.get("latest_enforcement") in {None, "release"} else item.get("latest_enforcement")
            property_tax_accounts.append(item)
            owner_key = str(item.get("owner_identity") or "unmatched")
            owner = property_owner_totals.setdefault(owner_key, {
                "owner_identity": owner_key,
                "owner_user_id": item.get("owner_user_id"),
                "owner_name": item.get("owner_name") or "Unmatched game identity",
                "owner_civ_number": item.get("owner_civ_number"),
                "property_count": 0,
                "assessed_value": 0.0,
                "projected_tax": 0.0,
                "unpaid_tax": 0.0,
            })
            owner["property_count"] += 1
            owner["assessed_value"] = round(owner["assessed_value"] + assessed_value, 2)
            owner["projected_tax"] = round(owner["projected_tax"] + item["projected_tax"], 2)
            owner["unpaid_tax"] = round(owner["unpaid_tax"] + item["unpaid_property_tax"], 2)
        property_tax_owners = sorted(property_owner_totals.values(), key=lambda item: (-item["unpaid_tax"], -item["property_count"], item["owner_name"]))
        property_enforcement_counts = one(
            db,
            """SELECT
                COALESCE(SUM(CASE WHEN action = 'lien' THEN 1 ELSE 0 END), 0) AS liens,
                COALESCE(SUM(CASE WHEN action = 'seize' THEN 1 ELSE 0 END), 0) AS seizures
                FROM (
                    SELECT DISTINCT ON (property_id) property_id, action
                    FROM property_enforcement_actions
                    ORDER BY property_id, id DESC
                ) latest""",
        ) or {}
        owner_properties: dict[str, list[dict[str, Any]]] = {}
        owner_user_properties: dict[int, list[dict[str, Any]]] = {}
        for item in property_tax_accounts:
            property_summary = {
                "property_id": item["property_id"],
                "name": item.get("name") or item["property_id"],
                "address": item.get("address") or "",
                "enforcement_state": item["enforcement_state"],
            }
            owner_properties.setdefault(str(item.get("owner_identity") or ""), []).append(property_summary)
            if item.get("owner_user_id"):
                owner_user_properties.setdefault(int(item["owner_user_id"]), []).append(property_summary)
        for license_item in tax_licenses:
            license_item["owner_properties"] = owner_user_properties.get(
                int(license_item.get("owner_id") or 0),
                owner_properties.get(str(license_item.get("identity_id") or ""), []),
            )
        tax_summary = {
            "businesses": len(tax_licenses),
            "active": sum(1 for item in tax_licenses if item.get("status") == "active"),
            "suspended": sum(1 for item in tax_licenses if item.get("status") == "suspended"),
            "revoked": sum(1 for item in tax_licenses if item.get("status") == "revoked"),
            "unpaid_total": round(sum(float(item.get("unpaid_tax") or 0) for item in tax_licenses), 2),
            "accrued_total": round(sum(float(item.get("accrued_tax") or 0) for item in tax_licenses), 2),
            "weekly_total": round(sum(float(item.get("weekly_tax") or 0) for item in tax_licenses if item.get("status") == "active"), 2),
        }
        tax_batches = all_rows(
            db,
            """
            SELECT b.*, creator.name AS created_by_name, approver.name AS approved_by_name,
                   COUNT(i.id) AS item_count, COALESCE(SUM(i.tax_amount), 0) AS total_amount
            FROM business_tax_settlement_batches b
            JOIN users creator ON creator.id = b.created_by
            LEFT JOIN users approver ON approver.id = b.approved_by
            LEFT JOIN business_tax_settlement_items i ON i.batch_id = b.id
            GROUP BY b.id, creator.name, approver.name
            ORDER BY b.created_at DESC LIMIT 30
            """
        )
        result_tax_batches: list[dict[str, Any]] = []
        for batch in tax_batches:
            item = dict(batch)
            item["items"] = [
                dict(row) for row in all_rows(
                    db,
                    """
                    SELECT i.*, b.business_name, b.license_number, u.name AS owner_name
                    FROM business_tax_settlement_items i
                    JOIN businesses b ON b.id = i.business_id
                    JOIN users u ON u.id = i.user_id
                    WHERE i.batch_id = ? ORDER BY i.id
                    """,
                    (batch["id"],),
                )
            ]
            result_tax_batches.append(item)
        return {
            "outstanding_accounts": [dict(row) for row in outstanding_accounts],
            "outstanding_count": sum(int(row["outstanding_count"] or 0) for row in outstanding_accounts),
            "outstanding_total": sum(float(row["outstanding_total"] or 0) for row in outstanding_accounts),
            "notice_history": [dict(row) for row in notice_history],
            "unpaid": [dict(row) for row in unpaid],
            "batches": result_batches,
            "tax_ready": [dict(row) for row in tax_ready],
            "tax_licenses": tax_licenses,
            "tax_summary": tax_summary,
            "tax_batches": result_tax_batches,
            "property_tax_accounts": property_tax_accounts,
            "property_tax_owners": property_tax_owners,
            "property_tax_rate": 0.14,
            "property_tax_base_value": PROPERTY_TAX_BASE_VALUE,
            "property_tax_allowed_rates": list(PROPERTY_TAX_ALLOWED_RATES),
            "property_tax_summary": {
                "properties": len(property_tax_accounts),
                "owners": len(property_tax_owners),
                "assessed_value": round(sum(item["source_assessed_value"] for item in property_tax_accounts), 2),
                "projected_tax": round(sum(item["projected_tax"] for item in property_tax_accounts), 2),
                "unpaid_tax": round(sum(item["unpaid_property_tax"] for item in property_tax_accounts), 2),
                "liens": int(property_enforcement_counts.get("liens") or 0),
                "seizures": int(property_enforcement_counts.get("seizures") or 0),
            },
        }

    def api_create_property_tax(self, db: Database, user: DbRow | None) -> None:
        err = fine_settlement_required(user)
        if err:
            self.error(403 if user else 401, err)
            return
        assert user is not None
        payload = self.read_json()
        property_id = str(payload.get("property_id") or "").strip()
        notes = str(payload.get("notes") or "").strip()[:1000]
        record = one(
            db,
            """SELECT p.*, COALESCE(ra.owner_user_id,l.user_id) AS owner_user_id, u.name AS owner_name
               FROM game_property_records p
               LEFT JOIN realty_property_assignments ra ON ra.property_id = p.property_id
               LEFT JOIN arma_account_links l ON l.identity_id = p.owner_identity OR l.uid = p.owner_identity
               LEFT JOIN users u ON u.id = COALESCE(ra.owner_user_id,l.user_id)
               WHERE p.property_id = ?""",
            (property_id,),
        )
        if not record or not str(record.get("owner_identity") or "").strip():
            self.error(404, "An owned property record is required")
            return
        if "rented" in str(record.get("source_file") or "").lower():
            self.error(409, "Rental tenancies are not taxable ownership records")
            return
        existing = one(db, "SELECT id FROM property_tax_assessments WHERE property_id = ? AND status = 'unpaid'", (property_id,))
        if existing:
            self.error(409, "This property already has an unpaid tax assessment")
            return
        try:
            submitted_rate = float(payload.get("tax_rate") or 0)
        except (TypeError, ValueError):
            submitted_rate = 0
        tax_rate = submitted_rate / 100 if submitted_rate in (12, 14, 18) else submitted_rate
        tax_rate = round(tax_rate, 2)
        if tax_rate not in PROPERTY_TAX_ALLOWED_RATES:
            self.error(400, "Select the authorized 12%, 14%, or 18% property-tax rate")
            return
        assessed_value = PROPERTY_TAX_BASE_VALUE
        amount = round(assessed_value * tax_rate, 2)
        ts = now_iso()
        cursor = db.execute(
            """INSERT INTO property_tax_assessments
               (property_id, owner_identity, owner_user_id, assessed_value, tax_rate, amount, status, notes, assessed_by, assessed_at)
               VALUES (?, ?, ?, ?, ?, ?, 'unpaid', ?, ?, ?) RETURNING id""",
            (property_id, record["owner_identity"], record.get("owner_user_id"), assessed_value, tax_rate, amount, notes, user["id"], ts),
        )
        assessment_id = int(cursor.fetchone()["id"])
        if record.get("owner_user_id"):
            add_message(
                db,
                int(record["owner_user_id"]),
                "Faircroft property tax assessment",
                f"A {int(tax_rate * 100)}% property tax assessment of ${amount:,.2f} was issued for {record.get('name') or property_id} using Faircroft's fixed ${assessed_value:,.2f} property-tax basis. Pay the bill in MyFaircroft with a verified four-digit receipt PIN.",
                int(user["id"]),
            )
        add_admin_audit(db, int(user["id"]), "property.tax.assessed", record.get("owner_user_id"), {
            "assessment_id": assessment_id, "property_id": property_id, "assessed_value": assessed_value, "tax_rate": tax_rate, "amount": amount,
        })
        self.send_json(201, {"ok": True, "assessment_id": assessment_id, "property_id": property_id, "assessed_value": assessed_value, "tax_rate": tax_rate, "amount": amount})

    def api_property_enforcement(self, db: Database, user: DbRow | None) -> None:
        err = fine_settlement_required(user)
        if err:
            self.error(403 if user else 401, err)
            return
        assert user is not None
        payload = self.read_json()
        property_id = str(payload.get("property_id") or "").strip()
        action = str(payload.get("action") or "").strip().lower()
        reason = str(payload.get("reason") or "").strip()[:1000]
        business_id = int(payload.get("business_id") or 0) or None
        if action not in {"lien", "seize", "release"}:
            self.error(400, "Select lien, seize, or release")
            return
        if action != "release" and len(reason) < 10:
            self.error(400, "Enter an enforcement reason of at least 10 characters")
            return
        record = one(db, """SELECT p.*, COALESCE(ra.owner_user_id,l.user_id) AS owner_user_id, u.name AS owner_name
            FROM game_property_records p
            LEFT JOIN realty_property_assignments ra ON ra.property_id=p.property_id
            LEFT JOIN arma_account_links l ON l.identity_id=p.owner_identity OR l.uid=p.owner_identity
            LEFT JOIN users u ON u.id=COALESCE(ra.owner_user_id,l.user_id) WHERE p.property_id=?""", (property_id,))
        if not record or not record.get("owner_identity"):
            self.error(404, "Owned property not found")
            return
        if "rented" in str(record.get("source_file") or "").lower():
            self.error(409, "Rental tenancies cannot receive ownership-tax enforcement")
            return
        latest = one(db, "SELECT action FROM property_enforcement_actions WHERE property_id=? ORDER BY id DESC LIMIT 1", (property_id,))
        current_state = "clear" if not latest or latest["action"] == "release" else str(latest["action"])
        if action == "seize" and current_state != "lien":
            self.error(409, "Place a tax lien before seizing this property")
            return
        if action == "lien" and current_state != "clear":
            self.error(409, f"This property is already under {current_state}")
            return
        if action == "release" and current_state == "clear":
            self.error(409, "This property has no active lien or seizure")
            return
        assessment_id = None
        amount = 0.0
        if business_id:
            business = one(db, """SELECT b.*, COALESCE(SUM(CASE WHEN t.status='unpaid' THEN t.amount ELSE 0 END),0) AS unpaid_tax
                FROM businesses b LEFT JOIN business_tax_assessments t ON t.business_id=b.id
                WHERE b.id=? GROUP BY b.id""", (business_id,))
            if not business or int(business["owner_id"]) != int(record.get("owner_user_id") or 0):
                self.error(409, "The selected property does not belong to this business owner")
                return
            amount = round(float(business.get("unpaid_tax") or 0), 2)
            if action != "release" and amount <= 0:
                self.error(409, "This business has no unpaid tax balance")
                return
        else:
            assessment = one(db, "SELECT id, amount FROM property_tax_assessments WHERE property_id=? AND status='unpaid' ORDER BY id DESC LIMIT 1", (property_id,))
            if assessment:
                assessment_id, amount = int(assessment["id"]), round(float(assessment["amount"] or 0), 2)
            if action != "release" and not assessment:
                self.error(409, "Issue a property tax assessment before enforcement")
                return
        ts = now_iso()
        db.execute(
            """INSERT INTO property_enforcement_actions
               (property_id, owner_identity, owner_user_id, business_id, assessment_id, action, reason, amount, issued_by, created_at)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
            (property_id, record["owner_identity"], record.get("owner_user_id"), business_id, assessment_id, action, reason or "Released by Faircroft Settlement Authority", amount, user["id"], ts),
        )
        if record.get("owner_user_id"):
            add_message(db, int(record["owner_user_id"]), f"Property enforcement: {action}",
                f"Faircroft Settlement Authority recorded a {action} on {record.get('name') or property_id}. Balance cited: ${amount:,.2f}. {reason}".strip(), int(user["id"]))
        add_admin_audit(db, int(user["id"]), f"property.enforcement.{action}", record.get("owner_user_id"), {
            "property_id": property_id, "business_id": business_id, "assessment_id": assessment_id, "amount": amount, "reason": reason,
        })
        self.send_json(200, {"ok": True, "property_id": property_id, "action": action, "previous_state": current_state, "amount": amount})

    def api_settlement_business_license(self, db: Database, user: DbRow | None, business_id: int) -> None:
        err = fine_settlement_required(user)
        if err:
            self.error(403 if user else 401, err)
            return
        assert user is not None
        business = one(
            db,
            """SELECT b.*, owner.name AS owner_name, owner.civ_number AS owner_civ_number,
                      (SELECT COALESCE(SUM(t.amount), 0) FROM business_tax_assessments t
                       WHERE t.business_id = b.id AND t.status = 'unpaid') AS unpaid_tax
               FROM businesses b
               JOIN users owner ON owner.id = b.owner_id
               WHERE b.id = ?""",
            (business_id,),
        )
        if not business:
            self.error(404, "Business license not found")
            return
        payload = self.read_json()
        action = str(payload.get("action") or "").strip().lower()
        reason = str(payload.get("reason") or "").strip()[:1000]
        current_status = str(business["status"] or "active").lower()
        if action not in {"suspend", "revoke", "restore"}:
            self.error(400, "Select suspend, revoke, or restore")
            return
        if action in {"suspend", "revoke"} and len(reason) < 10:
            self.error(400, "Enter an enforcement reason of at least 10 characters")
            return
        if action == "suspend" and current_status != "active":
            self.error(409, "Only an active business license can be suspended")
            return
        if action == "revoke" and current_status == "revoked":
            self.error(409, "This business license is already revoked")
            return
        if action == "restore" and current_status != "suspended":
            self.error(409, "Only a suspended business license can be restored here")
            return

        next_status = {"suspend": "suspended", "revoke": "revoked", "restore": "active"}[action]
        ts = now_iso()
        db.execute("UPDATE businesses SET status = ?, updated_at = ? WHERE id = ?", (next_status, ts, business_id))
        unpaid_tax = round(float(business.get("unpaid_tax") or 0), 2)
        if action in {"suspend", "revoke"}:
            db.execute(
                """INSERT INTO business_violations
                   (business_id, issued_by, severity, violation, penalty, status, created_at)
                   VALUES (?, ?, ?, ?, ?, 'open', ?)""",
                (
                    business_id,
                    user["id"],
                    "tax_enforcement",
                    reason,
                    f"Business license {next_status}; outstanding business tax ${unpaid_tax:,.2f}",
                    ts,
                ),
            )
        title = f"Business license {next_status}"
        body = (
            f"The {business['business_name']} license ({business['license_number']}) is now {next_status}. "
            f"Outstanding business tax: ${unpaid_tax:,.2f}."
            + (f" Reason: {reason}" if reason else " The license was restored by Faircroft Settlement Authority.")
        )
        add_message(db, int(business["owner_id"]), title, body, int(user["id"]))
        add_admin_audit(
            db,
            int(user["id"]),
            f"business.license.{action}",
            int(business["owner_id"]),
            {
                "business_id": business_id,
                "license_number": business["license_number"],
                "previous_status": current_status,
                "status": next_status,
                "unpaid_tax": unpaid_tax,
                "reason": reason,
            },
        )
        self.send_json(
            200,
            {
                "ok": True,
                "business_id": business_id,
                "business_name": business["business_name"],
                "previous_status": current_status,
                "status": next_status,
                "unpaid_tax": unpaid_tax,
            },
        )

    def api_create_settlement_notices(self, db: Database, user: DbRow | None) -> None:
        err = developer_required(user)
        if err:
            self.error(403 if user else 401, err)
            return
        assert user is not None
        payload = self.read_json()
        notice_type = str(payload.get("notice_type") or "").strip().lower()
        presets = {
            "suspension": ("Final notice: driver license suspension", "Failure to resolve your outstanding fines may result in suspension of your Faircroft driver license."),
            "revocation": ("Final notice: driver license revocation", "Continued failure to resolve your outstanding fines may result in revocation of your Faircroft driver license."),
            "warrant": ("Final notice: warrant enforcement", "Failure to pay outstanding fines may result in a warrant for your arrest in the State of Faircroft."),
        }
        if notice_type not in presets:
            self.error(400, "Select a valid settlement warning")
            return
        mode = str(payload.get("recipient_mode") or "individual").strip().lower()
        raw_ids = payload.get("user_ids") if isinstance(payload.get("user_ids"), list) else []
        try:
            selected_ids = list(dict.fromkeys(int(value) for value in raw_ids))
        except (TypeError, ValueError):
            self.error(400, "Select valid resident accounts")
            return
        accounts = self.fine_settlement_payload(db)["outstanding_accounts"]
        eligible = {int(item["user_id"]): item for item in accounts}
        recipient_ids = list(eligible) if mode == "bulk" else [item for item in selected_ids if item in eligible]
        if not recipient_ids:
            self.error(400, "No residents with outstanding fines were selected")
            return
        subject, warning = presets[notice_type]
        custom_note = str(payload.get("custom_note") or "").strip()[:800]
        ts = now_iso()
        for recipient_id in recipient_ids:
            account = eligible[recipient_id]
            body = (
                f"{warning} Your account currently shows {int(account['outstanding_count'])} outstanding filing(s) totaling ${float(account['outstanding_total']):,.2f}. "
                "Open MyFaircroft to review the balance. Pay the authorized staff member in game first; the four-digit receipt PIN must not be issued until payment is received."
                + (f" Official note: {custom_note}" if custom_note else "")
            )
            db.execute(
                """INSERT INTO settlement_notices
                   (user_id, notice_type, subject, body, outstanding_count, outstanding_total, created_by, created_at)
                   VALUES (?, ?, ?, ?, ?, ?, ?, ?)""",
                (recipient_id, notice_type, subject, body, int(account["outstanding_count"]), float(account["outstanding_total"]), user["id"], ts),
            )
            add_message(db, recipient_id, subject, body, user["id"])
        add_admin_audit(db, int(user["id"]), "settlement.notices.sent", None, {"notice_type": notice_type, "recipient_mode": mode, "recipient_count": len(recipient_ids)})
        self.send_json(201, {"ok": True, "recipient_count": len(recipient_ids), "notice_type": notice_type})

    def api_fine_settlement(self, db: Database, user: DbRow | None) -> None:
        err = fine_settlement_required(user)
        if err:
            self.error(403 if user else 401, err)
            return
        self.send_json(200, self.fine_settlement_payload(db))

    def api_create_fine_settlement_batch(self, db: Database, user: DbRow | None) -> None:
        err = fine_settlement_required(user)
        if err:
            self.error(403 if user else 401, err)
            return
        payload = self.read_json()
        raw_ids = payload.get("citation_ids")
        if not isinstance(raw_ids, list) or not raw_ids:
            self.error(400, "Select at least one unpaid fine")
            return
        citation_ids = list(dict.fromkeys(int(value) for value in raw_ids))[:100]
        placeholders = ",".join("?" for _ in citation_ids)
        rows = all_rows(
            db,
            f"""
            SELECT c.id, c.civ_id, c.fine_amount, c.status, l.identity_id, b.balance
            FROM citations c
            JOIN arma_account_links l ON l.user_id = c.civ_id
            JOIN arma_game_bank_balances b ON b.identity_id = l.identity_id
            LEFT JOIN fine_settlement_items i ON i.citation_id = c.id
            WHERE c.id IN ({placeholders})
              AND c.status IN ('issued', 'reviewed', 'reduced', 'closed') AND i.id IS NULL
              AND COALESCE(c.disposition, '') NOT IN ('not_guilty', 'dismissed')
              AND b.balance >= c.fine_amount
            """,
            tuple(citation_ids),
        )
        if len(rows) != len(citation_ids):
            self.error(409, "Every selected fine must be unpaid, unbatched, linked, and have a synced game balance")
            return
        created_at = utcnow()
        batch_number = f"DCJS-{created_at.strftime('%Y%m%d')}-{secrets.randbelow(900000) + 100000}"
        batch = db.execute(
            """
            INSERT INTO fine_settlement_batches (batch_number, created_by, created_at, notes)
            VALUES (?, ?, ?, ?) RETURNING id
            """,
            (batch_number, user["id"], created_at.isoformat(), str(payload.get("notes") or "").strip()[:2000]),
        ).fetchone()
        for row in rows:
            fine = round(float(row["fine_amount"]), 2)
            before = round(float(row["balance"]), 2)
            db.execute(
                """
                INSERT INTO fine_settlement_items
                (batch_id, citation_id, user_id, identity_id, fine_amount, balance_before, expected_balance)
                VALUES (?, ?, ?, ?, ?, ?, ?)
                """,
                (batch["id"], row["id"], row["civ_id"], row["identity_id"], fine, before, round(before - fine, 2)),
            )
        add_admin_audit(db, int(user["id"]), "fine_settlement.batch.created", details={"batch_number": batch_number, "citation_ids": citation_ids})
        self.send_json(201, {"ok": True, "batch_id": int(batch["id"]), "batch_number": batch_number})

    def api_fine_settlement_code(self, db: Database, user: DbRow | None, batch_id: int) -> None:
        err = fine_settlement_required(user)
        if err:
            self.error(403 if user else 401, err)
            return
        batch = one(db, "SELECT * FROM fine_settlement_batches WHERE id = ?", (batch_id,))
        if not batch:
            self.error(404, "Settlement batch not found")
            return
        if batch["status"] != "draft":
            self.error(409, "Only a draft batch can receive a new approval code")
            return
        alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"
        raw_code = "DCJS-" + "".join(secrets.choice(alphabet) for _ in range(8))
        expires_at = (utcnow() + dt.timedelta(minutes=10)).isoformat()
        db.execute(
            "UPDATE fine_settlement_batches SET approval_code_hash = ?, approval_code_hint = ?, approval_expires_at = ? WHERE id = ?",
            (hash_password(raw_code), raw_code[-4:], expires_at, batch_id),
        )
        add_admin_audit(db, int(user["id"]), "fine_settlement.code.created", details={"batch_id": batch_id, "hint": raw_code[-4:]})
        self.send_json(201, {"ok": True, "code": raw_code, "expires_at": expires_at})

    def api_suspend_fine_batch_licenses(self, db: Database, user: DbRow | None, batch_id: int) -> None:
        err = fine_settlement_required(user)
        if err:
            self.error(403 if user else 401, err)
            return
        batch = one(db, "SELECT * FROM fine_settlement_batches WHERE id = ?", (batch_id,))
        if not batch:
            self.error(404, "Settlement batch not found")
            return
        if batch["status"] != "draft":
            self.error(409, "Licenses can only be suspended while the batch is awaiting authorization")
            return
        targets = all_rows(
            db,
            """
            SELECT DISTINCT i.user_id, u.name, u.civ_number,
                   COALESCE(d.license_status, 'No license') AS license_status
            FROM fine_settlement_items i
            JOIN users u ON u.id = i.user_id
            LEFT JOIN dmv_records d ON d.user_id = i.user_id
            WHERE i.batch_id = ?
            ORDER BY u.name
            """,
            (batch_id,),
        )
        if not targets:
            self.error(409, "Settlement batch has no players")
            return
        suspended_at = now_iso()
        results: list[dict[str, Any]] = []
        for target in targets:
            if not one(db, "SELECT id FROM dmv_records WHERE user_id = ?", (target["user_id"],)):
                create_default_dmv(db, int(target["user_id"]))
            previous = str(target["license_status"] or "No license")
            db.execute(
                "UPDATE dmv_records SET license_status = 'Suspended', updated_at = ? WHERE user_id = ?",
                (suspended_at, target["user_id"]),
            )
            reason = f"Failure to pay fines in settlement batch {batch['batch_number']}."
            add_message(
                db,
                int(target["user_id"]),
                "Driver license suspended for unpaid fines",
                f"Your Faircroft driver license has been suspended for failure to pay outstanding fines. "
                f"Reference: {batch['batch_number']}. Resolve the listed fines before requesting reinstatement.",
                int(user["id"]),
            )
            results.append({
                "user_id": int(target["user_id"]),
                "name": target["name"],
                "civ_number": target["civ_number"],
                "previous_status": previous,
                "license_status": "Suspended",
                "reason": reason,
            })
        add_admin_audit(
            db,
            int(user["id"]),
            "fine_settlement.licenses.batch_suspended",
            details={"batch_id": batch_id, "batch_number": batch["batch_number"], "players": results},
        )
        self.send_json(200, {"ok": True, "batch_number": batch["batch_number"], "suspended": results})

    def api_approve_fine_settlement(self, db: Database, user: DbRow | None, batch_id: int) -> None:
        err = fine_settlement_required(user)
        if err:
            self.error(403 if user else 401, err)
            return
        payload = self.read_json()
        batch = one(db, "SELECT * FROM fine_settlement_batches WHERE id = ?", (batch_id,))
        code = str(payload.get("code") or "").strip().upper()
        if not batch or batch["status"] != "draft":
            self.error(409, "Settlement batch is not awaiting approval")
            return
        unsuspended = all_rows(
            db,
            """
            SELECT DISTINCT u.name
            FROM fine_settlement_items i
            JOIN users u ON u.id = i.user_id
            LEFT JOIN dmv_records d ON d.user_id = i.user_id
            WHERE i.batch_id = ? AND COALESCE(d.license_status, '') != 'Suspended'
            """,
            (batch_id,),
        )
        if unsuspended:
            self.error(409, "Suspend every affected driver license before authorizing forced fine removal")
            return
        if not batch["approval_code_hash"] or not verify_password(code, batch["approval_code_hash"]):
            self.error(403, "Invalid settlement authorization code")
            return
        if not batch["approval_expires_at"] or dt.datetime.fromisoformat(batch["approval_expires_at"]) <= utcnow():
            self.error(403, "Settlement authorization code has expired")
            return
        approved_at = now_iso()
        db.execute(
            """
            UPDATE fine_settlement_batches
            SET status = 'awaiting_codex', approved_by = ?, approved_at = ?,
                processing_started_at = ?, approval_code_hash = ''
            WHERE id = ?
            """,
            (user["id"], approved_at, approved_at, batch_id),
        )
        prompt = (
            f"Process approved DCJS fine settlement batch {batch['batch_number']} (database batch ID {batch_id}). "
            "Use the signed-in Shadowhaven panel and configured SFTP access. Stop the Arma server manually, "
            "wait the full 120 seconds, confirm it is offline, then edit only the matching live FCRPMUSSALO/Banks "
            "JSON balances to the locked expected values shown in Fine Settlement. Do not create a backup. "
            "Start the server, wait for Railway bank sync, then use Verify synced balances in the Fine Settlement app. "
            "Never mark fines paid unless every actual synced balance matches its expected value."
        )
        add_admin_audit(db, int(user["id"]), "fine_settlement.batch.approved", details={"batch_id": batch_id})
        self.send_json(200, {"ok": True, "codex_prompt": prompt})

    def api_complete_fine_settlement(self, db: Database, user: DbRow | None, batch_id: int) -> None:
        err = fine_settlement_required(user)
        if err:
            self.error(403 if user else 401, err)
            return
        batch = one(db, "SELECT * FROM fine_settlement_batches WHERE id = ?", (batch_id,))
        if not batch or batch["status"] not in ("awaiting_codex", "needs_review"):
            self.error(409, "Batch is not ready for balance verification")
            return
        items = all_rows(db, "SELECT * FROM fine_settlement_items WHERE batch_id = ?", (batch_id,))
        paid = 0
        for item in items:
            if item["status"] == "paid":
                paid += 1
                continue
            bank = one(db, "SELECT balance FROM arma_game_bank_balances WHERE identity_id = ?", (item["identity_id"],))
            actual = round(float(bank["balance"]), 2) if bank else None
            expected = round(float(item["expected_balance"]), 2)
            if actual is not None and abs(actual - expected) <= 0.01:
                verified_at = now_iso()
                court_case = one(db, "SELECT final_result, disposition FROM citations WHERE id = ?", (item["citation_id"],))
                paid_result = final_result_for("paid", f"Settled through {batch['batch_number']}", float(item["fine_amount"]))
                if court_case and court_case.get("final_result") and court_case.get("disposition"):
                    paid_result = f"{court_case['final_result']} | Fine satisfied through {batch['batch_number']}"
                db.execute(
                    "UPDATE fine_settlement_items SET status = 'paid', verified_balance = ?, verified_at = ?, failure_reason = '' WHERE id = ?",
                    (actual, verified_at, item["id"]),
                )
                db.execute(
                    "UPDATE citations SET status = 'paid', final_result = ?, updated_at = ? WHERE id = ?",
                    (paid_result, verified_at, item["citation_id"]),
                )
                add_transaction(
                    db, int(item["user_id"]), "dcjs_fine_settlement", -float(item["fine_amount"]),
                    f"State of Faircroft DCJS · Fine settlement · Case {item['citation_id']} · Batch {batch['batch_number']}",
                )
                paid += 1
            else:
                reason = "Live bank balance has not synced" if actual is None else f"Expected {expected:.2f}; synced {actual:.2f}"
                db.execute(
                    "UPDATE fine_settlement_items SET status = 'needs_review', verified_balance = ?, verified_at = ?, failure_reason = ? WHERE id = ?",
                    (actual, now_iso(), reason, item["id"]),
                )
        status = "completed" if paid == len(items) else "needs_review"
        db.execute(
            "UPDATE fine_settlement_batches SET status = ?, completed_at = ? WHERE id = ?",
            (status, now_iso() if status == "completed" else None, batch_id),
        )
        add_admin_audit(db, int(user["id"]), "fine_settlement.batch.verified", details={"batch_id": batch_id, "paid": paid, "total": len(items), "status": status})
        self.send_json(200, {"ok": status == "completed", "status": status, "paid": paid, "total": len(items)})

    def api_create_tax_settlement_batch(self, db: Database, user: DbRow | None) -> None:
        err = fine_settlement_required(user)
        if err:
            self.error(403 if user else 401, err)
            return
        payload = self.read_json()
        raw_ids = payload.get("business_ids")
        if not isinstance(raw_ids, list) or not raw_ids:
            self.error(400, "Select at least one business tax account")
            return
        business_ids = list(dict.fromkeys(int(value) for value in raw_ids))[:100]
        placeholders = ",".join("?" for _ in business_ids)
        rows = all_rows(
            db,
            f"""
            SELECT b.id AS business_id, b.owner_id, l.identity_id, bank.balance, SUM(t.amount) AS tax_amount
            FROM businesses b
            JOIN business_tax_assessments t ON t.business_id = b.id
            JOIN arma_account_links l ON l.user_id = b.owner_id
            JOIN arma_game_bank_balances bank ON bank.identity_id = l.identity_id
            WHERE b.id IN ({placeholders}) AND t.status = 'unpaid' AND t.settlement_batch_id IS NULL
            GROUP BY b.id, b.owner_id, l.identity_id, bank.balance
            HAVING bank.balance >= SUM(t.amount)
            """,
            tuple(business_ids),
        )
        if len(rows) != len(business_ids):
            self.error(409, "Every business must have unpaid taxes, a linked owner, and sufficient synced game funds")
            return
        identities = [str(row["identity_id"]) for row in rows]
        if len(set(identities)) != len(identities):
            self.error(409, "Select only one business per Arma account in each batch")
            return
        created_at = utcnow()
        batch_number = f"DCJS-TAX-{created_at.strftime('%Y%m%d')}-{secrets.randbelow(900000) + 100000}"
        batch = db.execute(
            "INSERT INTO business_tax_settlement_batches (batch_number, created_by, created_at, notes) VALUES (?, ?, ?, ?) RETURNING id",
            (batch_number, user["id"], created_at.isoformat(), str(payload.get("notes") or "").strip()[:2000]),
        ).fetchone()
        for row in rows:
            amount = round(float(row["tax_amount"]), 2)
            before = round(float(row["balance"]), 2)
            db.execute(
                """
                INSERT INTO business_tax_settlement_items
                (batch_id, business_id, user_id, identity_id, tax_amount, balance_before, expected_balance)
                VALUES (?, ?, ?, ?, ?, ?, ?)
                """,
                (batch["id"], row["business_id"], row["owner_id"], row["identity_id"], amount, before, round(before - amount, 2)),
            )
            db.execute(
                """
                UPDATE business_tax_assessments SET settlement_batch_id = ?
                WHERE business_id = ? AND status = 'unpaid' AND settlement_batch_id IS NULL
                """,
                (batch["id"], row["business_id"]),
            )
        add_admin_audit(db, int(user["id"]), "business_tax.batch.created", details={"batch_number": batch_number, "business_ids": business_ids})
        self.send_json(201, {"ok": True, "batch_id": int(batch["id"]), "batch_number": batch_number})

